STANDARD_DEDUCTION = 10000.0
FEDERAL_TAX_RATE = 0.20
STATE_TAX_RATE = 0.05
MEDICARE_RATE = 0.015
SOCIAL_SECURITY_RATE = 0.06
SOCIAL_SECURITY_WAGE_CAP = 100000.0
CURRENCY_PRECISION = 2


def taxable_income(salary):
    """Income subject to federal and state tax, never below zero."""
    return max(0.0, salary - STANDARD_DEDUCTION)


def federal_tax(salary):
    return taxable_income(salary) * FEDERAL_TAX_RATE


def state_tax(salary):
    return taxable_income(salary) * STATE_TAX_RATE


def medicare_tax(salary):
    return salary * MEDICARE_RATE


def social_security_tax(salary):
    return min(salary, SOCIAL_SECURITY_WAGE_CAP) * SOCIAL_SECURITY_RATE


def validate(salaries):
    """Return the salaries as floats, rejecting non-numeric or negative input."""
    clean = []
    for index, salary in enumerate(salaries):
        if isinstance(salary, bool) or not isinstance(salary, (int, float)):
            raise TypeError("salary at position %d is not a number" % index)
        if salary < 0:
            raise ValueError("salary at position %d is negative" % index)
        clean.append(float(salary))
    return clean


def payroll(salaries):
    """Total tax owed for each salary in the list."""
    totals = []
    for salary in validate(salaries):
        total = (
            federal_tax(salary)
            + state_tax(salary)
            + medicare_tax(salary)
            + social_security_tax(salary)
        )
        totals.append(round(total, CURRENCY_PRECISION))
    return totals


def breakdown_report(salaries):
    """Human-readable per-salary breakdown of the four taxes."""
    lines = []
    for salary in validate(salaries):
        capped = min(salary, SOCIAL_SECURITY_WAGE_CAP)
        lines.append(
            "salary {:>10,.2f} | taxable {:>10,.2f} | fed {:>9,.2f} | "
            "state {:>8,.2f} | medicare {:>8,.2f} | ss base {:>10,.2f} | "
            "ss {:>8,.2f}".format(
                salary,
                taxable_income(salary),
                federal_tax(salary),
                state_tax(salary),
                medicare_tax(salary),
                capped,
                social_security_tax(salary),
            )
        )
    return "\n".join(lines)


def main():
    sample = [100000, 8000, 250000, 45000.50]
    print(breakdown_report(sample))
    print("totals:", payroll(sample))
    effective = [
        round(tax / salary * 100.0, CURRENCY_PRECISION)
        for tax, salary in zip(payroll(sample), sample)
    ]
    print("effective rates (%):", effective)
    print("deduction applied per salary:", STANDARD_DEDUCTION)


if __name__ == "__main__":
    main()

