MAX_RETRIES = 3
DEFAULT_TIMEOUT = 200
BACKOFF_MULTIPLIER = 2
MAX_TIMEOUT = 800
CONNECTION_OVERHEAD = 50
MIN_RESPONSE_TIME = 0
FAILURE_CODE = -1


def retry_timeouts():
    """Yield the timeout used by each successive attempt of a single request."""
    timeout = DEFAULT_TIMEOUT
    for _ in range(MAX_RETRIES):
        yield timeout
        timeout = min(timeout * BACKOFF_MULTIPLIER, MAX_TIMEOUT)


def check_response_time(response_time):
    """Reject values that cannot describe a measured response time."""
    if isinstance(response_time, bool) or not isinstance(response_time, int):
        raise TypeError("response times must be integers, got %r" % (response_time,))
    if response_time < MIN_RESPONSE_TIME:
        raise ValueError("response time must be at least %d ms" % MIN_RESPONSE_TIME)


def simulate_request(response_time):
    """Return (consumed time, attempt number) for one request."""
    check_response_time(response_time)
    for attempt, timeout in enumerate(retry_timeouts(), start=1):
        if response_time <= timeout:
            return response_time + CONNECTION_OVERHEAD, attempt
    return FAILURE_CODE, MAX_RETRIES


def latency(requests):
    """Total consumed time per request, or -1 when every retry is exhausted."""
    return [simulate_request(response_time)[0] for response_time in requests]


def format_report(requests):
    """Human readable summary of how each request behaved under retrying."""
    lines = []
    for response_time in requests:
        consumed, attempts = simulate_request(response_time)
        if consumed == FAILURE_CODE:
            lines.append(
                "%5d ms -> failed: exceeded the %d ms timeout cap on all %d attempts"
                % (response_time, MAX_TIMEOUT, MAX_RETRIES)
            )
        else:
            lines.append(
                "%5d ms -> %5d ms consumed on attempt %d of %d"
                % (response_time, consumed, attempts, MAX_RETRIES)
            )
    return "\n".join(lines)


def main():
    samples = [500, MIN_RESPONSE_TIME, 150, DEFAULT_TIMEOUT, MAX_TIMEOUT, 1200]
    print("timeouts:", list(retry_timeouts()))
    print("latency:", latency(samples))
    print(format_report(samples))
    slowest_ok = MAX_TIMEOUT + CONNECTION_OVERHEAD
    print("worst successful cost: %d ms" % slowest_ok)


if __name__ == "__main__":
    main()

