import sys

MIN_LEVEL = 1
MAX_LEVEL = 99
BASE_HEALTH = 100
BASE_MANA = 50
HEALTH_PER_LEVEL = 20
MANA_PER_LEVEL = 10
BOSS_BONUS_HEALTH = 500
TRUE_WORDS = ("true", "yes", "1")
FALSE_WORDS = ("false", "no", "0")


def cap_level(level):
    """Clamp a raw level into the legal range, rejecting nonsense input."""
    if not isinstance(level, int) or isinstance(level, bool):
        raise TypeError("level must be an int, got %r" % (level,))
    if level < MIN_LEVEL:
        raise ValueError("level must be at least %d, got %d" % (MIN_LEVEL, level))
    return min(level, MAX_LEVEL)


def stats(characters):
    """Return [(health, mana), ...] for [(level, boss_defeated), ...]."""
    result = []
    for level, boss_defeated in characters:
        capped = cap_level(level)
        health = BASE_HEALTH + capped * HEALTH_PER_LEVEL
        mana = BASE_MANA + capped * MANA_PER_LEVEL
        if boss_defeated:
            health += BOSS_BONUS_HEALTH
        result.append((health, mana))
    return result


def max_health():
    """Highest health any character can reach under the balance rules."""
    return BASE_HEALTH + MAX_LEVEL * HEALTH_PER_LEVEL + BOSS_BONUS_HEALTH


def max_mana():
    return BASE_MANA + MAX_LEVEL * MANA_PER_LEVEL


def parse_character(text):
    """Parse a line like '5 true' into (5, True)."""
    fields = text.replace(",", " ").split()
    if len(fields) != 2:
        raise ValueError("expected 'level flag', got %r" % (text,))
    flag = fields[1].strip().lower()
    if flag in TRUE_WORDS:
        boss_defeated = True
    elif flag in FALSE_WORDS:
        boss_defeated = False
    else:
        raise ValueError("unrecognised boss flag %r" % (fields[1],))
    return (int(fields[0]), boss_defeated)


def format_report(characters, results):
    lines = []
    for (level, boss_defeated), (health, mana) in zip(characters, results):
        if level > MAX_LEVEL:
            shown = "%d (capped to %d)" % (level, MAX_LEVEL)
        else:
            shown = str(level)
        lines.append(
            "level %s boss=%s -> HP %d (%.1f%% of cap), MP %d (%.1f%% of cap)"
            % (shown, boss_defeated, health, 100.0 * health / max_health(),
               mana, 100.0 * mana / max_mana())
        )
    return "\n".join(lines)


def main():
    characters = [parse_character(line) for line in sys.stdin if line.strip()]
    if not characters:
        characters = [(1, False), (5, True)]
    print(stats(characters))
    print(format_report(characters, stats(characters)))


if __name__ == "__main__":
    main()

