import sys
import time

BASE_RATE = 5.0
PER_POUND_RATE = 1.5
HEAVY_THRESHOLD = 20.0
HEAVY_PENALTY = 10.0
FREE_SHIPPING_MINIMUM = 100.0
MAX_RETRIES = 3
DEFAULT_TIMEOUT = 5.0
RETRY_BACKOFF_SECONDS = 0.5


def shipping(carts):
    """Return the delivery fee for each (total_price, total_weight) cart."""
    costs = []
    for price, weight in carts:
        if price >= FREE_SHIPPING_MINIMUM:
            costs.append(0)
            continue
        cost = BASE_RATE + weight * PER_POUND_RATE
        if weight > HEAVY_THRESHOLD:
            cost += HEAVY_PENALTY
        costs.append(cost)
    return costs


def parse_carts(lines):
    """Parse 'price, weight' records, ignoring blank and commented lines."""
    carts = []
    for number, raw in enumerate(lines, start=1):
        text = raw.split("#", 1)[0].strip()
        if not text:
            continue
        fields = text.split(",")
        if len(fields) != 2:
            raise ValueError(f"line {number}: expected 'price, weight', got {text!r}")
        try:
            price, weight = (float(field) for field in fields)
        except ValueError:
            raise ValueError(f"line {number}: non-numeric value in {text!r}") from None
        if price < 0 or weight < 0:
            raise ValueError(f"line {number}: price and weight must not be negative")
        carts.append((price, weight))
    return carts


def load_carts(path, timeout=DEFAULT_TIMEOUT):
    """Read cart records from a file, retrying transient I/O failures."""
    deadline = time.monotonic() + timeout
    attempt = 0
    last_error = None
    while attempt < MAX_RETRIES:
        attempt += 1
        try:
            with open(path, encoding="utf-8") as handle:
                return parse_carts(handle)
        except OSError as error:
            last_error = error
            if attempt == MAX_RETRIES or time.monotonic() >= deadline:
                break
            time.sleep(RETRY_BACKOFF_SECONDS)
    raise RuntimeError(f"could not read {path} after {attempt} attempt(s): {last_error}")


def format_report(carts, costs):
    """Render one aligned report line per cart, with free/heavy annotations."""
    lines = []
    for (price, weight), cost in zip(carts, costs):
        notes = []
        if price >= FREE_SHIPPING_MINIMUM:
            notes.append("free shipping")
        if weight > HEAVY_THRESHOLD:
            notes.append("heavy package")
        suffix = "  (" + ", ".join(notes) + ")" if notes else ""
        lines.append(f"${price:>8.2f} {weight:>6.1f} lb -> ${cost:>7.2f}{suffix}")
    return "\n".join(lines)


def main(argv):
    if len(argv) != 2:
        print(f"usage: {argv[0]} CARTS_FILE", file=sys.stderr)
        return 2
    try:
        carts = load_carts(argv[1])
    except (RuntimeError, ValueError) as error:
        print(f"error: {error}", file=sys.stderr)
        return 1
    print(format_report(carts, shipping(carts)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

