BILL_HUNDRED = 100
BILL_FIFTY = 50
BILL_TWENTY = 20
SINGLE_WITHDRAWAL_LIMIT = 500
DAILY_WITHDRAWAL_LIMIT = 1000
MIN_DISPENSE_AMOUNT = 20
REJECTED = ()


def _decompose(amount):
    """Split amount into (hundreds, fifties, twenties), maximising larger bills."""
    for hundreds in range(amount // BILL_HUNDRED, -1, -1):
        rest = amount - hundreds * BILL_HUNDRED
        for fifties in range(rest // BILL_FIFTY, -1, -1):
            remainder = rest - fifties * BILL_FIFTY
            if remainder % BILL_TWENTY == 0:
                return (hundreds, fifties, remainder // BILL_TWENTY)
    return REJECTED


def _plan(amount, dispensed_total):
    """Validate a single request against the machine limits and decompose it."""
    if not isinstance(amount, int) or isinstance(amount, bool):
        return REJECTED
    if amount < MIN_DISPENSE_AMOUNT:
        return REJECTED
    if amount > SINGLE_WITHDRAWAL_LIMIT:
        return REJECTED
    if dispensed_total + amount > DAILY_WITHDRAWAL_LIMIT:
        return REJECTED
    return _decompose(amount)


def withdraw(amounts):
    """Process requested withdrawals sequentially, returning bill counts per request."""
    results = []
    dispensed_total = 0
    for amount in amounts:
        bills = _plan(amount, dispensed_total)
        if bills:
            dispensed_total += amount
        results.append(bills)
    return results


def format_receipt(amount, bills):
    if not bills:
        return "{:>4}: rejected".format(amount)
    hundreds, fifties, twenties = bills
    parts = []
    if hundreds:
        parts.append("{} x {}".format(hundreds, BILL_HUNDRED))
    if fifties:
        parts.append("{} x {}".format(fifties, BILL_FIFTY))
    if twenties:
        parts.append("{} x {}".format(twenties, BILL_TWENTY))
    return "{:>4}: ".format(amount) + ", ".join(parts)


def main():
    requests = [170, 30, 110, 500, 480, 300, 520]
    plans = withdraw(requests)
    for amount, bills in zip(requests, plans):
        print(format_receipt(amount, bills))
    total = sum(amount for amount, bills in zip(requests, plans) if bills)
    print("dispensed {} of {}".format(total, DAILY_WITHDRAWAL_LIMIT))
    print("remaining today: {}".format(DAILY_WITHDRAWAL_LIMIT - total))
    print(withdraw([170, 30]))


if __name__ == "__main__":
    main()

