GROUND_FLOOR = 0
TRAVEL_SECONDS_PER_FLOOR = 3
DOOR_OPEN_SECONDS = 2
DOOR_CLOSE_SECONDS = 2
BOARDING_SECONDS = 5
MAX_CAPACITY = 10
SECONDS_PER_MINUTE = 60


def _validate_request(request):
    """Return (passengers, floor) after checking a single request tuple."""
    if len(request) != 2:
        raise ValueError("each request must be a (passengers, floor) pair")
    passengers, floor = request
    if not isinstance(passengers, int) or not isinstance(floor, int):
        raise TypeError("passengers and floor must be integers")
    if passengers < 0:
        raise ValueError("passenger count cannot be negative")
    if floor < GROUND_FLOOR:
        raise ValueError("destination floor cannot be below floor %d" % GROUND_FLOOR)
    return passengers, floor


def trips_needed(passengers):
    """Number of full-capacity trips required to move all passengers."""
    return -(-passengers // MAX_CAPACITY)


def travel_seconds(floor):
    """One-way travel time between the ground floor and the given floor."""
    return (floor - GROUND_FLOOR) * TRAVEL_SECONDS_PER_FLOOR


def stop_seconds():
    """Time spent standing still at one end of a trip."""
    door_cycle = DOOR_OPEN_SECONDS + DOOR_CLOSE_SECONDS
    return door_cycle + BOARDING_SECONDS


def round_trip_seconds(floor):
    """Ground floor -> destination -> ground floor, with a stop at each end."""
    return 2 * travel_seconds(floor) + 2 * stop_seconds()


def elevator(requests):
    """Estimate, per request, the seconds needed to carry the passengers."""
    totals = []
    for request in requests:
        passengers, floor = _validate_request(request)
        trips = trips_needed(passengers)
        if trips == 0:
            totals.append(0)
            continue
        total = trips * round_trip_seconds(floor) - travel_seconds(floor)
        totals.append(total)
    return totals


def format_report(requests, totals):
    """Build one human readable line per request."""
    lines = []
    for (passengers, floor), seconds in zip(requests, totals):
        minutes, remainder = divmod(seconds, SECONDS_PER_MINUTE)
        trips = trips_needed(passengers)
        lines.append(
            "%2d passengers to floor %2d: %3d s (%dm %02ds) in %d trip(s)"
            % (passengers, floor, seconds, minutes, remainder, trips)
        )
    return lines


def main():
    requests = [(5, 3), (10, 1), (23, 5), (0, 7), (17, GROUND_FLOOR)]
    totals = elevator(requests)
    print(totals)
    for line in format_report(requests, totals):
        print(line)


if __name__ == "__main__":
    main()

