DAILY_RATE = 40.0
INSURANCE_RATE = 15.0
PREMIUM_SURCHARGE = 20.0
FREE_MILES_PER_DAY = 100
EXTRA_MILE_CHARGE = 0.5
TAX_RATE = 0.10
CURRENCY_PRECISION = 2
CURRENCY_SYMBOL = "$"
REPORT_WIDTH = 44


def validate_rental(record):
    """Unpack one rental tuple, raising ValueError on bad input."""
    try:
        days, miles, premium = record
    except (TypeError, ValueError):
        raise ValueError("each rental must be (days, miles, premium)")
    if not isinstance(days, int) or days <= 0:
        raise ValueError("days rented must be a positive integer: %r" % (days,))
    if miles < 0:
        raise ValueError("miles driven cannot be negative: %r" % (miles,))
    return days, float(miles), bool(premium)


def base_cost(days, premium):
    """Daily rental plus insurance, with the premium class surcharge."""
    per_day = DAILY_RATE + INSURANCE_RATE
    if premium:
        per_day += PREMIUM_SURCHARGE
    return days * per_day


def mileage_charge(days, miles):
    """Charge for the miles driven beyond the free allowance."""
    allowance = days * FREE_MILES_PER_DAY
    if miles <= allowance:
        return 0.0
    return (miles - allowance) * EXTRA_MILE_CHARGE


def rental(rentals):
    """Return the final taxed bill for every rental in the list."""
    bills = []
    for record in rentals:
        days, miles, premium = validate_rental(record)
        subtotal = base_cost(days, premium) + mileage_charge(days, miles)
        bills.append(round(subtotal * (1.0 + TAX_RATE), CURRENCY_PRECISION))
    return bills


def format_bill(amount):
    return "%s%.*f" % (CURRENCY_SYMBOL, CURRENCY_PRECISION, amount)


def report(rentals):
    """Build a human readable billing summary for the given rentals."""
    bills = rental(rentals)
    lines = ["RENTAL BILLING".center(REPORT_WIDTH), "-" * REPORT_WIDTH]
    for (days, miles, premium), amount in zip(rentals, bills):
        label = "%d day(s), %g mi%s" % (days, miles, ", premium" if premium else "")
        lines.append(label.ljust(REPORT_WIDTH - 12) + format_bill(amount).rjust(12))
    lines.append("-" * REPORT_WIDTH)
    total = round(sum(bills), CURRENCY_PRECISION)
    lines.append("TOTAL".ljust(REPORT_WIDTH - 12) + format_bill(total).rjust(12))
    return "\n".join(lines)


def main():
    fleet = [(2, 250, False), (1, 80, True), (5, 600, True), (3, 300, False)]
    print(report(fleet))
    print("bills:", rental(fleet))


if __name__ == "__main__":
