BYTES_PER_KILOBYTE = 1024
BYTES_PER_MEGABYTE = 1048576
MAX_STORAGE_QUOTA_MB = 5
WARNING_THRESHOLD_MB = MAX_STORAGE_QUOTA_MB * 0.8
MAX_FILE_SIZE_MB = 2


def to_megabytes(size_bytes):
    """Convert a raw byte count into megabytes."""
    return size_bytes / BYTES_PER_MEGABYTE


def format_size(size_bytes):
    """Render a byte count with the largest sensible binary unit."""
    if size_bytes < BYTES_PER_MEGABYTE:
        return "{:.2f} KB".format(size_bytes / BYTES_PER_KILOBYTE)
    return "{:.2f} MB".format(to_megabytes(size_bytes))


def validate_files(files):
    """Return the file sizes as a list, rejecting anything that is not a byte count."""
    checked = []
    for position, size in enumerate(files):
        if isinstance(size, bool) or not isinstance(size, int):
            raise TypeError("file size at index {} is not an integer".format(position))
        if size < 0:
            raise ValueError("file size at index {} is negative".format(position))
        checked.append(size)
    return checked


def storage(files):
    """Accumulate file sizes in megabytes under the per-file and quota limits."""
    total = 0.0
    for size in validate_files(files):
        size_mb = to_megabytes(size)
        if size_mb > MAX_FILE_SIZE_MB:
            continue
        total += size_mb
        if total > MAX_STORAGE_QUOTA_MB:
            total = MAX_STORAGE_QUOTA_MB
            break
    return (total, total >= WARNING_THRESHOLD_MB)


def report(files):
    """Build human readable lines describing how a batch of files is handled."""
    lines = []
    for size in validate_files(files):
        if to_megabytes(size) > MAX_FILE_SIZE_MB:
            lines.append("skipped  {} (above the {} MB per-file limit)".format(
                format_size(size), MAX_FILE_SIZE_MB))
        else:
            lines.append("accepted {}".format(format_size(size)))
    total, warned = storage(files)
    lines.append("total    {:.2f} MB of a {} MB quota".format(total, MAX_STORAGE_QUOTA_MB))
    if warned:
        lines.append("WARNING  usage reached the {:.2f} MB threshold".format(WARNING_THRESHOLD_MB))
    return lines


def main():
    batches = [
        [1048576],
        [524288, 3145728, 1048576, 2097152],
        [2097152, 2097152, 2097152, 1048576],
    ]
    for index, batch in enumerate(batches, start=1):
        print("batch {}".format(index))
        for line in report(batch):
            print("  " + line)
        print("  result {}".format(storage(batch)))


if __name__ == "__main__":
    main()

