MAX_CAPACITY = 5000
FAST_CHARGE_RATE = 50
TRICKLE_CHARGE_RATE = 10
FAST_CHARGE_THRESHOLD = 4000
IDLE_DRAIN_RATE = 5
EMPTY_CAPACITY = 0
PERCENT_SCALE = 100


def _validate_event(event):
    """Unpack and check a single (minutes, plugged_in) event."""
    minutes, plugged_in = event
    if isinstance(minutes, bool) or not isinstance(minutes, int):
        raise TypeError("event duration must be an integer number of minutes")
    if minutes < 0:
        raise ValueError("event duration must not be negative")
    if not isinstance(plugged_in, bool):
        raise TypeError("plugged-in flag must be a boolean")
    return minutes, plugged_in


def _charge_one_minute(capacity):
    """Capacity after one minute connected to the charger."""
    if capacity < FAST_CHARGE_THRESHOLD:
        capacity += FAST_CHARGE_RATE
    else:
        capacity += TRICKLE_CHARGE_RATE
    return min(capacity, MAX_CAPACITY)


def _drain_one_minute(capacity):
    """Capacity after one idle minute on battery power."""
    return max(capacity - IDLE_DRAIN_RATE, EMPTY_CAPACITY)


def charge(events):
    """Simulate the battery over the given events, returning final capacity."""
    capacity = EMPTY_CAPACITY
    for event in events:
        minutes, plugged_in = _validate_event(event)
        for _ in range(minutes):
            if plugged_in:
                capacity = _charge_one_minute(capacity)
            else:
                capacity = _drain_one_minute(capacity)
    return capacity


def state_of_charge(capacity):
    """Capacity expressed as a percentage of the hardware maximum."""
    return capacity * PERCENT_SCALE / MAX_CAPACITY


def format_report(events):
    """Human readable trace of the capacity after each event."""
    lines = []
    for index in range(len(events)):
        minutes, plugged_in = _validate_event(events[index])
        capacity = charge(events[: index + 1])
        mode = "charging" if plugged_in else "idle"
        lines.append(
            "{:>4} min {:<9} -> {:>5} mAh ({:5.1f}%)".format(
                minutes, mode, capacity, state_of_charge(capacity)
            )
        )
    return "\n".join(lines)


def main():
    schedules = [
        [(10, True), (5, False)],
        [(120, True), (30, False), (10, True)],
        [(200, True), (1000, False)],
    ]
    for schedule in schedules:
        print(format_report(schedule))
        final = charge(schedule)
        status = "full" if final == MAX_CAPACITY else "empty" if final == EMPTY_CAPACITY else "partial"
        print("final capacity: {} mAh ({})\n".format(final, status))


if __name__ == "__main__":
    main()

