        total = BASE_CHARGE
        total += min(usage, TIER_ONE_LIMIT) * TIER_ONE_RATE
        if usage > TIER_ONE_LIMIT:
            total += (min(usage, TIER_TWO_LIMIT) - TIER_ONE_LIMIT) * TIER_TWO_RATE
        if usage > TIER_TWO_LIMIT:
            total += (usage - TIER_TWO_LIMIT) * TIER_THREE_RATE
        bills.append(round(total, BILL_PRECISION))
    return bills


def parse_usages(text):
    """Parse whitespace- or comma-separated gallon readings into integers."""
    tokens = text.replace(",", " ").split()
    if not tokens:
        raise ValueError("no meter readings found")
    return [int(token) for token in tokens]


