CENTS_PRECISION = 2
CURRENCY_SYMBOL = "$"
RECEIPT_WIDTH = 34


def validate_passenger(passenger):
    """Return a (priority, weight) pair, raising ValueError on bad input."""
    if len(passenger) != 2:
        raise ValueError("each passenger needs a priority flag and a bag weight")
    priority, weight = passenger
    if not isinstance(priority, bool):
        raise ValueError("priority seat selection must be a boolean")
    if not isinstance(weight, int) or isinstance(weight, bool):
        raise ValueError("checked baggage weight must be an integer")
    if weight < 0:
        raise ValueError("checked baggage weight cannot be negative")
    return priority, weight


def baggage_fee(weight):
    """Fee for a single checked bag of the given weight in pounds."""
    if weight <= 0:
        return 0.0
    if weight < HEAVY_BAG_THRESHOLD:
        return STANDARD_BAG_FEE
    return HEAVY_BAG_FEE


def passenger_subtotal(priority, weight):
    """Pre-tax total for one passenger."""
    subtotal = BASE_ECONOMY_FARE
    if priority:
        subtotal += PRIORITY_SEAT_FEE
    return subtotal + baggage_fee(weight)


def flight(passengers):
    """Compute the taxed ticket price for every passenger in the list."""
    prices = []
    for passenger in passengers:
        priority, weight = validate_passenger(passenger)
        subtotal = passenger_subtotal(priority, weight)
        prices.append(round(subtotal * (1 + FEDERAL_TAX_RATE), CENTS_PRECISION))
    return prices


