    for index, ((priority, weight), price) in enumerate(zip(passengers, prices), 1):
        seat = "priority" if priority else "economy"
        bag = "{} lb".format(weight) if weight > 0 else "no bag"
        label = "{}. {} / {}".format(index, seat, bag)
        lines.append(label.ljust(RECEIPT_WIDTH - 10) + format_money(price).rjust(10))
    lines.append("-" * RECEIPT_WIDTH)
    total = round(sum(prices), CENTS_PRECISION)
    lines.append("TOTAL".ljust(RECEIPT_WIDTH - 10) + format_money(total).rjust(10))
    heavy = sum(1 for _, weight in passengers if weight >= HEAVY_BAG_THRESHOLD)
    lines.append("heavy bags charged: {}".format(heavy))
    return "\n".join(lines)


