BASELINE_RESTING_BURN = 2000.0
DAILY_STEP_GOAL = 10000
STANDARD_BURN_RATE = 0.04
BONUS_BURN_RATE = 0.06
STREAK_BONUS_CALORIES = 500.0
STREAK_REQUIRED_DAYS = 3
REPORT_DECIMALS = 1


def _validate(steps):
    if not isinstance(steps, (list, tuple)):
        raise TypeError("steps must be a list of integers")
    checked = []
    for index, value in enumerate(steps):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("day %d: step count must be an integer" % (index + 1))
        if value < 0:
            raise ValueError("day %d: step count cannot be negative" % (index + 1))
        checked.append(value)
    return checked


def fitness(steps):
    daily_steps = _validate(steps)
    calories = []
    streak = 0
    for count in daily_steps:
        total = BASELINE_RESTING_BURN
        if count <= DAILY_STEP_GOAL:
            total += count * STANDARD_BURN_RATE
        else:
            total += DAILY_STEP_GOAL * STANDARD_BURN_RATE
            total += (count - DAILY_STEP_GOAL) * BONUS_BURN_RATE
        if count >= DAILY_STEP_GOAL:
            streak += 1
        else:
            streak = 0
        if streak >= STREAK_REQUIRED_DAYS:
            total += STREAK_BONUS_CALORIES
        calories.append(round(total, 10))
    return calories


def summarize(steps):
    calories = fitness(steps)
    goal_days = sum(1 for count in steps if count >= DAILY_STEP_GOAL)
    return {
        "days": len(calories),
        "goal_days": goal_days,
        "total_calories": sum(calories),
        "average_calories": sum(calories) / len(calories) if calories else BASELINE_RESTING_BURN,
    }


def format_report(steps):
    calories = fitness(steps)
    lines = []
    for index, (count, burned) in enumerate(zip(steps, calories), start=1):
        marker = "goal" if count >= DAILY_STEP_GOAL else "under"
        lines.append(
            "Day %d: %6d steps (%s) -> %.*f cal"
            % (index, count, marker, REPORT_DECIMALS, burned)
        )
    summary = summarize(steps)
    lines.append(
        "Totals: %d days, %d at or above %d steps, %.*f cal, avg %.*f cal"
        % (
            summary["days"],
            summary["goal_days"],
            DAILY_STEP_GOAL,
            REPORT_DECIMALS,
            summary["total_calories"],
            REPORT_DECIMALS,
            summary["average_calories"],
        )
    )
    return "\n".join(lines)


if __name__ == "__main__":
    print(fitness([12000, 8000]))
    print(format_report([11000, 10000, 15000, 9000, 10500, 12500, 13000]))

