MIN_CREDIT_SCORE = 650
MAX_DTI_RATIO = 0.36
LOAN_TERM_YEARS = 30
BASE_INTEREST_RATE = 0.05
MONTHS_PER_YEAR = 12


def monthly_payment(principal):
    """Monthly payment for a fully amortised loan at the base rate and term."""
    months = LOAN_TERM_YEARS * MONTHS_PER_YEAR
    monthly_rate = BASE_INTEREST_RATE / MONTHS_PER_YEAR
    growth = (1 + monthly_rate) ** months
    return principal * monthly_rate * growth / (growth - 1)


def debt_to_income(principal, income):
    """Annualised payment burden as a fraction of gross annual income."""
    if income <= 0:
        raise ValueError("income must be positive")
    return monthly_payment(principal) * MONTHS_PER_YEAR / income


def evaluate(income, credit_score, amount):
    """Return (approved, reason) for a single application."""
    if amount <= 0:
        return False, "requested amount must be positive"
    if credit_score < MIN_CREDIT_SCORE:
        return False, "credit score %d below minimum %d" % (credit_score, MIN_CREDIT_SCORE)
    ratio = amount / income
    if ratio > MAX_DTI_RATIO:
        return False, "amount/income %.2f exceeds %.2f" % (ratio, MAX_DTI_RATIO)
    return True, "approved"


def screen(applications):
    """Return the list of loan amounts that satisfy the fixed credit criteria."""
    approved = []
    for income, credit_score, amount in applications:
        ok, _reason = evaluate(income, credit_score, amount)
        if ok:
            approved.append(amount)
    return approved


def report(applications):
    """Build human-readable lines describing each decision."""
    lines = []
    for income, credit_score, amount in applications:
        ok, reason = evaluate(income, credit_score, amount)
        payment = monthly_payment(amount) if amount > 0 else 0.0
        burden = debt_to_income(amount, income) if amount > 0 else 0.0
        lines.append(
            "income=%8.2f score=%3d amount=%9.2f payment=%8.2f "
            "burden=%5.1f%% -> %s" % (
                income, credit_score, amount, payment, burden * 100, reason
            )
        )
    return lines


if __name__ == "__main__":
    examples = [
        (90000.0, 720, 30000.0),
        (60000.0, 610, 15000.0),
        (50000.0, 700, 25000.0),
    ]
    print("criteria: score >= %d, amount/income <= %.2f, %d-year term at %.1f%%"
          % (MIN_CREDIT_SCORE, MAX_DTI_RATIO, LOAN_TERM_YEARS,
             BASE_INTEREST_RATE * 100))
    for line in report(examples):
        print(line)
    print("approved amounts:", screen(examples))

