gravityAcceleration = 9.8
dragCoefficient = 0.4
burnThrust = 500.0
maxAtmosphericHeight = 100000.0
escapeVelocity = 11000.0
groundAltitude = 0.0
maxIntervalSeconds = 60.0
reportPrecision = 2


def validate_intervals(telemetry):
    """Convert raw telemetry entries into a list of usable time steps."""
    intervals = []
    for index, raw in enumerate(telemetry):
        try:
            seconds = float(raw)
        except (TypeError, ValueError):
            raise ValueError("telemetry entry %d is not numeric: %r" % (index, raw))
        if seconds <= groundAltitude:
            raise ValueError("telemetry entry %d must be positive: %r" % (index, raw))
        if seconds > maxIntervalSeconds:
            raise ValueError(
                "telemetry entry %d exceeds %.1f s: %r" % (index, maxIntervalSeconds, raw)
            )
        intervals.append(seconds)
    return intervals


def simulate(telemetry):
    """Integrate the flight over the telemetry intervals; return (altitude, velocity)."""
    altitude = groundAltitude
    velocity = 0.0
    for seconds in validate_intervals(telemetry):
        acceleration = burnThrust - gravityAcceleration
        if altitude < maxAtmosphericHeight:
            acceleration -= dragCoefficient * velocity
        velocity += acceleration * seconds
        altitude += velocity * seconds
        if altitude < groundAltitude:
            altitude = groundAltitude
            velocity = 0.0
    return altitude, velocity


def has_escaped(velocity):
    """True when the final velocity reaches the escape threshold."""
    return velocity >= escapeVelocity


def format_report(altitude, velocity):
    lines = [
        "altitude: %.*f m" % (reportPrecision, altitude),
        "velocity: %.*f m/s" % (reportPrecision, velocity),
    ]
    if altitude >= maxAtmosphericHeight:
        lines.append("phase: vacuum (no drag)")
    else:
        lines.append("phase: atmospheric (drag active)")
    if has_escaped(velocity):
        lines.append("status: escape velocity reached")
    else:
        lines.append("status: %.*f m/s short of escape" % (reportPrecision, escapeVelocity - velocity))
    return "\n".join(lines)


def main():
    sequences = [[1.0], [1.0, 2.0, 3.0], [5.0] * 8]
    for telemetry in sequences:
        altitude, velocity = simulate(telemetry)
        print("telemetry %r" % (telemetry,))
        print(format_report(altitude, velocity))
        print()
    try:
        simulate([10.0, maxIntervalSeconds + 1.0])
    except ValueError as error:
        print("rejected: %s" % error)


if __name__ == "__main__":
    main()

