def classify(depth):
    """Return the safety status string for a single depth reading."""
    if depth <= SAFE_CRUISE_DEPTH:
        return STATUS_SAFE
    if depth <= WARNING_DEPTH:
        return STATUS_CAUTION
    if depth < CRUSH_DEPTH:
        return STATUS_WARNING
    return STATUS_CRITICAL


def ascent_time(depth):
    """Minimum time in seconds to surface at the maximum permitted ascent rate."""
    return depth / MAX_ASCENT_RATE


def validate(depth):
    """Reject readings a depth sensor cannot physically produce."""
    if not isinstance(depth, (int, float)) or isinstance(depth, bool):
        raise TypeError("depth readings must be numeric: %r" % (depth,))
    if depth < MIN_VALID_DEPTH:
        raise ValueError("depth below surface level: %r" % (depth,))
    return float(depth)


def monitor(telemetry):
    """Map each depth reading to (status, seconds-to-surface)."""
    results = []
    for reading in telemetry:
        depth = validate(reading)
        results.append((classify(depth), ascent_time(depth)))
    return results


def format_alert(depth, status):
    """Human readable alert line describing the zone the reading falls in."""
    if status == STATUS_SAFE:
        detail = "inside the %.0f m cruising envelope" % SAFE_CRUISE_DEPTH
    elif status == STATUS_CAUTION:
        detail = "%.1f m before the warning threshold" % (WARNING_DEPTH - depth)
