    if deepest >= CRUSH_DEPTH:
        lines.append("hull integrity lost")
    else:
        lines.append("margin to crush depth: %.1f m" % (CRUSH_DEPTH - deepest))
    critical = sum(1 for status, _ in results if status == STATUS_CRITICAL)
    lines.append("critical readings: %d" % critical)
    lines.append("full ascent at %.0f m/s: %.1f s"
                 % (MAX_ASCENT_RATE, ascent_time(deepest)))
