QUARTER_VALUE = 25
DIME_VALUE = 10
NICKEL_VALUE = 5
PENNY_VALUE = 1

COIN_SPECS = (
    ("quarter", QUARTER_VALUE),
    ("dime", DIME_VALUE),
    ("nickel", NICKEL_VALUE),
    ("penny", PENNY_VALUE),
)

MAX_COINS_PER_TRANSACTION = 50
MIN_AMOUNT_CENTS = 1
CENTS_PER_DOLLAR = 100
FAILURE_MESSAGE = "Unable to dispense: coin limit exceeded"


def validate_amount(cents):
    """Return the amount as a positive integer number of cents or raise."""
    if isinstance(cents, bool) or not isinstance(cents, int):
        raise TypeError("amount must be an integer number of cents")
    if cents < MIN_AMOUNT_CENTS:
        raise ValueError(f"amount must be at least {MIN_AMOUNT_CENTS} cent")
    return cents


def dispense(cents):
    """Greedily break `cents` into quarters, dimes, nickels and pennies."""
    remaining = validate_amount(cents)
    counts = []
    for _, value in COIN_SPECS:
        counts.append(remaining // value)
        remaining %= value
    if sum(counts) > MAX_COINS_PER_TRANSACTION:
        return FAILURE_MESSAGE
    return counts


def format_amount(cents):
    """Render a cent amount as a dollar string."""
    return f"${cents // CENTS_PER_DOLLAR}.{cents % CENTS_PER_DOLLAR:02d}"


def format_receipt(cents, result):
    """Turn a dispense() result into human readable lines."""
    header = f"Change for {format_amount(cents)}:"
    if result == FAILURE_MESSAGE:
        return f"{header}\n  {FAILURE_MESSAGE}"
    lines = [header]
    for (name, value), count in zip(COIN_SPECS, result):
        if count:
            label = name if count == 1 else name + "s"
            lines.append(f"  {count} {label} at {value}c")
    total = sum(result)
    lines.append(f"  {total} coins used of {MAX_COINS_PER_TRANSACTION} allowed")
    return "\n".join(lines)


def main():
    for amount in (99, 400):
        print(format_receipt(amount, dispense(amount)))
        print()


if __name__ == "__main__":
    main()

