def _validate(attacks):
    """Return the attack rolls as a list of ints, rejecting impossible rolls."""
    checked = []
    for index, power in enumerate(attacks):
        if isinstance(power, bool) or not isinstance(power, int):
            raise TypeError("attack %d is not an integer: %r" % (index, power))
        if power < MIN_ATTACK_ROLL:
            raise ValueError("attack %d is below the minimum roll of %d"
                             % (index, MIN_ATTACK_ROLL))
        checked.append(power)
    return checked


def resolve(attacks):
    """Turn each attack power into the damage it deals to the defender."""
    damages = []
    for power in _validate(attacks):
        if power > BASE_DEFENSE:
