EXCELLENT_THRESHOLD = -50
GOOD_THRESHOLD = -65
WEAK_THRESHOLD = -80
DROP_LIMIT = -90

EXCELLENT_LABEL = "excellent"
GOOD_LABEL = "good"
WEAK_LABEL = "weak"
POOR_LABEL = "poor"


def classify(signal):
    """Map a single dBm reading onto its quality label."""
    if signal >= EXCELLENT_THRESHOLD:
        return EXCELLENT_LABEL
    if signal >= GOOD_THRESHOLD:
        return GOOD_LABEL
    if signal >= WEAK_THRESHOLD:
        return WEAK_LABEL
    return POOR_LABEL


def analyze(signals):
    """Categorize every reading that is at or above the hard drop limit."""
    categories = []
    for signal in signals:
        if isinstance(signal, bool) or not isinstance(signal, (int, float)):
            raise TypeError("signal readings must be numbers, got %r" % (signal,))
        if signal < DROP_LIMIT:
            continue
        categories.append(classify(signal))
    return categories


def count_excellent(categories):
    """Count how many categorized signals reached the excellent band."""
    return sum(1 for category in categories if category == EXCELLENT_LABEL)


def summarize(categories):
    """Build a label -> occurrence mapping in descending quality order."""
    counts = {
        EXCELLENT_LABEL: 0,
        GOOD_LABEL: 0,
        WEAK_LABEL: 0,
        POOR_LABEL: 0,
    }
    for category in categories:
        counts[category] += 1
    return counts


def format_report(categories):
    """Render a one-line breakdown of the analyzed signal categories."""
    parts = ["%s=%d" % (label, total) for label, total in summarize(categories).items()]
    return " | ".join(parts)


def main():
    readings = [-42, -55.5, -49, -67, -78, -95, -88, -102, -60, -80, -91, -35]
    categories = analyze(readings)
    print("readings accepted: %d of %d" % (len(categories), len(readings)))
    print("dropped below %d dBm: %d" % (DROP_LIMIT, len(readings) - len(categories)))
    print("breakdown: %s" % format_report(categories))
    print("excellent (>= %d dBm): %d" % (EXCELLENT_THRESHOLD, count_excellent(categories)))
    weakest_acceptable = [c for c in categories if c == POOR_LABEL]
    if weakest_acceptable:
        print("borderline links between %d and %d dBm: %d"
              % (DROP_LIMIT, WEAK_THRESHOLD, len(weakest_acceptable)))


if __name__ == "__main__":
