import math


CYAN_ML_PER_PAGE = 0.5
MAGENTA_ML_PER_PAGE = 0.4
YELLOW_ML_PER_PAGE = 0.6
BLACK_ML_PER_PAGE = 1.2
PRIMER_WASTE_ML = 15.0
CARTRIDGE_CAPACITY_ML = 250.0
REPORT_DECIMALS = 2
SAMPLE_PAGE_COUNT = 500


def _validate_pages(pages):
    """Return the page count as a non-negative integer or raise."""
    if isinstance(pages, bool) or not isinstance(pages, int):
        raise TypeError("pages must be an integer")
    if pages < 0:
        raise ValueError("pages must not be negative")
    return pages


def _ink_volume(pages, rate_ml_per_page):
    """Ink for one color: coverage for every page plus the priming waste."""
    return pages * rate_ml_per_page + PRIMER_WASTE_ML


def estimate(pages):
    """Return the millilitres of each ink needed for a run of `pages` pages."""
    pages = _validate_pages(pages)
    return {
        "cyan": _ink_volume(pages, CYAN_ML_PER_PAGE),
        "magenta": _ink_volume(pages, MAGENTA_ML_PER_PAGE),
        "yellow": _ink_volume(pages, YELLOW_ML_PER_PAGE),
        "black": _ink_volume(pages, BLACK_ML_PER_PAGE),
    }


def total_ink(pages):
    """Return the combined volume of all four inks for the run."""
    return sum(estimate(pages).values())


def cartridges_needed(volume_ml):
    """Number of full cartridges required to supply `volume_ml` of ink."""
    if volume_ml < 0:
        raise ValueError("volume_ml must not be negative")
    return math.ceil(volume_ml / CARTRIDGE_CAPACITY_ML)


def format_report(pages):
    """Build a human-readable estimate report for a print run."""
    breakdown = estimate(pages)
    lines = ["Ink estimate for {0} pages".format(pages)]
    for color, volume in breakdown.items():
        lines.append(
            "  {0:<8} {1:>8} ml  ({2} cartridge(s))".format(
                color,
                round(volume, REPORT_DECIMALS),
                cartridges_needed(volume),
            )
        )
    combined = sum(breakdown.values())
    lines.append("  {0:<8} {1:>8} ml".format("TOTAL", round(combined, REPORT_DECIMALS)))
    waste = PRIMER_WASTE_ML * len(breakdown)
    lines.append("  priming waste included: {0} ml".format(round(waste, REPORT_DECIMALS)))
    return "\n".join(lines)


def main():
    print(format_report(SAMPLE_PAGE_COUNT))
    black_only = estimate(SAMPLE_PAGE_COUNT)["black"]
    print("Black cartridges: {0}".format(cartridges_needed(black_only)))
    print("Combined volume: {0} ml".format(round(total_ink(SAMPLE_PAGE_COUNT), REPORT_DECIMALS)))


if __name__ == "__main__":
    main()

