FREEZING_THRESHOLD_F = 28
MAX_HUMIDITY_PERCENT = 60
WATER_RATE_GPM = 50
MAX_OPERATION_HOURS = 12
MINUTES_PER_HOUR = 60
MIN_HUMIDITY_PERCENT = 0
ABSOLUTE_ZERO_F = -459.67


def validate_reading(temperature, humidity):
    if temperature < ABSOLUTE_ZERO_F:
        raise ValueError("temperature %r is below absolute zero" % (temperature,))
    if humidity < MIN_HUMIDITY_PERCENT or humidity > 100:
        raise ValueError("humidity %r is not a percentage" % (humidity,))


def daily_water_usage():
    return WATER_RATE_GPM * MAX_OPERATION_HOURS * MINUTES_PER_HOUR


def plan(forecast):
    days = []
    for temperature, humidity in forecast:
        validate_reading(temperature, humidity)
        if temperature < FREEZING_THRESHOLD_F and humidity < MAX_HUMIDITY_PERCENT:
            days.append(
                {
                    "temperature": temperature,
                    "humidity": humidity,
                    "viable": True,
                    "hours": MAX_OPERATION_HOURS,
                    "water_gallons": daily_water_usage(),
                }
            )
        else:
            days.append(
                {
                    "temperature": temperature,
                    "humidity": humidity,
                    "viable": False,
                    "hours": 0,
                    "water_gallons": 0,
                }
            )
    return days


def total_water(days):
    return sum(day["water_gallons"] for day in days)


def describe(index, day):
    if day["viable"]:
        return "Day %d: %.1fF / %d%% -> run %d h, %d gal" % (
            index,
            day["temperature"],
            day["humidity"],
            MAX_OPERATION_HOURS,
            day["water_gallons"],
        )
    if day["temperature"] >= FREEZING_THRESHOLD_F:
        reason = "too warm"
    else:
        reason = "too humid"
    return "Day %d: %.1fF / %d%% -> idle (%s)" % (
        index,
        day["temperature"],
        day["humidity"],
        reason,
    )


if __name__ == "__main__":
    week = [(21, 45), (27, 55), (30, 40), (18, 72), (25, 30), (26, 60), (33, 80)]
    schedule = plan(week)
    for number, entry in enumerate(schedule, start=1):
        print(describe(number, entry))
    viable_days = sum(1 for entry in schedule if entry["viable"])
    print("Viable days: %d of %d" % (viable_days, len(schedule)))
    print("Total water: %d gallons at %d gal/min" % (total_water(schedule), WATER_RATE_GPM))
    print(
        "Limits: below %dF, under %d%% humidity"
        % (FREEZING_THRESHOLD_F, MAX_HUMIDITY_PERCENT)
    )

