NORMAL_SYSTOLIC_LIMIT = 120
NORMAL_DIASTOLIC_LIMIT = 80
ELEVATED_SYSTOLIC_THRESHOLD = 129
CRITICAL_SYSTOLIC_THRESHOLD = 180
LABEL_NORMAL = "normal"
LABEL_ELEVATED = "elevated"
LABEL_CRITICAL = "critical"


def validate_reading(reading):
    systolic, diastolic = reading
    if not isinstance(systolic, int) or not isinstance(diastolic, int):
        raise TypeError("blood pressure values must be integers: %r" % (reading,))
    if systolic <= diastolic:
        raise ValueError("systolic must exceed diastolic: %r" % (reading,))
    return systolic, diastolic


def classify_reading(systolic, diastolic):
    if diastolic >= NORMAL_DIASTOLIC_LIMIT or systolic > ELEVATED_SYSTOLIC_THRESHOLD:
        return LABEL_CRITICAL
    if systolic >= NORMAL_SYSTOLIC_LIMIT:
        return LABEL_ELEVATED
    return LABEL_NORMAL


def categorize(readings):
    labels = []
    for reading in readings:
        systolic, diastolic = validate_reading(reading)
        labels.append(classify_reading(systolic, diastolic))
    return labels


def critical_readings(readings):
    return [
        reading
        for reading, label in zip(readings, categorize(readings))
        if label == LABEL_CRITICAL
    ]


def excess_over_normal(systolic, diastolic):
    return (
        max(0, systolic - NORMAL_SYSTOLIC_LIMIT),
        max(0, diastolic - NORMAL_DIASTOLIC_LIMIT),
    )


def format_reading(reading):
    systolic, diastolic = reading
    over_systolic, over_diastolic = excess_over_normal(systolic, diastolic)
    if systolic >= CRITICAL_SYSTOLIC_THRESHOLD:
        advice = "EMERGENCY CARE"
    else:
        advice = "clinic follow-up"
    return "{:>3}/{:<3} (+{}/+{} over normal) -> {}".format(
        systolic, diastolic, over_systolic, over_diastolic, advice
    )


def main():
    patients = [
        (112, 71), (118, 79), (124, 76), (129, 78), (131, 84),
        (145, 92), (176, 101), (182, 110), (198, 118), (109, 68),
    ]
    labels = categorize(patients)
    print("normal: %d" % labels.count(LABEL_NORMAL))
    print("elevated: %d" % labels.count(LABEL_ELEVATED))
    print("critical: %d" % labels.count(LABEL_CRITICAL))
    criticals = critical_readings(patients)
    print("\nCritical cases (systolic > %d or diastolic >= %d):"
          % (ELEVATED_SYSTOLIC_THRESHOLD, NORMAL_DIASTOLIC_LIMIT))
    for reading in sorted(criticals, key=lambda pair: pair[0], reverse=True):
        print("  " + format_reading(reading))
    emergencies = [pair for pair in criticals if pair[0] >= CRITICAL_SYSTOLIC_THRESHOLD]
    print("\n%d of %d critical readings reach the hypertensive crisis level of %d."
          % (len(emergencies), len(criticals), CRITICAL_SYSTOLIC_THRESHOLD))


if __name__ == "__main__":
    main()

