AUDIO_BITRATE_KBPS = 320.0
KILOBITS_PER_MEGABIT = 1000.0
BITS_PER_BYTE = 8.0
SIZE_DECIMALS = 2

RESOLUTION_BITRATES = {
    "720p": HD_BITRATE_MBPS,
    "1080p": FULL_HD_BITRATE_MBPS,
    "2160p": FOUR_K_BITRATE_MBPS,
}

RESOLUTION_ALIASES = {
    "hd": "720p",
    "1280x720": "720p",
    "fhd": "1080p",
    "full hd": "1080p",
    "1920x1080": "1080p",
    "4k": "2160p",
    "uhd": "2160p",
    "3840x2160": "2160p",
}


def megabits_to_megabytes(megabits):
    return megabits / BITS_PER_BYTE


def audio_bitrate_mbps():
    return AUDIO_BITRATE_KBPS / KILOBITS_PER_MEGABIT


def normalize_resolution(resolution):
    key = str(resolution).strip().lower()
    return RESOLUTION_ALIASES.get(key, key)


def video_bitrate_mbps(resolution):
    key = normalize_resolution(resolution)
    if key not in RESOLUTION_BITRATES:
        known = ", ".join(sorted(RESOLUTION_BITRATES))
        raise ValueError("unsupported resolution %r (known: %s)" % (resolution, known))
    return RESOLUTION_BITRATES[key]


def parse_video(video):
    if isinstance(video, dict):
        resolution = video["resolution"]
        duration = video["duration"]
    else:
        resolution, duration = video
    if not isinstance(duration, (int, float)) or isinstance(duration, bool):
        raise TypeError("duration must be a number, got %r" % (duration,))
    if duration < 0:
        raise ValueError("duration must not be negative, got %r" % (duration,))
    return resolution, float(duration)


def file_size_megabytes(resolution, duration):
    total_mbps = video_bitrate_mbps(resolution) + audio_bitrate_mbps()
    return megabits_to_megabytes(total_mbps * duration)


def assign(videos):
    sizes = []
    for video in videos:
        resolution, duration = parse_video(video)
        sizes.append(round(file_size_megabytes(resolution, duration), SIZE_DECIMALS))
    return sizes


def format_report(videos, sizes):
    lines = []
    for video, size in zip(videos, sizes):
        resolution, duration = parse_video(video)
        label = normalize_resolution(resolution)
        rate = RESOLUTION_BITRATES[label]
        lines.append(
            "%-6s %7.1fs @ %4.1f Mbps -> %.*f MB"
            % (label, duration, rate, SIZE_DECIMALS, size)
        )
    return "\n".join(lines)


