IDEAL_PH = 8.1
PH_TOLERANCE = 0.3
MAX_AMMONIA = 0.2
MIN_SAFE_TEMPERATURE = 75.0
MAX_SAFE_TEMPERATURE = 80.0
REQUIRED_FIELDS = ("ph", "ammonia", "temperature")
ALERT_STREAK_THRESHOLD = 2
DAY_LABELS = ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")


def _read_sample(sample):
    values = []
    for field in REQUIRED_FIELDS:
        if field not in sample:
            raise KeyError("sample is missing field %r" % field)
        values.append(float(sample[field]))
    return tuple(values)


def evaluate(samples):
    flags = []
    for sample in samples:
        ph, ammonia, temperature = _read_sample(sample)
        ph_drift = abs(ph - IDEAL_PH)
        safe = ph_drift <= PH_TOLERANCE
        if ammonia > MAX_AMMONIA:
            safe = False
        if temperature < MIN_SAFE_TEMPERATURE or temperature > MAX_SAFE_TEMPERATURE:
            safe = False
        flags.append(safe)
    return flags


def longest_unsafe_streak(flags):
    best = 0
    current = 0
    for safe in flags:
        if safe:
            current = 0
        else:
            current += 1
            if current > best:
                best = current
    return best


def describe(sample):
    ph, ammonia, temperature = _read_sample(sample)
    notes = []
    drift = abs(ph - IDEAL_PH)
    if drift > PH_TOLERANCE:
