CHARS_PER_WORD = 5
MASTERY_WPM = 80.0
PASSING_WPM = 40.0
ERROR_PENALTY_WPM = 2.0
PERCENT_SCALE = 100.0


def accuracy(total_chars, errors):
    """Overall accuracy percentage for a batch of typed characters."""
    if total_chars <= 0:
        return 0.0
    correct = max(total_chars - errors, 0)
    return correct / total_chars * PERCENT_SCALE


def gross_wpm(total_chars, minutes):
    """Words per minute before any error penalty is applied."""
    return (total_chars / CHARS_PER_WORD) / minutes


def net_wpm(total_chars, minutes, errors):
    """Gross speed reduced by the standard penalty per error."""
    penalty = errors * ERROR_PENALTY_WPM / minutes
    return max(gross_wpm(total_chars, minutes) - penalty, 0.0)


def classify(speed):
    if speed >= MASTERY_WPM:
        return "mastery"
    if speed >= PASSING_WPM:
        return "passing"
    return "failing"


def evaluate(sessions):
    """Grade typing sessions, returning per-session records plus a summary."""
    records = []
    chars_typed = 0
    errors_made = 0
    for index, (total_chars, minutes, errors) in enumerate(sessions, start=1):
        if minutes <= 0:
            raise ValueError("session %d has non-positive elapsed time" % index)
        if total_chars < 0 or errors < 0:
            raise ValueError("session %d has negative counts" % index)
        speed = net_wpm(total_chars, minutes, errors)
        records.append({
            "session": index,
            "gross_wpm": gross_wpm(total_chars, minutes),
            "net_wpm": speed,
            "accuracy": accuracy(total_chars, errors),
            "grade": classify(speed),
        })
        chars_typed += total_chars
        errors_made += errors
    summary = {
        "sessions": len(records),
        "accuracy": accuracy(chars_typed, errors_made),
        "mastered": sum(1 for r in records if r["net_wpm"] >= MASTERY_WPM),
        "passed": sum(1 for r in records if r["net_wpm"] >= PASSING_WPM),
    }
    return {"records": records, "summary": summary}


def report(result):
    lines = []
    for record in result["records"]:
        lines.append(
            "Session %d: gross %.1f wpm, net %.1f wpm (%s), accuracy %.1f%%"
            % (record["session"], record["gross_wpm"], record["net_wpm"],
               record["grade"], record["accuracy"])
        )
    summary = result["summary"]
    lines.append(
        "Overall: %d sessions, %.1f%% accuracy, %d at/above %.0f wpm, %d mastering %.0f wpm"
        % (summary["sessions"], summary["accuracy"], summary["passed"],
           PASSING_WPM, summary["mastered"], MASTERY_WPM)
    )
    return "\n".join(lines)


def main():
    sessions = [(1500, 3.0, 5), (2400, 5.0, 12), (900, 4.0, 8)]
    print(report(evaluate(sessions)))


if __name__ == "__main__":
    main()

