baseFare = 5.00
perMileRate = 1.50
rushSurcharge = 3.00
maxStops = 20
maxRetries = 3
defaultTimeout = 30.0


def apply_rush_surcharge(total):
    """Add the rush hour surcharge to an already computed total fare."""
    return total + rushSurcharge


def validate_deliveries(deliveries):
    """Return only the usable, non-negative numeric distances."""
    clean = []
    for distance in deliveries:
        if not isinstance(distance, (int, float)):
            continue
        if distance < 0:
            continue
        clean.append(float(distance))
    return clean


def calculate(deliveries):
    """Cost each delivery until the per-driver stop limit is reached."""
    distances = validate_deliveries(deliveries)
    stops = 0
    costs = []
    for distance in distances:
        if stops >= maxStops:
            break
        costs.append(distance * perMileRate + baseFare)
        stops += 1
    return costs


def fetch_route_plan(deliveries, rush_hour=False):
    """Retry the costing run, then summarise it into a dispatch plan."""
    attempt = 0
    costs = []
    while attempt < maxRetries:
        attempt += 1
        costs = calculate(deliveries)
        if costs:
            break
    total = sum(costs)
    if rush_hour:
        total = apply_rush_surcharge(total)
    eta = min(defaultTimeout, len(costs) * 2.0)
    return {
        "stops": len(costs),
        "skipped": len(deliveries) - len(costs),
        "costs": costs,
        "total": total,
        "eta_minutes": eta,
        "attempts": attempt,
    }


def format_plan(plan):
    lines = ["Dispatch plan (%d stops, %d skipped)" % (plan["stops"], plan["skipped"])]
    for index, cost in enumerate(plan["costs"], start=1):
        lines.append("  stop %2d: $%6.2f" % (index, cost))
    lines.append("  total  : $%6.2f" % plan["total"])
    if plan["total"] > baseFare * maxStops:
        lines.append("  note   : fare exceeds standard batch ceiling")
    if plan["eta_minutes"] >= defaultTimeout:
        lines.append("  note   : route hits the dispatch timeout window")
    lines.append("  eta    : %.1f min in %d attempt(s)" % (plan["eta_minutes"], plan["attempts"]))
    return "\n".join(lines)


if __name__ == "__main__":
    batch = [1.2, 4.0, 7.5, 0.8, 12.0, 3.3, 9.9, 2.0, 5.5, 6.1, 0.0, 15.0, 8.2, 4.4, 11.7]
    print(format_plan(fetch_route_plan(batch, rush_hour=True)))

