IDEAL_CHLORINE_LEVEL = 3.0
MIN_PH = 7.2
MAX_PH = 7.8
ACID_DOSE_PER_VOLUME = 0.012
SODA_DOSE_PER_VOLUME = 0.018
CHLORINE_DOSE_PER_VOLUME = 0.0014
MAX_RETRIES = 3
DEFAULT_TIMEOUT = 30.0
DOSE_ROUNDING = 3


def validate_reading(reading):
    volume, ph, chlorine = reading
    if volume <= 0:
        raise ValueError("water volume must be positive")
    if ph <= 0:
        raise ValueError("ph level must be positive")
    if chlorine < 0:
        raise ValueError("chlorine level cannot be negative")
    return float(volume), float(ph), float(chlorine)


def soda_needed(volume, ph):
    if ph >= MIN_PH:
        return 0.0
    return round((MIN_PH - ph) * SODA_DOSE_PER_VOLUME * volume, DOSE_ROUNDING)


def acid_needed(volume, ph):
    if ph <= MAX_PH:
        return 0.0
    return round((ph - MAX_PH) * ACID_DOSE_PER_VOLUME * volume, DOSE_ROUNDING)


def chlorine_needed(volume, chlorine):
    if chlorine >= IDEAL_CHLORINE_LEVEL:
        return 0.0
    gap = IDEAL_CHLORINE_LEVEL - chlorine
    return round(gap * CHLORINE_DOSE_PER_VOLUME * volume, DOSE_ROUNDING)


def balance(readings):
    doses = []
    for reading in readings:
        volume, ph, chlorine = validate_reading(reading)
        doses.append((acid_needed(volume, ph),
                      soda_needed(volume, ph),
                      chlorine_needed(volume, chlorine)))
    return doses


def simulate_treatment(volume, ph, chlorine):
    """Apply doses repeatedly until the pool is in range or attempts run out."""
    for attempt in range(1, MAX_RETRIES + 1):
        acid, soda, added = balance([(volume, ph, chlorine)])[0]
        if acid == 0.0 and soda == 0.0 and added == 0.0:
            return attempt - 1, ph, chlorine
        ph += soda / (SODA_DOSE_PER_VOLUME * volume)
        ph -= acid / (ACID_DOSE_PER_VOLUME * volume)
        chlorine += added / (CHLORINE_DOSE_PER_VOLUME * volume)
    return MAX_RETRIES, ph, chlorine


def format_report(reading, doses, minutes):
    volume, ph, chlorine = reading
    acid, soda, added = doses
    label = "OK" if minutes <= DEFAULT_TIMEOUT else "OVERDUE"
    return (f"{volume:>7.0f} L  ph={ph:.2f} cl={chlorine:.2f} -> "
            f"acid={acid:.3f} soda={soda:.3f} chlorine={added:.3f} "
            f"[{label} after {minutes:.0f} min]")


def main():
    readings = [(50000, 6.9, 1.2), (30000, 8.1, 3.4), (12000, 7.5, 0.0)]
    results = balance(readings)
    for reading, doses in zip(readings, results):
        cycles, _ph, _cl = simulate_treatment(*reading)
        minutes = cycles * (DEFAULT_TIMEOUT / MAX_RETRIES)
        print(format_report(reading, doses, minutes))


if __name__ == "__main__":
    main()

