BASE_HOURLY_RATE = 3.50
DAILY_MAXIMUM_FEE = 24.00
LOST_TICKET_PENALTY = 15.00
GRACE_PERIOD_MINUTES = 15
EV_CHARGING_RATE_PER_HOUR = 2.00
MINUTES_PER_HOUR = 60


def hours_billed(minutes):
    """Round a duration in minutes up to a whole number of billable hours."""
    if minutes < 0:
        raise ValueError("durations must not be negative")
    return -(-minutes // MINUTES_PER_HOUR)


def parking_fee(parked_minutes):
    """Fee for occupying a bay, free inside the grace period and capped daily."""
    if parked_minutes <= GRACE_PERIOD_MINUTES:
        return 0.0
    fee = hours_billed(parked_minutes) * BASE_HOURLY_RATE
    return min(fee, DAILY_MAXIMUM_FEE)


def charging_fee(charging_minutes):
    """Fee for the EV charger, billed per started hour."""
    return hours_billed(charging_minutes) * EV_CHARGING_RATE_PER_HOUR


def session_total(parked_minutes, lost_ticket, charging_minutes):
    """Combine parking, penalty and charging charges for one session."""
    total = parking_fee(parked_minutes) + charging_fee(charging_minutes)
    if lost_ticket:
        total += LOST_TICKET_PENALTY
    return round(total, 2)


def bill(sessions):
    """Return the total fee for each (minutes, lost_ticket, ev_minutes) session."""
    return [session_total(*session) for session in sessions]


def describe(session, total):
    """Render a one-line human readable receipt for a billed session."""
    parked_minutes, lost_ticket, charging_minutes = session
    if parked_minutes <= GRACE_PERIOD_MINUTES:
        parking_note = "within grace period"
    else:
        parking_note = "{} h parking".format(hours_billed(parked_minutes))
        if parking_fee(parked_minutes) >= DAILY_MAXIMUM_FEE:
            parking_note += " (daily maximum)"
    parts = [parking_note]
    if charging_minutes > 0:
        parts.append("{} h charging".format(hours_billed(charging_minutes)))
    if lost_ticket:
        parts.append("lost ticket +{:.2f}".format(LOST_TICKET_PENALTY))
    return "{:>7.2f}  {}".format(total, ", ".join(parts))


def main():
    sessions = [
        (10, False, 0),
        (61, False, 0),
        (150, False, 45),
        (600, False, 0),
        (90, True, 120),
        (GRACE_PERIOD_MINUTES, True, 0),
    ]
    totals = bill(sessions)
    for session, total in zip(sessions, totals):
        print(describe(session, total))
    print("{:>7.2f}  garage revenue ({} sessions)".format(sum(totals), len(totals)))
    print("{:>7.2f}  base hourly rate".format(BASE_HOURLY_RATE))
    print("{:>7.2f}  EV rate per hour".format(EV_CHARGING_RATE_PER_HOUR))


if __name__ == "__main__":
    main()

