MAX_BUCKET_CAPACITY = 100.0
INITIAL_TOKEN_GRANT = 20.0
TOKEN_REFILL_RATE_PER_SECOND = 2.0
STANDARD_REQUEST_COST = 5.0
PENALTY_COOLDOWN_SECONDS = 10.0
MAX_PENALTY_DURATION_LIMIT = 60.0


def normalize_tokens(tokens):
    """Return the starting balance, granting the initial tokens to new users."""
    if tokens is None:
        return INITIAL_TOKEN_GRANT
    balance = float(tokens)
    if balance < 0.0:
        raise ValueError("token count cannot be negative")
    return min(balance, MAX_BUCKET_CAPACITY)


def refill(tokens, elapsed_seconds):
    """Add the tokens earned during the idle period, capped at bucket capacity."""
    if elapsed_seconds < 0.0:
        raise ValueError("elapsed seconds cannot be negative")
    refilled = tokens + elapsed_seconds * TOKEN_REFILL_RATE_PER_SECOND
    return min(refilled, MAX_BUCKET_CAPACITY)


def penalty_is_active(penalized, elapsed_seconds):
    """A penalty holds until the cooldown passes, or until the hard duration cap."""
    if not penalized:
        return False
    if elapsed_seconds > MAX_PENALTY_DURATION_LIMIT:
        return False
    return elapsed_seconds < PENALTY_COOLDOWN_SECONDS


def can_afford(tokens):
    return tokens >= STANDARD_REQUEST_COST


def handle_request(tokens, elapsed_seconds, penalized):
    """Resolve a single request into (tokens, allowed, penalized)."""
    balance = refill(normalize_tokens(tokens), elapsed_seconds)
    if penalty_is_active(penalized, elapsed_seconds):
        return (balance, False, True)
    if can_afford(balance):
        return (balance - STANDARD_REQUEST_COST, True, False)
    return (balance, False, True)


def throttle(requests):
    """Apply the token bucket policy to every (tokens, elapsed, penalized) entry."""
    results = []
    for tokens, elapsed_seconds, penalized in requests:
        results.append(handle_request(tokens, elapsed_seconds, bool(penalized)))
    return results


def format_report(results):
    lines = []
    for index, (tokens, allowed, penalized) in enumerate(results, start=1):
        fill_pct = 100.0 * tokens / MAX_BUCKET_CAPACITY
        verdict = "ALLOW" if allowed else "DENY"
        state = "penalized" if penalized else "ok"
        remaining = int(tokens // STANDARD_REQUEST_COST)
        lines.append(
            "#{0} {1:<5} tokens={2:6.2f} ({3:5.1f}% full) "
            "requests_left={4} state={5}".format(
                index, verdict, tokens, fill_pct, remaining, state
            )
        )
    return "\n".join(lines)


def main():
    requests = [
        (None, 0.0, False),
        (4.0, 0.5, False),
        (4.0, 2.0, True),
        (0.0, PENALTY_COOLDOWN_SECONDS, True),
        (12.0, MAX_PENALTY_DURATION_LIMIT + 1.0, True),
        (MAX_BUCKET_CAPACITY, 30.0, False),
    ]
    print(format_report(throttle(requests)))


if __name__ == "__main__":
    main()

