text_nat:
CUT_IN_SPEED = 3.5
RATED_SPEED = 13.0
CUT_OUT_SPEED = 25.0
BASE_POWER_OUTPUT = 2500.0
STANDARD_AIR_DENSITY = 1.225
MIN_AIR_DENSITY = 0.8
MAX_AIR_DENSITY = 1.5
POWER_DECIMALS = 2


def validate_condition(speed, density):
    if speed < 0.0:
        raise ValueError("wind speed cannot be negative: %r" % (speed,))
    if not MIN_AIR_DENSITY <= density <= MAX_AIR_DENSITY:
        raise ValueError(
            "air density %r outside plausible range %.2f-%.2f"
            % (density, MIN_AIR_DENSITY, MAX_AIR_DENSITY)
        )


def raw_power(speed):
    if speed < CUT_IN_SPEED or speed > CUT_OUT_SPEED:
        return 0.0
    if speed >= RATED_SPEED:
        return BASE_POWER_OUTPUT
    fraction = (speed - CUT_IN_SPEED) / (RATED_SPEED - CUT_IN_SPEED)
    return BASE_POWER_OUTPUT * fraction


def density_factor(density):
    return density / STANDARD_AIR_DENSITY


def power_output(speed, density):
    return round(raw_power(speed) * density_factor(density), POWER_DECIMALS)


def describe_state(speed):
    if speed < CUT_IN_SPEED:
        return "idle (below cut-in)"
    if speed > CUT_OUT_SPEED:
        return "shut down (above cut-out)"
    if speed >= RATED_SPEED:
        return "rated output"
    return "partial load"


def generate(conditions):
    outputs = []
    for speed, density in conditions:
        validate_condition(speed, density)
        outputs.append(power_output(speed, density))
    return outputs


def format_report(conditions, outputs):
    lines = []
    for (speed, density), power in zip(conditions, outputs):
        lines.append(
            "%5.1f m/s  %.3f kg/m3  %9.*f kW  %s"
            % (speed, density, POWER_DECIMALS, power, describe_state(speed))
        )
    total = round(sum(outputs), POWER_DECIMALS)
    capacity = BASE_POWER_OUTPUT * len(outputs)
    share = (total / capacity * 100.0) if capacity else 0.0
    lines.append("farm total: %.*f kW (%.1f%% of nameplate)" % (POWER_DECIMALS, total, share))
    return "\n".join(lines)


def main():
    conditions = [
        (2.0, 1.225),
        (CUT_IN_SPEED, 1.200),
        (8.0, 1.225),
        (11.5, 1.310),
        (RATED_SPEED, 1.180),
        (18.0, STANDARD_AIR_DENSITY),
        (CUT_OUT_SPEED + 1.0, 1.225),
    ]
    print(format_report(conditions, generate(conditions)))


if __name__ == "__main__":
    main()

