CAR_MAX_PAYLOAD = 80.0
SAFETY_MARGIN_MULTIPLIER = 1.15


def car_weight(payload):
    """Gross weight of a single car carrying the given payload."""
    return CAR_EMPTY_WEIGHT + float(payload)


def train_weight(payloads):
    """Total gross weight of every car in the manifest."""
    return sum(car_weight(payload) for payload in payloads)


def overloaded_cars(payloads):
    """Indices of cars whose payload exceeds the per-car limit."""
    return [i for i, payload in enumerate(payloads) if payload > CAR_MAX_PAYLOAD]


def within_car_limit(payloads):
    return len(payloads) <= MAX_CARS_PER_TRAIN


def within_haul_capacity(total_weight):
    return total_weight * SAFETY_MARGIN_MULTIPLIER <= LOCOMOTIVE_HAUL_CAPACITY


def validate_manifest(payloads):
    """Return (car count, total weight, is_valid) for one manifest."""
    cars = len(payloads)
    total_weight = train_weight(payloads)
    valid = (
        not overloaded_cars(payloads)
        and within_car_limit(payloads)
        and within_haul_capacity(total_weight)
    )
    return (cars, total_weight, valid)


def load(manifests):
    """Validate every planned train and report its car count, weight and status."""
    return [validate_manifest(payloads) for payloads in manifests]


def describe(index, result):
    """Human readable report line for a single validated manifest."""
    cars, total_weight, valid = result
    status = "DISPATCH" if valid else "REJECTED"
    headroom = LOCOMOTIVE_HAUL_CAPACITY - total_weight * SAFETY_MARGIN_MULTIPLIER
    return (
        f"Train {index}: {cars:2d}/{MAX_CARS_PER_TRAIN} cars, "
        f"{total_weight:8.1f} t gross, headroom {headroom:8.1f} t -> {status}"
    )


def main():
    manifests = [
        [60.0, 72.5, 48.0, 80.0],
        [55.0, CAR_MAX_PAYLOAD + 5.0, 30.0],
        [70.0] * (MAX_CARS_PER_TRAIN + 1),
        [78.0] * MAX_CARS_PER_TRAIN,
        [],
    ]
    for index, result in enumerate(load(manifests), start=1):
        print(describe(index, result))


if __name__ == "__main__":
    main()

