STANDARD_GRAVITY = 9.80665
TERMINAL_VELOCITY = 55.0
MIN_DEPLOY_ALTITUDE = 800.0
RESERVE_DEPLOY_ALTITUDE = 300.0
PARACHUTE_DRAG_COEFFICIENT = 0.12
SIMULATION_TIME_STEP = 1.0
STATUS_FREEFALL = "freefall"
STATUS_MAIN_DEPLOYED = "main chute deployed"
STATUS_RESERVE_DEPLOYED = "reserve chute deployed"


def validate_jump(jump):
    """Normalise one (exit altitude, current altitude, velocity) tuple."""
    exit_altitude, altitude, velocity = (float(value) for value in jump)
    if exit_altitude < MIN_DEPLOY_ALTITUDE:
        raise ValueError("exit altitude is below the minimum deployment altitude")
    if altitude > exit_altitude:
        raise ValueError("current altitude cannot exceed the exit altitude")
    if altitude < 0.0:
        raise ValueError("current altitude cannot be negative")
    if velocity < 0.0 or velocity > TERMINAL_VELOCITY:
        raise ValueError("velocity must lie between zero and terminal velocity")
    return exit_altitude, altitude, velocity


def select_chute(altitude):
    """Return (main_triggered, reserve_triggered) for the given altitude."""
    if altitude < RESERVE_DEPLOY_ALTITUDE:
        return False, True
    if altitude < MIN_DEPLOY_ALTITUDE:
        return True, False
    return False, False


def apply_gravity(velocity):
    new_velocity = velocity + STANDARD_GRAVITY * SIMULATION_TIME_STEP
    if new_velocity > TERMINAL_VELOCITY:
        return TERMINAL_VELOCITY
    return new_velocity


def apply_parachute_drag(velocity):
    return velocity * PARACHUTE_DRAG_COEFFICIENT


def describe_status(main_triggered, reserve_triggered):
    if reserve_triggered:
        return STATUS_RESERVE_DEPLOYED
    if main_triggered:
        return STATUS_MAIN_DEPLOYED
    return STATUS_FREEFALL


def simulate(jumps):
    """Advance every jump by one time step and report chute status."""
    results = []
    for jump in jumps:
        _, altitude, velocity = validate_jump(jump)
        main_triggered, reserve_triggered = select_chute(altitude)
        velocity = apply_gravity(velocity)
        if main_triggered or reserve_triggered:
            velocity = apply_parachute_drag(velocity)
        results.append((round(velocity, 3), describe_status(main_triggered, reserve_triggered)))
    return results


def format_report(jumps, results):
    lines = []
    for (_, altitude, _velocity), (velocity, status) in zip(jumps, results):
        marker = "!" if status == STATUS_RESERVE_DEPLOYED else " "
        lines.append("{}{:8.1f} m -> {:6.2f} m/s  {}".format(marker, altitude, velocity, status))
    return "\n".join(lines)


def main():
    jumps = [
        (4000.0, 3500.0, 20.0),
        (4000.0, 1200.0, 54.0),
        (3000.0, 700.0, 50.0),
        (3000.0, 250.0, 48.0),
        (1000.0, 1000.0, 0.0),
    ]
    print(format_report(jumps, simulate(jumps)))


if __name__ == "__main__":
    main()

