"""Job estimator for an industrial 3D printing farm."""

BASE_EXTRUDER_TEMPERATURE = 205.0
BASE_BED_TEMPERATURE = 60.0
MAX_RETRACTION_SPEED = 45.0
BASE_RETRACTION_SPEED = 30.0
RAPID_MOVE_RETRACTION_BONUS = 20.0
FILAMENT_WEIGHT_PER_METER = 3.02
COOLING_FAN_TRIGGER_THRESHOLD = 25.0
FAN_SPEED_MAX = 100
FAN_SPEED_LOW = 20
RAPID_PRINT_TIME_SECONDS = 900.0
RAPID_TEMPERATURE_BOOST = 7.5
MAX_OVERHANG_PERCENT = 100.0


def validate_model(model):
    """Unpack and sanity-check a single (length, time, overhang) tuple."""
    length, print_time, overhang = model
    if length <= 0.0:
        raise ValueError("filament length must be positive, got %r" % (length,))
    if print_time <= 0.0:
        raise ValueError("print time must be positive, got %r" % (print_time,))
    if overhang < 0.0 or overhang > MAX_OVERHANG_PERCENT:
        raise ValueError("overhang must be a percentage, got %r" % (overhang,))
    return float(length), float(print_time), float(overhang)


def filament_weight(length_m):
    """Grams of filament consumed by a job of the given length in metres."""
    return length_m * FILAMENT_WEIGHT_PER_METER


def is_rapid_job(print_time):
    return print_time < RAPID_PRINT_TIME_SECONDS


def fan_speed_for(overhang):
    if overhang > COOLING_FAN_TRIGGER_THRESHOLD:
        return FAN_SPEED_MAX
    return FAN_SPEED_LOW


def extruder_temperature(print_time):
    if is_rapid_job(print_time):
        return BASE_EXTRUDER_TEMPERATURE + RAPID_TEMPERATURE_BOOST
    return BASE_EXTRUDER_TEMPERATURE


def retraction_speed(print_time):
    """Faster retraction for rapid jobs, capped to avoid grinding filament."""
    speed = BASE_RETRACTION_SPEED
    if is_rapid_job(print_time):
        speed += RAPID_MOVE_RETRACTION_BONUS
    return min(speed, MAX_RETRACTION_SPEED)


def estimate(models):
    """Return (weight_g, extruder_temp, fan_speed) for each queued model."""
    results = []
    for model in models:
        length, print_time, overhang = validate_model(model)
        results.append((
            round(filament_weight(length), 2),
            extruder_temperature(print_time),
            fan_speed_for(overhang),
        ))
    return results


def format_report(models, results):
    lines = ["bed temperature held at %.1fC for all jobs" % BASE_BED_TEMPERATURE]
    for index, (model, result) in enumerate(zip(models, results), start=1):
        weight, temperature, fan = result
        lines.append(
            "job %d: %.2fg | nozzle %.1fC | fan %d%% | retraction %.1fmm/s"
            % (index, weight, temperature, fan, retraction_speed(model[1]))
        )
    return "\n".join(lines)


def main():
    queue = [(12.5, 5400.0, 10.0), (3.0, 420.0, 48.0), (27.8, 18000.0, 25.0)]
    print(format_report(queue, estimate(queue)))


if __name__ == "__main__":
    main()

