import math

STARTING_LINE_OFFSET_MILES = 0.1
AID_STATION_INTERVAL_MILES = 2.0
MARATHON_DISTANCE_MILES = 26.2
MAX_COURSE_FINISH_MINUTES = 390.0
SWEEPER_PACE_PER_MILE = 15.0
DISQUALIFICATION_BUFFER_MINUTES = 10.0


def adjusted_distance(total_distance):
    """Distance actually run on the measured course."""
    return total_distance - STARTING_LINE_OFFSET_MILES


def distance_to_next_aid_station(course_distance):
    """Miles left until the next aid station strictly ahead of the runner."""
    stations_passed = math.floor(course_distance / AID_STATION_INTERVAL_MILES)
    next_station = (stations_passed + 1) * AID_STATION_INTERVAL_MILES
    return next_station - course_distance


def sweeper_time(course_distance):
    """Minute mark at which the sweeper vehicle reaches this point."""
    return course_distance * SWEEPER_PACE_PER_MILE


def is_disqualified(course_distance, elapsed_minutes):
    cutoff = sweeper_time(course_distance) + DISQUALIFICATION_BUFFER_MINUTES
    return elapsed_minutes > cutoff


def required_pace(course_distance, elapsed_minutes):
    """Minutes per mile needed to reach the finish before the course closes."""
    remaining_distance = MARATHON_DISTANCE_MILES - course_distance
    if remaining_distance <= 0:
        return 0.0
    remaining_time = MAX_COURSE_FINISH_MINUTES - elapsed_minutes
    if remaining_time <= 0:
        return 0.0
    return remaining_time / remaining_distance


def pace(runners):
    """Return (miles to next aid station, required pace, disqualified) per runner."""
    report = []
    for total_distance, elapsed_minutes in runners:
        if total_distance < STARTING_LINE_OFFSET_MILES:
            raise ValueError("distance is behind the starting line")
        if elapsed_minutes < 0:
            raise ValueError("elapsed time cannot be negative")
        course_distance = adjusted_distance(total_distance)
        aid_gap = distance_to_next_aid_station(course_distance)
        if is_disqualified(course_distance, elapsed_minutes):
            report.append((aid_gap, 0.0, True))
        else:
            report.append((aid_gap, required_pace(course_distance, elapsed_minutes), False))
    return report


def format_row(index, result):
    aid_gap, needed_pace, disqualified = result
    if disqualified:
        status = "DQ (swept)"
    elif needed_pace == 0.0:
        status = "finished"
    else:
        status = "{:.2f} min/mi to beat {:.0f} min".format(needed_pace, MAX_COURSE_FINISH_MINUTES)
    return "Runner {}: aid station in {:.2f} mi - {}".format(index, aid_gap, status)


def main():
    runners = [
        (5.1, 48.0),
        (13.2, 210.0),
        (20.1, 320.0),
        (MARATHON_DISTANCE_MILES + STARTING_LINE_OFFSET_MILES, 355.0),
    ]
    for index, result in enumerate(pace(runners), start=1):
        print(format_row(index, result))


if __name__ == "__main__":
    main()

