text_nat:
MIN_FM_FREQUENCY = 88.1
MAX_FM_FREQUENCY = 107.9
MIN_STATION_SPACING = 0.4
MAX_POWER_LIMIT = 100.0
INTERFERENCE_THRESHOLD = 75.0
BAND_EDGE_GUARD = 0.2
BORDER_ATTENUATION = 0.85
POWER_REDUCTION_FACTOR = 0.5


def clamp_frequency(frequency):
    """Pull a requested frequency strictly inside the usable FM band."""
    lowest = MIN_FM_FREQUENCY + BAND_EDGE_GUARD
    highest = MAX_FM_FREQUENCY - BAND_EDGE_GUARD
    if frequency < lowest:
        return lowest
    if frequency > highest:
        return highest
    return frequency


def cap_power(power):
    """Never allow a transmitter above the licensed ceiling."""
    if power < 0:
        return 0.0
    return min(float(power), MAX_POWER_LIMIT)


def spacing_conflict(frequency, assigned):
    """True when the frequency crowds an already approved station."""
    for other, _power in assigned:
        if abs(frequency - other) < MIN_STATION_SPACING:
            return True
    return False


def resolve_spacing(frequency, assigned):
    """Shift upward by whole intervals until the slot is clear."""
    while spacing_conflict(frequency, assigned):
        frequency += MIN_STATION_SPACING
        if frequency >= MAX_FM_FREQUENCY:
            return None
    return round(frequency, 2)


def border_power(power):
    """Projected field strength reaching the local borders."""
    return power * BORDER_ATTENUATION


def limit_interference(power):
    """Halve the power when the border projection is too loud."""
    if border_power(power) > INTERFERENCE_THRESHOLD:
        return round(power * POWER_REDUCTION_FACTOR, 2)
    return round(power, 2)


def allocate(stations):
    """Assign a legal frequency and power to every request."""
    assigned = []
    for requested_frequency, requested_power in stations:
        frequency = clamp_frequency(float(requested_frequency))
        power = cap_power(requested_power)
        frequency = resolve_spacing(frequency, assigned)
        if frequency is None:
            continue
        assigned.append((frequency, limit_interference(power)))
    return assigned


def format_report(allocations):
    """Human readable licence table for the authority's records."""
    lines = []
    for frequency, power in allocations:
        lines.append("{0:6.2f} MHz  {1:6.2f} kW".format(frequency, power))
    return "\n".join(lines)


def main():
    requests = [
        (88.1, 120.0),
        (88.2, 60.0),
        (88.3, 90.0),
        (107.9, 95.0),
        (95.5, -5.0),
    ]
    print(format_report(allocate(requests)))


if __name__ == "__main__":
    main()

