        if abs(frequency - other) < minStationSpacing:
            return True
    return False


def resolve_spacing(frequency, assigned):
    """Shift upward by whole intervals until the slot is clear."""
    while spacing_conflict(frequency, assigned):
        frequency += minStationSpacing
        if frequency >= maxFmFrequency:
            return None
    return round(frequency, 2)


def border_power(power):
    """Projected field strength reaching the local borders."""
    return power * borderAttenuation


def limit_interference(power):
    """Halve the power when the border projection is too loud."""
    if border_power(power) > interferenceThreshold:
        return round(power * powerReductionFactor, 2)
    return round(power, 2)


def allocate(stations):
    """Assign a legal frequency and power to every request."""
    assigned = []
    for requested_frequency, requested_power in stations:
        frequency = clamp_frequency(float(requested_frequency))
        power = cap_power(requested_power)
        frequency = resolve_spacing(frequency, assigned)
        if frequency is None:
            continue
        assigned.append((frequency, limit_interference(power)))
    return assigned


def format_report(allocations):
    """Human readable licence table for the authority's records."""
    lines = []
    for frequency, power in allocations:
        lines.append("{0:6.2f} MHz  {1:6.2f} kW".format(frequency, power))
    return "\n".join(lines)


def main():
