OVERDUE_RATE_PER_DAY = 0.25
MAX_LATE_FINE = 15.00
GRACE_PERIOD_DAYS = 3
LOST_ITEM_REPLACEMENT_FEE = 45.00
PROCESSING_SURCHARGE = 1.50
CURRENCY_SYMBOL = "$"
ROUNDING_DIGITS = 2


def parse_entry(entry):
    """Validate one (days_overdue, is_lost) tuple and return it normalised."""
    try:
        days, lost = entry
    except (TypeError, ValueError):
        raise ValueError("each return must be a (days_overdue, is_lost) pair")
    if isinstance(days, bool) or not isinstance(days, int):
        raise ValueError("days_overdue must be an integer")
    if days < 0:
        raise ValueError("days_overdue must not be negative")
    return days, bool(lost)


def lost_item_fee():
    """Charge for an item declared lost; late days are irrelevant."""
    return round(LOST_ITEM_REPLACEMENT_FEE + PROCESSING_SURCHARGE, ROUNDING_DIGITS)


def raw_late_fee(days):
    """Uncapped daily accrual for an overdue item."""
    return days * OVERDUE_RATE_PER_DAY


def late_fee(days):
    """Fee for an overdue but returned item, including the surcharge."""
    if days <= GRACE_PERIOD_DAYS:
        return 0.0
    capped = min(raw_late_fee(days), MAX_LATE_FINE)
    return round(capped + PROCESSING_SURCHARGE, ROUNDING_DIGITS)


def item_fee(days, lost):
    if lost:
        return lost_item_fee()
    return late_fee(days)


def process(returns):
    """Return the list of total fees to charge, one per returned item."""
    fees = []
    for entry in returns:
        days, lost = parse_entry(entry)
        fees.append(item_fee(days, lost))
    return fees


def format_amount(amount):
    return "{}{:.2f}".format(CURRENCY_SYMBOL, round(amount, ROUNDING_DIGITS))


def summarize(returns, fees):
    """Build human-readable report lines for a batch of returns."""
    lines = ["Fees waived up to {} day(s) overdue".format(GRACE_PERIOD_DAYS)]
    capped = 0
    for (days, lost), fee in zip(returns, fees):
        label = "lost" if lost else "{} day(s) overdue".format(days)
        if not lost and raw_late_fee(days) > MAX_LATE_FINE:
            capped += 1
            label += " (fine capped)"
        lines.append("  {:<28} {}".format(label, format_amount(fee)))
    lines.append("Items at the {} cap: {}".format(format_amount(MAX_LATE_FINE), capped))
    lines.append("Batch total: {}".format(format_amount(sum(fees))))
    return lines


def main():
    returns = [(0, False), (3, False), (7, False), (120, False), (12, True)]
    for line in summarize(returns, process(returns)):
        print(line)


if __name__ == "__main__":
    main()

