OXYGEN_CONSUMPTION_PER_HOUR = 0.084  # kg of O2 per crew member per hour
CO2_DANGER_LIMIT = 0.5  # percent of cabin atmosphere
EMERGENCY_WATER_RATION = 3.5  # liters per crew member
NOMINAL_CABIN_PRESSURE = 101.3  # kPa
FILTRATION_RATE = 0.35  # fraction of CO2 removed per scrubber pass
MAX_RETRIES = 3  # scrubber passes attempted before declaring failure
DEFAULT_TIMEOUT = 90.0  # seconds the crew has to react to an emergency


def validate_packet(packet):
    if len(packet) != 4:
        raise ValueError("telemetry packet must hold 4 fields")
    crew, hours, pressure, co2 = packet
    if crew < 1:
        raise ValueError("crew size must be at least 1")
    if hours <= 0:
        raise ValueError("mission duration must be positive")
    if pressure <= 0:
        raise ValueError("cabin pressure must be positive")
    if co2 < 0:
        raise ValueError("CO2 level cannot be negative")
    return crew, float(hours), float(pressure), float(co2)


def required_oxygen(crew, hours):
    return crew * hours * OXYGEN_CONSUMPTION_PER_HOUR


def required_water(crew):
    return crew * EMERGENCY_WATER_RATION


def filtered_co2(co2):
    level = co2
    for _ in range(MAX_RETRIES):
        level *= 1.0 - FILTRATION_RATE
        if level <= CO2_DANGER_LIMIT:
            break
    return level


def evacuation_needed(pressure, co2):
    if pressure < NOMINAL_CABIN_PRESSURE:
        return True
    return co2 > CO2_DANGER_LIMIT


def monitor(telemetry):
    results = []
    for packet in telemetry:
        crew, hours, pressure, co2 = validate_packet(packet)
        oxygen = required_oxygen(crew, hours)
        water = required_water(crew)
        scrubbed = filtered_co2(co2)
        results.append((round(oxygen, 2), round(water, 2),
                        evacuation_needed(pressure, scrubbed)))
    return results


def format_report(index, oxygen, water, emergency):
    status = "EVACUATE within %.0f s" % DEFAULT_TIMEOUT if emergency else "nominal"
    return "packet %d: O2=%.2f kg, H2O=%.2f L, %s" % (index, oxygen, water, status)


def main():
    telemetry = [
        (4, 72, 101.4, 0.42),
        (6, 120, 98.7, 0.31),
        (3, 48, 101.5, 1.60),
        (5, 240, 102.0, 0.55),
    ]
    for index, (oxygen, water, emergency) in enumerate(monitor(telemetry)):
        print(format_report(index, oxygen, water, emergency))


if __name__ == "__main__":
    main()

