SPACE_PER_JUMPER_SQM = 4.5
SESSION_DURATION_MINUTES = 50
CLEANING_BUFFER_MINUTES = 10
WAIVER_EXPIRY_LIMIT_DAYS = 365
MAX_LIABILITY_OCCUPANCY = 30
OPERATING_WINDOW_MINUTES = 8 * 60


def is_waiver_valid(waiver_age_days):
    """A waiver counts as valid while it is younger than the expiry limit."""
    return 0 <= waiver_age_days < WAIVER_EXPIRY_LIMIT_DAYS


def capacity_from_area(floor_area):
    """How many jumpers physically fit in the requested zone."""
    if floor_area < SPACE_PER_JUMPER_SQM:
        return 0
    return int(floor_area // SPACE_PER_JUMPER_SQM)


def cap_group_size(group_size, floor_area):
    """Smallest of the requested group, the area capacity and the liability cap."""
    area_capacity = capacity_from_area(floor_area)
    return min(group_size, area_capacity, MAX_LIABILITY_OCCUPANCY)


def session_slots():
    """Sessions that fit into the operating window, cleaning included."""
    turnaround = SESSION_DURATION_MINUTES + CLEANING_BUFFER_MINUTES
    return OPERATING_WINDOW_MINUTES // turnaround


def validate_booking(booking):
    group_size, waiver_age_days, floor_area = booking
    if group_size < 1:
        raise ValueError("group size must be at least one jumper")
    if floor_area <= 0:
        raise ValueError("requested zone floor area must be positive")
    if waiver_age_days < 0:
        raise ValueError("waiver age cannot be negative")
    return group_size, waiver_age_days, float(floor_area)


def schedule(bookings):
    results = []
    slots = session_slots()
    for booking in bookings:
        group_size, waiver_age_days, floor_area = validate_booking(booking)
        waiver_ok = is_waiver_valid(waiver_age_days)
        if not waiver_ok:
            results.append((0, 0, False))
            continue
        results.append((cap_group_size(group_size, floor_area), slots, True))
    return results


def format_report(bookings, results):
    lines = ["Trampoline facility daily plan",
             "  space per jumper: %.1f sqm" % SPACE_PER_JUMPER_SQM,
             "  session length: %d min (+%d min cleaning)"
             % (SESSION_DURATION_MINUTES, CLEANING_BUFFER_MINUTES)]
    for booking, (allowed, slots, waiver_ok) in zip(bookings, results):
        requested = booking[0]
        if not waiver_ok:
            lines.append("  %2d jumpers -> rejected, waiver older than %d days"
                         % (requested, WAIVER_EXPIRY_LIMIT_DAYS))
        else:
            note = ""
            if allowed == MAX_LIABILITY_OCCUPANCY < requested:
                note = " (liability cap reached)"
            lines.append("  %2d jumpers -> %2d admitted across %d slots%s"
                         % (requested, allowed, slots, note))
    return "\n".join(lines)


def main():
    bookings = [(12, 30, 80.0), (40, 10, 400.0), (8, 400, 60.0), (6, 0, 20.0)]
    results = schedule(bookings)
    print(format_report(bookings, results))


if __name__ == "__main__":
    main()

