text_nat:
DEFAULT_OSC_FREQUENCY = 440.0
MAX_FILTER_CUTOFF = 18000.0
MIN_SAFE_RESONANCE = 0.15
MAX_ATTACK_SECONDS = 0.35
MASTER_VOLUME_CAP = 0.8


def resolve_pitch(pitch):
    """Substitute silent oscillators with the default tuning frequency."""
    if pitch == 0:
        return DEFAULT_OSC_FREQUENCY
    return abs(float(pitch))


def clamp_cutoff(cutoff):
    """Keep the filter inside the audible/anti-aliasing safe range."""
    cutoff = max(0.0, float(cutoff))
    if cutoff > MAX_FILTER_CUTOFF:
        return MAX_FILTER_CUTOFF
    return cutoff


def lift_resonance(resonance):
    """Raise weak resonance so the filter still produces audible harmonics."""
    resonance = float(resonance)
    if resonance < MIN_SAFE_RESONANCE:
        return MIN_SAFE_RESONANCE
    return resonance


def limit_attack(attack):
    """Shorten long attacks so percussive transients survive."""
    attack = max(0.0, float(attack))
    return min(attack, MAX_ATTACK_SECONDS)


def normalization_factor():
    """Gain factor derived from the master volume cap."""
    return MASTER_VOLUME_CAP / (1.0 + MASTER_VOLUME_CAP)


def scale_patch(pitch, cutoff, resonance, attack):
    """Apply the master normalization gain to every numeric field."""
    gain = normalization_factor()
    return (
        round(pitch * gain, 4),
        round(cutoff * gain, 4),
        round(resonance * gain, 4),
        round(attack * gain, 6),
    )


def synthesize(patches):
    """Sanitize and normalize a list of (pitch, cutoff, resonance, attack) patches."""
    sanitized = []
    for pitch, cutoff, resonance, attack in patches:
        safe_pitch = resolve_pitch(pitch)
        safe_cutoff = clamp_cutoff(cutoff)
        safe_resonance = lift_resonance(resonance)
        safe_attack = limit_attack(attack)
        sanitized.append(scale_patch(safe_pitch, safe_cutoff, safe_resonance, safe_attack))
    return sanitized


def format_report(patches, results):
    """Render a human-readable comparison of requested versus sanitized values."""
    lines = ["idx  pitch(Hz)      cutoff(Hz)     resonance   attack(s)"]
    for index, (request, result) in enumerate(zip(patches, results)):
        flags = []
        if request[0] == 0:
            flags.append("pitch->%.1f" % DEFAULT_OSC_FREQUENCY)
        if request[1] > MAX_FILTER_CUTOFF:
            flags.append("cutoff clamped")
        if request[2] < MIN_SAFE_RESONANCE:
            flags.append("resonance lifted")
        if request[3] > MAX_ATTACK_SECONDS:
            flags.append("attack shortened")
        lines.append(
            "%3d  %-13.4f  %-13.4f  %-10.4f  %-9.6f %s"
            % (index, result[0], result[1], result[2], result[3], ", ".join(flags))
        )
    return "\n".join(lines)


def main():
    patches = [
        (0, 22000.0, 0.02, 1.2),
        (220.0, 8000.0, 0.6, 0.1),
        (-110.0, 19000.0, 0.15, 0.35),
    ]
    results = synthesize(patches)
    print(format_report(patches, results))
    print("normalization gain: %.4f" % normalization_factor())


if __name__ == "__main__":
    main()

