MAX_STROKES_PAR_LIMIT = 10
OUT_OF_BOUNDS_PENALTY = 2
WATER_HAZARD_PENALTY = 1
HOLE_IN_ONE_BONUS = 2
STANDARD_COURSE_PAR = 3
MAX_RETRIES = 3
DEFAULT_TIMEOUT = 0.5


def validate_hole(entry):
    """Normalise one scorecard entry into three non-negative integers."""
    strokes, out_of_bounds, water = entry
    values = (int(strokes), int(out_of_bounds), int(water))
    if values[0] < 1:
        raise ValueError("a played hole needs at least one stroke")
    if values[1] < 0 or values[2] < 0:
        raise ValueError("penalty counts cannot be negative")
    return values


def apply_hole_in_one_bonus(strokes):
    """Reward a single-stroke hole by deducting the bonus."""
    if strokes == 1:
        return strokes - HOLE_IN_ONE_BONUS
    return strokes


def penalty_strokes(out_of_bounds, water):
    """Total extra strokes charged for out-of-bounds shots and water hazards."""
    return out_of_bounds * OUT_OF_BOUNDS_PENALTY + water * WATER_HAZARD_PENALTY


def cap_strokes(strokes):
    """Clamp a hole total so one disastrous hole cannot dominate the card."""
    return min(strokes, MAX_STROKES_PAR_LIMIT)


def net_score(entry):
    """Relative score for a single hole, measured against the course par."""
    strokes, out_of_bounds, water = validate_hole(entry)
    total = apply_hole_in_one_bonus(strokes)
    total += penalty_strokes(out_of_bounds, water)
    return cap_strokes(total) - STANDARD_COURSE_PAR


def tally(rounds):
    """Relative net score for every hole on the card."""
    return [net_score(entry) for entry in rounds]


def fetch_card(source):
    """Read a scorecard from a flaky source, retrying transient failures."""
    from time import sleep
    last_error = None
    for attempt in range(MAX_RETRIES):
        try:
            return source(timeout=DEFAULT_TIMEOUT)
        except (OSError, TimeoutError) as exc:
            last_error = exc
            sleep(DEFAULT_TIMEOUT * (attempt + 1))
    raise RuntimeError("scorecard unavailable after %d attempts" % MAX_RETRIES) from last_error


def format_report(scores):
    """Human readable summary: per-hole result plus the card total."""
    lines = []
    for index, score in enumerate(scores, start=1):
        marker = "E" if score == 0 else "%+d" % score
        lines.append("Hole %2d: %s (par %d)" % (index, marker, STANDARD_COURSE_PAR))
    lines.append("Total: %+d over %d holes" % (sum(scores), len(scores)))
    return "\n".join(lines)


def main():
    def local_source(timeout=DEFAULT_TIMEOUT):
        return [(1, 0, 0), (3, 0, 0), (4, 1, 0), (2, 0, 2), (9, 3, 2), (5, 0, 1)]

    card = fetch_card(local_source)
    print(format_report(tally(card)))


if __name__ == "__main__":
    main()

