MIN_RIDER_HEIGHT_CM = 120
MAX_CARRIAGE_PAYLOAD_KG = 450
BASE_DISPATCH_INTERVAL_SECONDS = 90
RAIN_DELAY_MINUTES = 15
RESTRAINT_LOCK_THRESHOLD = 3
RAINY_WEATHER = "rainy"
SECONDS_PER_MINUTE = 60
STATUS_CLEAR = "CLEAR"


def find_short_riders(heights):
    """Return the heights of passengers who are too short to ride."""
    return [h for h in heights if h < MIN_RIDER_HEIGHT_CM]


def is_payload_safe(total_weight):
    """The carriage may not carry more than its rated payload."""
    return total_weight <= MAX_CARRIAGE_PAYLOAD_KG


def are_restraints_locked(clicks):
    """Restraints only count as locked once enough clicks are engaged."""
    return clicks >= RESTRAINT_LOCK_THRESHOLD


def estimate_wait_seconds(weather):
    """Base interval, extended by the rain delay during inclement weather."""
    wait = BASE_DISPATCH_INTERVAL_SECONDS
    if str(weather).strip().lower() == RAINY_WEATHER:
        wait += RAIN_DELAY_MINUTES * SECONDS_PER_MINUTE
    return wait


def build_safety_status(short_riders, total_weight, clicks):
    """Collect every blocking condition into a single human-readable status."""
    problems = []
    if short_riders:
        shortest = min(short_riders)
        problems.append(
            "HEIGHT VIOLATION: {0}cm rider below {1}cm".format(shortest, MIN_RIDER_HEIGHT_CM)
        )
    if not is_payload_safe(total_weight):
        overload = total_weight - MAX_CARRIAGE_PAYLOAD_KG
        problems.append("OVERWEIGHT: {0}kg over limit".format(overload))
    if not are_restraints_locked(clicks):
        problems.append(
            "RESTRAINTS UNLOCKED: {0} of {1} clicks".format(clicks, RESTRAINT_LOCK_THRESHOLD)
        )
    if not problems:
        return STATUS_CLEAR
    return "; ".join(problems)


def supervise(rides):
    """Evaluate each ride cycle and report dispatch, wait time and safety status."""
    report = []
    for heights, total_weight, weather, clicks in rides:
        short_riders = find_short_riders(heights)
        status = build_safety_status(short_riders, total_weight, clicks)
        dispatch = status == STATUS_CLEAR
        report.append((dispatch, estimate_wait_seconds(weather), status))
    return report


def format_line(index, result):
    dispatch, wait, status = result
    verdict = "DISPATCH" if dispatch else "HOLD"
    return "Cycle {0}: {1} | wait {2}s | {3}".format(index, verdict, wait, status)


def main():
    rides = [
        ([135, 142, 158, 121], 402, "sunny", 4),
        ([118, 150, 147], 380, "rainy", 5),
        ([160, 165, 170, 175], 470, "cloudy", 3),
        ([130, 128, 144], 340, RAINY_WEATHER, 1),
    ]
    for index, result in enumerate(supervise(rides), start=1):
        print(format_line(index, result))


if __name__ == "__main__":
    main()

