IDEAL_FERMENT_TEMP = 20.0
MAX_PRESSURE_LIMIT = 15.0
MIN_FINAL_GRAVITY = 1.010
YEAST_RATE_PER_LITRE = 0.75
COOLING_JACKET_CAPACITY = 8.0
MAX_RETRIES = 3
DEFAULT_TIMEOUT = 5.0


def required_yeast(volume):
    """Grams of yeast needed to pitch a batch of the given volume."""
    return round(volume * YEAST_RATE_PER_LITRE, 2)


def cooling_percentage(temperature):
    """Percentage of jacket power needed to pull the vat back to target."""
    if temperature <= IDEAL_FERMENT_TEMP:
        return 0.0
    excess = temperature - IDEAL_FERMENT_TEMP
    return round(min(excess / COOLING_JACKET_CAPACITY * 100.0, 100.0), 1)


def pressure_warning(pressure):
    """True when the vat head pressure is above the safe limit."""
    return pressure > MAX_PRESSURE_LIMIT


def fermentation_complete(gravity):
    """True once the sugar has been consumed down to the final gravity."""
    return gravity < MIN_FINAL_GRAVITY


def read_sensor(vat, attempt_log):
    """Unpack a sensor tuple, retrying while readings are incomplete."""
    for attempt in range(1, MAX_RETRIES + 1):
        if len(vat) == 4:
            volume, temperature, pressure, gravity = vat
            attempt_log.append(attempt)
            return float(volume), float(temperature), float(pressure), float(gravity)
        vat = tuple(vat) + (0.0,) * (4 - len(vat))
    raise ValueError("sensor bus unresponsive after %d retries" % MAX_RETRIES)


def brew(vats):
    """Analyse every vat and return (yeast, cooling %, pressure warning)."""
    report = []
    attempt_log = []
    for vat in vats:
        volume, temperature, pressure, gravity = read_sensor(vat, attempt_log)
        report.append((
            required_yeast(volume),
            cooling_percentage(temperature),
            pressure_warning(pressure),
        ))
        if fermentation_complete(gravity):
            print("Vat of %.1fL: fermentation complete, ready to crash-cool" % volume)
    if attempt_log and max(attempt_log) > 1:
        print("Sensor bus retried; polling interval reset to %.1fs" % DEFAULT_TIMEOUT)
    return report


def format_report(rows):
    """Render the analysis rows as fixed-width monitoring lines."""
    lines = []
    for index, (yeast, cooling, warning) in enumerate(rows, start=1):
        state = "VENT!" if warning else "ok"
        lines.append("Vat %d: yeast %7.2fg | cooling %5.1f%% | %s"
                     % (index, yeast, cooling, state))
    return "\n".join(lines)


def main():
    vats = [
        (500.0, 18.5, 12.0, 1.048),
        (1000.0, 24.0, 16.2, 1.008),
        (250.0, 32.0, 9.4, 1.020),
        (750.0, 20.0, 15.0),
    ]
    rows = brew(vats)
    print(format_report(rows))
    print("Next poll in %.1fs (up to %d retries per vat)" % (DEFAULT_TIMEOUT, MAX_RETRIES))


if __name__ == "__main__":
    main()

