text_nat:
BASE_MONTHLY_RATE = 50
PREMIUM_SURCHARGE = 20
CANCELLATION_FEE = 75
MIN_MONTHS_WITHOUT_FEE = 3
SESSION_COST = 30
MAX_SESSIONS_PER_MONTH = 4
BASIC_PLAN = "basic"
PREMIUM_PLAN = "premium"
PLAN_SURCHARGES = {
    BASIC_PLAN: 0,
    PREMIUM_PLAN: PREMIUM_SURCHARGE,
}
CURRENCY_SYMBOL = "$"


def validate_member(months, plan, sessions):
    if plan not in PLAN_SURCHARGES:
        raise ValueError("unknown plan: {0!r}".format(plan))
    if months < 0:
        raise ValueError("months active cannot be negative")
    if sessions < 0:
        raise ValueError("training sessions cannot be negative")


def monthly_rate(plan):
    return BASE_MONTHLY_RATE + PLAN_SURCHARGES[plan]


def session_charge(sessions):
    return min(sessions, MAX_SESSIONS_PER_MONTH) * SESSION_COST


def cancellation_charge(months, plan, cancelling):
    if not cancelling:
        return 0
    if plan == PREMIUM_PLAN:
        return 0
    if months < MIN_MONTHS_WITHOUT_FEE:
        return CANCELLATION_FEE
    return 0


def bill(members):
    totals = []
    for months, plan, sessions, cancelling in members:
        validate_member(months, plan, sessions)
        total = monthly_rate(plan)
        total += session_charge(sessions)
        total += cancellation_charge(months, plan, cancelling)
        totals.append(total)
    return totals


def format_invoice(members, totals):
    lines = []
    for (months, plan, sessions, cancelling), total in zip(members, totals):
        notes = []
        if sessions > MAX_SESSIONS_PER_MONTH:
            notes.append("{0} of {1} sessions billed".format(MAX_SESSIONS_PER_MONTH, sessions))
        if cancelling and plan == PREMIUM_PLAN:
            notes.append("cancellation fee waived")
        elif cancelling and months < MIN_MONTHS_WITHOUT_FEE:
            notes.append("early cancellation fee applied")
        detail = "; ".join(notes) if notes else "standard billing"
        lines.append(
            "{0:>7} plan, month {1}: {2}{3} ({4})".format(
                plan, months, CURRENCY_SYMBOL, total, detail
            )
        )
    return "\n".join(lines)


def main():
    members = [(2, BASIC_PLAN, 1, True), (4, PREMIUM_PLAN, 5, False)]
    totals = bill(members)
    print(totals)
    print(format_invoice(members, totals))


if __name__ == "__main__":
    main()

