DEGRADATION_PER_YEAR = 0.02
MIN_EFFICIENCY = 0.0
HOURS_PER_DAY = 24.0
CURRENCY_PRECISION = 2
CURRENCY_SYMBOL = "$"


def validate_setup(area, hours, years):
    """Reject physically impossible panel descriptions."""
    if area < 0:
        raise ValueError("panel area cannot be negative")
    if hours < 0 or hours > HOURS_PER_DAY:
        raise ValueError("daily hours of sun must be between 0 and %g" % HOURS_PER_DAY)
    if years < 0:
        raise ValueError("years installed cannot be negative")


def efficiency(years):
    """Remaining output fraction after annual degradation."""
    remaining = 1.0 - DEGRADATION_PER_YEAR * years
    if remaining < MIN_EFFICIENCY:
        return MIN_EFFICIENCY
    return remaining


def effective_power(area):
    """Generated power in watts, limited by the inverter."""
    raw = area * WATTS_PER_SQUARE_METER
    if raw > MAX_INVERTER_WATTS:
        return MAX_INVERTER_WATTS
    return raw


def daily_kilowatt_hours(area, hours, years):
    energy_watt_hours = effective_power(area) * hours * efficiency(years)
    return energy_watt_hours / WATTS_PER_KILOWATT


def estimate(panels):
    """Daily monetary return for each (area, hours, years) panel setup."""
    returns = []
    for area, hours, years in panels:
        validate_setup(area, hours, years)
        revenue = daily_kilowatt_hours(area, hours, years) * PRICE_PER_KWH
        returns.append(round(revenue, CURRENCY_PRECISION))
