OPTIMAL_LEVEL = 300
CRITICAL_LEVEL = 350
BASE_RELEASE_RATE = 50
SPILLWAY_RELEASE_RATE = 200
MIN_ENVIRONMENTAL_RELEASE = 10
MIN_RESERVOIR_LEVEL = 0
ENTRY_FIELD_COUNT = 3


def select_release_rate(level):
    """Pick the hourly release rate dictated by the starting reservoir level."""
    if level > CRITICAL_LEVEL:
        return SPILLWAY_RELEASE_RATE
    if level < OPTIMAL_LEVEL:
        return MIN_ENVIRONMENTAL_RELEASE
    return BASE_RELEASE_RATE


def validate_entry(entry):
    """Return a (level, inflow, hours) triple, raising ValueError on bad input."""
    if len(entry) != ENTRY_FIELD_COUNT:
        raise ValueError("each entry needs level, inflow and hours: %r" % (entry,))
    level, inflow, hours = entry
    if level < MIN_RESERVOIR_LEVEL:
        raise ValueError("reservoir level cannot be negative: %r" % (level,))
    if inflow < 0:
        raise ValueError("inflow rate cannot be negative: %r" % (inflow,))
    if hours < 0:
        raise ValueError("projection window cannot be negative: %r" % (hours,))
    return level, inflow, hours


def project_level(level, inflow, hours):
    """Project the reservoir level after `hours` of constant inflow and release."""
    rate = select_release_rate(level)
    projected = level + (inflow - rate) * hours
    return max(projected, MIN_RESERVOIR_LEVEL)


def regulate(levels):
    """Return the projected final water level for every reservoir reading."""
    results = []
    for entry in levels:
        level, inflow, hours = validate_entry(entry)
        results.append(project_level(level, inflow, hours))
    return results


def classify(level):
    """Label a projected level for the operator report."""
    if level > CRITICAL_LEVEL:
        return "FLOOD RISK"
    if level < OPTIMAL_LEVEL:
        return "BELOW OPTIMAL"
    return "NORMAL"


def format_report(levels, projections):
    """Build one report line per reservoir, showing the rate that was applied."""
    lines = []
    for (level, inflow, hours), final in zip(levels, projections):
        rate = select_release_rate(level)
        lines.append(
            "start=%d inflow=%d/h hours=%d release=%d/h -> final=%d (%s)"
            % (level, inflow, hours, rate, final, classify(final))
        )
    return "\n".join(lines)


def main():
    readings = [(360, 20, 2), (290, 15, 2), (320, 40, 6), (400, 120, 3)]
    projections = regulate(readings)
    print(projections)
    print(format_report(readings, projections))
    flooding = [f for f in projections if f > CRITICAL_LEVEL]
    if flooding:
        print("spillway follow-up required for %d reservoir(s)" % len(flooding))
    else:
        print("all reservoirs projected at or below %d" % CRITICAL_LEVEL)


if __name__ == "__main__":
    main()

