SAFE_PRESSURE = 100
PRESSURIZATION_RATE = 5
DEPRESSURIZATION_RATE = 8
MIN_LIFE_SUPPORT = 20
MAX_SAFE_PRESSURE = 150


def validate_cycle(cycle):
    """Check one (start, target, minutes) tuple and return it normalised."""
    if len(cycle) != 3:
        raise ValueError("each cycle needs start, target and duration")
    start, target, minutes = (float(value) for value in cycle)
    if minutes < 0:
        raise ValueError("duration cannot be negative")
    for pressure in (start, target):
        if pressure < MIN_LIFE_SUPPORT:
            raise ValueError("pressure below life support threshold: %g" % pressure)
        if pressure > MAX_SAFE_PRESSURE:
            raise ValueError("pressure above safe cap: %g" % pressure)
    return start, target, minutes


def rise_to(start, target, minutes):
    """Pressurize for the given time, stopping at the target or the safe cap."""
    reached = start + PRESSURIZATION_RATE * minutes
    return min(reached, target, MAX_SAFE_PRESSURE)


def fall_to(start, target, minutes):
    """Depressurize for the given time, never dropping below life support."""
    reached = start - DEPRESSURIZATION_RATE * minutes
    return max(reached, target, MIN_LIFE_SUPPORT)


def run_cycle(cycle):
    start, target, minutes = validate_cycle(cycle)
    if target > start:
        final = rise_to(start, target, minutes)
    elif target < start:
        final = fall_to(start, target, minutes)
    else:
        final = start
    return int(final) if float(final).is_integer() else final


def classify(pressure):
    if pressure >= SAFE_PRESSURE:
        return "breathable"
    if pressure <= MIN_LIFE_SUPPORT:
        return "vacuum-ready"
    return "transitioning"


def pressurize(cycles):
    """Return the final pressure of every airlock cycle."""
    return [run_cycle(cycle) for cycle in cycles]


def format_report(cycles, results):
    lines = []
    for (start, target, minutes), final in zip(cycles, results):
        headroom = MAX_SAFE_PRESSURE - final
        lines.append(
            "%3s -> %-3s in %2s min: %-5s (%s, %g kPa below cap)"
            % (start, target, minutes, final, classify(final), headroom)
        )
    return "\n".join(lines)


def main():
    cycles = [(80, 100, 10), (100, 20, 5), (20, 150, 40), (95, 95, 3)]
    results = pressurize(cycles)
    print(results)
    print(format_report(cycles, results))
    safe = sum(1 for pressure in results if pressure >= SAFE_PRESSURE)
    print("%d of %d cycles ended at or above %g" % (safe, len(results), SAFE_PRESSURE))


if __name__ == "__main__":
    main()

