STANDARD_SET_MINUTES = 45
HEADLINE_SET_MINUTES = 90
CHANGEOVER_MINUTES = 15
CURFEW_MINUTES = 1000
HEADLINE_POPULARITY_THRESHOLD = 80
MINUTES_PER_HOUR = 60
BAND_FIELD_COUNT = 3


def validate_band(band):
    """Raise ValueError if a lineup entry is not a usable (genre, duration, popularity) tuple."""
    if len(band) != BAND_FIELD_COUNT:
        raise ValueError("each band needs exactly %d fields" % BAND_FIELD_COUNT)
    genre, duration, popularity = band
    if not str(genre).strip():
        raise ValueError("band genre must not be empty")
    if duration <= 0:
        raise ValueError("requested duration must be positive: %r" % (duration,))
    if popularity < 0:
        raise ValueError("popularity score must not be negative: %r" % (popularity,))


def set_length(duration, popularity):
    """Return the granted stage time for one band."""
    if popularity > HEADLINE_POPULARITY_THRESHOLD:
        allowance = HEADLINE_SET_MINUTES
    else:
        allowance = STANDARD_SET_MINUTES
    return min(duration, allowance)


def schedule(bands):
    """Return [(start, end)] in minutes from festival start, in lineup order."""
    slots = []
    cursor = 0
    for band in bands:
        validate_band(band)
        _, duration, popularity = band
        end = cursor + set_length(duration, popularity)
        if end > CURFEW_MINUTES:
            break
        slots.append((cursor, end))
        cursor = end + CHANGEOVER_MINUTES
    return slots


def format_clock(minutes):
    return "%d:%02d" % (minutes // MINUTES_PER_HOUR, minutes % MINUTES_PER_HOUR)


def build_report(bands, slots):
    lines = []
    for band, (start, end) in zip(bands, slots):
        genre, duration, popularity = band
        billing = "headline" if popularity > HEADLINE_POPULARITY_THRESHOLD else "support"
        lines.append("%-6s %-8s %s-%s (%d of %d min requested)"
                     % (genre, billing, format_clock(start), format_clock(end),
                        end - start, duration))
    dropped = len(bands) - len(slots)
    if dropped:
        lines.append("%d band(s) cut: curfew is %s" % (dropped, format_clock(CURFEW_MINUTES)))
    last_end = slots[-1][1] if slots else 0
    lines.append("stage free again at %s, %d min before curfew"
                 % (format_clock(last_end), CURFEW_MINUTES - last_end))
    return "\n".join(lines)


def main():
    lineup = [("rock", 60, 50), ("pop", 120, 85), ("folk", 30, 20), ("metal", 95, 99)]
    print(schedule([("rock", 60, 50), ("pop", 120, 85)]))
    print(build_report(lineup, schedule(lineup)))


if __name__ == "__main__":
    main()

