text_nat:
OVEN_CAPACITY = 20
BATCH_MINUTES = 40
SOURDOUGH_REST_MINUTES = 120
URGENT_FEE = 15
PRICE_PER_LOAF = 3
MIN_LOAVES_PER_ORDER = 1
SOURDOUGH_NAME = "sourdough"


def validate_order(order):
    """Unpack one order tuple and return (loaves, bread_type, urgent)."""
    if len(order) != 3:
        raise ValueError("each order needs (loaves, bread type, urgent flag)")
    loaves, bread_type, urgent = order
    if not isinstance(loaves, int) or isinstance(loaves, bool):
        raise TypeError("loaf count must be an integer")
    if loaves < MIN_LOAVES_PER_ORDER:
        raise ValueError("an order must contain at least %d loaf" % MIN_LOAVES_PER_ORDER)
    if not isinstance(bread_type, str) or not bread_type.strip():
        raise ValueError("bread type must be a non-empty string")
    return loaves, bread_type.strip().lower(), bool(urgent)


def batch_count(loaves):
    """Number of oven loads needed for the given loaf count."""
    return (loaves + OVEN_CAPACITY - 1) // OVEN_CAPACITY


def bake_minutes(loaves, bread_type):
    """Total minutes to finish every batch of one order."""
    minutes = batch_count(loaves) * BATCH_MINUTES
    if bread_type == SOURDOUGH_NAME:
        minutes += SOURDOUGH_REST_MINUTES
    return minutes


def order_revenue(loaves, urgent):
    """Money taken for one order, including any urgent surcharge."""
    revenue = loaves * PRICE_PER_LOAF
    if urgent:
        revenue += URGENT_FEE
    return revenue


def plan(orders):
    """Return [(total minutes, total revenue), ...] for the given orders."""
    schedule = []
    for order in orders:
        loaves, bread_type, urgent = validate_order(order)
        schedule.append((bake_minutes(loaves, bread_type), order_revenue(loaves, urgent)))
    return schedule


def format_report(orders, schedule):
    """Build a human readable bakery plan for the orders and their schedule."""
    lines = ["Bakery plan (oven holds %d loaves per batch)" % OVEN_CAPACITY]
    urgent_orders = 0
    for order, (minutes, revenue) in zip(orders, schedule):
        loaves, bread_type, urgent = validate_order(order)
        if urgent:
            urgent_orders += 1
        lines.append(
            "%4d %-10s %2d batch(es) %4d min  %3d money%s"
            % (loaves, bread_type, batch_count(loaves), minutes, revenue,
               "  URGENT" if urgent else "")
        )
    lines.append("Longest order: %d min" % max((m for m, _r in schedule), default=0))
    lines.append("Surcharges: %d x %d" % (urgent_orders, URGENT_FEE))
    lines.append("Total revenue: %d (loaves priced at %d each)"
                 % (sum(r for _m, r in schedule), PRICE_PER_LOAF))
    return "\n".join(lines)


def main():
    orders = [(30, "white", False), (10, SOURDOUGH_NAME, True), (45, "rye", True)]
    schedule = plan(orders)
