STANDARD_GAME = "standard"
VALID_GAME_TYPES = frozenset({
    STANDARD_GAME,
    PREMIUM_GAME,
})
VIP_TAG = "VIP"
REGULAR_TAG = "regular"
REPORT_TAG_WIDTH = 8


def effective_points(score, game_type):
    """Apply the game-type multiplier to a raw score."""
    if score < 0:
        raise ValueError("score must not be negative: {0!r}".format(score))
    if game_type not in VALID_GAME_TYPES:
        raise ValueError("unknown game type: {0!r}".format(game_type))
    if game_type == PREMIUM_GAME:
        return score * PREMIUM_MULTIPLIER
    return score


def tickets_for(score, game_type, vip):
    """Return the tickets awarded for a single play."""
    points = effective_points(score, game_type)
    tickets = points // POINTS_PER_TICKET
    if vip:
        tickets = int(tickets * (1 + VIP_BONUS_RATE))
    if tickets > JACKPOT_LIMIT:
        return JACKPOT_LIMIT
    if tickets < MINIMUM_PAYOUT:
        return MINIMUM_PAYOUT
    return tickets


def payout(games):
    """Return the list of tickets awarded for each (score, type, vip) play."""
    return [tickets_for(score, game_type, vip) for score, game_type, vip in games]


def describe_play(score, game_type, vip, tickets):
    """Render one line of the payout report."""
    tag = VIP_TAG if vip else REGULAR_TAG
    line = "{0:>6} pts  {1:<9} {2:<{3}} -> {4:>3} tickets".format(
        score, game_type, tag, REPORT_TAG_WIDTH, tickets
    )
    if tickets == JACKPOT_LIMIT:
        line += "  (jackpot cap)"
    elif tickets == MINIMUM_PAYOUT:
        line += "  (minimum payout)"
    return line


def format_report(games, tickets):
    """Render a per-play report plus a total line."""
    lines = [
        describe_play(score, game_type, vip, awarded)
        for (score, game_type, vip), awarded in zip(games, tickets)
    ]
    lines.append("total: {0} tickets".format(sum(tickets)))
    return "\n".join(lines)


