MIN_HARDNESS = 1
MAX_HARDNESS = 10
BASE_DIG_RATE = 10.0
HARD_ROCK_THRESHOLD = 7
HARD_ROCK_SLOWDOWN = 0.40
MAX_DAILY_HOURS = 12
BLAST_BONUS_DEPTH = 5
BLAST_BONUS_MIN_TARGET = 50
COST_PER_HOUR = 100


def validate_site(site):
    """Unpack and sanity-check a single (target, hardness, hours) tuple."""
    target, hardness, hours = site
    if target < 0:
        raise ValueError("depth to clear cannot be negative: %r" % (target,))
    if hardness < MIN_HARDNESS:
        raise ValueError("hardness below scale minimum: %r" % (hardness,))
    if hardness > MAX_HARDNESS:
        raise ValueError("hardness above scale maximum: %r" % (hardness,))
    if hours < 0:
        raise ValueError("allocated hours cannot be negative: %r" % (hours,))
    return target, hardness, hours


def effective_rate(hardness):
    """Meters per hour after the hard rock penalty, if any."""
    if hardness >= HARD_ROCK_THRESHOLD:
        return BASE_DIG_RATE * (1.0 - HARD_ROCK_SLOWDOWN)
    return BASE_DIG_RATE


def blast_bonus(target):
    """Free meters granted at the start of a large clearance job."""
    if target > BLAST_BONUS_MIN_TARGET:
        return BLAST_BONUS_DEPTH
    return 0


def hours_used(hours):
    """Allocated hours trimmed to the daily operating limit."""
    return min(hours, MAX_DAILY_HOURS)


def excavate(sites):
    """Return [(depth_reached, total_cost), ...] for every mining site."""
    results = []
    for site in sites:
        target, hardness, hours = validate_site(site)
        worked = hours_used(hours)
        depth = blast_bonus(target) + effective_rate(hardness) * worked
        results.append((round(depth), worked * COST_PER_HOUR))
    return results


def format_report(sites, results):
    """Build a human readable line per site from the excavation results."""
    lines = []
    for site, (depth, cost) in zip(sites, results):
        target, hardness, hours = site
        notes = []
        if hardness >= HARD_ROCK_THRESHOLD:
            notes.append("hard rock")
        if target > BLAST_BONUS_MIN_TARGET:
            notes.append("blast bonus +%dm" % BLAST_BONUS_DEPTH)
        if hours > MAX_DAILY_HOURS:
            notes.append("capped at %dh" % MAX_DAILY_HOURS)
        suffix = " (%s)" % ", ".join(notes) if notes else ""
        lines.append(
            "target %dm, hardness %d, %dh -> %dm for $%d%s"
            % (target, hardness, hours_used(hours), depth, cost, suffix)
        )
    return "\n".join(lines)


def main():
    sites = [(100, 5, 10), (40, 8, 15)]
    results = excavate(sites)
    print(results)
    print(format_report(sites, results))


if __name__ == "__main__":
    main()

