import math

COVERAGE_RATE_SQM_PER_MIN = 100.0
HIGH_RES_SPEED_FACTOR = 0.5
MAX_BATTERY_MINUTES = 30
HIGH_WIND_THRESHOLD = 15
HIGH_WIND_PENALTY_MINUTES = 5
SAFE_RETURN_MARGIN_MINUTES = 5
MINUTES_PER_HOUR = 60


def validate_region(region):
    area, wind, high_res = region
    if area < 0:
        raise ValueError("area must not be negative: %r" % (area,))
    if wind < 0:
        raise ValueError("wind speed must not be negative: %r" % (wind,))
    return float(area), float(wind), bool(high_res)


def coverage_rate(high_res):
    if high_res:
        return COVERAGE_RATE_SQM_PER_MIN * HIGH_RES_SPEED_FACTOR
    return COVERAGE_RATE_SQM_PER_MIN


def flight_minutes(area, high_res):
    return area / coverage_rate(high_res)


def usable_battery_minutes(wind):
    minutes = MAX_BATTERY_MINUTES - SAFE_RETURN_MARGIN_MINUTES
    if wind > HIGH_WIND_THRESHOLD:
        minutes -= HIGH_WIND_PENALTY_MINUTES
    return minutes


def batteries_for_region(region):
    area, wind, high_res = validate_region(region)
    return math.ceil(flight_minutes(area, high_res) / usable_battery_minutes(wind))


def survey(regions):
    return [batteries_for_region(region) for region in regions]


def format_duration(minutes):
    whole = int(round(minutes))
    if whole < MINUTES_PER_HOUR:
        return "%dm" % whole
    return "%dh%02dm" % divmod(whole, MINUTES_PER_HOUR)


def report(regions):
    counts = survey(regions)
    lines = []
    for index, (region, count) in enumerate(zip(regions, counts), start=1):
        area, wind, high_res = validate_region(region)
        airtime = flight_minutes(area, high_res)
        usable = usable_battery_minutes(wind)
        note = "high-res" if high_res else "standard"
        if wind > HIGH_WIND_THRESHOLD:
            note += ", wind penalty %dm" % HIGH_WIND_PENALTY_MINUTES
        lines.append(
            "Region %d: %.0f sqm, %s, airtime %s, %dm usable per battery -> %d battery(ies)"
            % (index, area, note, format_duration(airtime), usable, count)
        )
    total_air = sum(flight_minutes(*validate_region(r)[::2]) for r in regions)
    lines.append(
        "Total: %d battery(ies), airtime %s, reserve %dm per battery"
        % (sum(counts), format_duration(total_air), SAFE_RETURN_MARGIN_MINUTES)
    )
    return "\n".join(lines)


def main():
    regions = [(2000, 10, False), (2500, 20, True)]
    print(survey(regions))
    print(report(regions))


if __name__ == "__main__":
    main()

