import math

MEALS_PER_PASSENGER_DAY = 3
WATER_RATION_LITERS = 5
BUFFER_PERCENTAGE = 15.0
PASSENGERS_PER_CREW_MEMBER = 4
LUXURY_WATER_BONUS_LITERS = 2
MAX_PASSENGERS_PER_VOYAGE = 9000
MAX_VOYAGE_DAYS = 180
REPORT_DECIMALS = 1


def validate_voyage(passengers, days, luxury):
    if not isinstance(passengers, int) or not isinstance(days, int):
        raise TypeError("passenger count and duration must be integers")
    if not isinstance(luxury, bool):
        raise TypeError("luxury tier must be a boolean")
    if passengers < 1 or passengers > MAX_PASSENGERS_PER_VOYAGE:
        raise ValueError(
            "passenger count must be between 1 and %d" % MAX_PASSENGERS_PER_VOYAGE
        )
    if days < 1 or days > MAX_VOYAGE_DAYS:
        raise ValueError("duration must be between 1 and %d days" % MAX_VOYAGE_DAYS)


def crew_size(passengers):
    return math.ceil(passengers / PASSENGERS_PER_CREW_MEMBER)


def apply_buffer(amount):
    return amount * (1.0 + BUFFER_PERCENTAGE / 100.0)


def meals_needed(people, days):
    return apply_buffer(people * days * MEALS_PER_PASSENGER_DAY)


def water_needed(people, days, luxury):
    daily_ration = WATER_RATION_LITERS
    if luxury:
        daily_ration += LUXURY_WATER_BONUS_LITERS
    return apply_buffer(people * days * daily_ration)


def provision(voyages):
    results = []
    for passengers, days, luxury in voyages:
        validate_voyage(passengers, days, luxury)
        people = passengers + crew_size(passengers)
        results.append((meals_needed(people, days), water_needed(people, days, luxury)))
    return results


def format_report(voyages, supplies):
    lines = []
    for (passengers, days, luxury), (meals, water) in zip(voyages, supplies):
