BASE_FARE = 2.0
EXTRA_ZONE_COST = 1.0
ZONES_INCLUDED_IN_BASE = 1
PEAK_SURCHARGE = 1.5
SENIOR_DISCOUNT_RATE = 0.5
MAX_FARE = 7.0
MIN_ZONES = 1
FARE_DECIMALS = 2
CURRENCY_SYMBOL = "$"
PEAK_LABEL = "peak"
OFFPEAK_LABEL = "off-peak"


def validate_trip(trip):
    """Unpack and sanity-check a single (zones, peak, senior) tuple."""
    zones, peak, senior = trip
    if not isinstance(zones, int) or isinstance(zones, bool):
        raise TypeError("zone count must be an integer: %r" % (zones,))
    if zones < MIN_ZONES:
        raise ValueError("a trip must cross at least %d zone(s)" % MIN_ZONES)
    return zones, bool(peak), bool(senior)


def zone_charge(zones):
    """Base fare plus the per-zone cost for every zone beyond the first."""
    return BASE_FARE + (zones - ZONES_INCLUDED_IN_BASE) * EXTRA_ZONE_COST


def fare_for_trip(zones, peak, senior):
    """Discount first, then surcharge, then apply the absolute cap."""
    fare = zone_charge(zones)
    if senior:
        fare *= 1.0 - SENIOR_DISCOUNT_RATE
    if peak:
        fare += PEAK_SURCHARGE
    return min(fare, MAX_FARE)


def collect(trips):
    fares = []
    for trip in trips:
        zones, peak, senior = validate_trip(trip)
        fares.append(round(fare_for_trip(zones, peak, senior), FARE_DECIMALS))
    return fares


def format_fare(amount):
    return "%s%.*f" % (CURRENCY_SYMBOL, FARE_DECIMALS, amount)


def describe_trip(trip, fare):
    zones, peak, senior = validate_trip(trip)
    window = PEAK_LABEL if peak else OFFPEAK_LABEL
    rider = "senior" if senior else "standard"
    line = "%d zone(s), %s, %s: %s" % (zones, window, rider, format_fare(fare))
    if fare >= MAX_FARE:
        line += " (capped)"
    return line


def report(trips):
    fares = collect(trips)
    lines = [describe_trip(trip, fare) for trip, fare in zip(trips, fares)]
    lines.append("total: %s" % format_fare(sum(fares)))
    return "\n".join(lines)


def main():
