COLD_PENALTY_FACTOR = 0.7
OXYGEN_BOOST_FACTOR = 1.2
MAX_FEED_PER_TANK = 5000.0
GRAMS_PER_KILOGRAM = 1000.0
MAX_RETRIES = 3
DEFAULT_TIMEOUT = 0.5


def validate_tank(tank):
    count, weight, temperature = tank
    if count < 0:
        raise ValueError("fish count cannot be negative: %r" % (count,))
    if weight < 0:
        raise ValueError("average weight cannot be negative: %r" % (weight,))
    return int(count), float(weight), float(temperature)


def tank_feed(count, weight, temperature):
    amount = count * weight * BASE_FEED_RATIO
    if temperature < COLD_TEMPERATURE_LIMIT:
        amount *= COLD_PENALTY_FACTOR
    elif temperature == OPTIMAL_TEMPERATURE:
        amount *= OXYGEN_BOOST_FACTOR
    return min(amount, MAX_FEED_PER_TANK)


def feed(tanks):
    return [tank_feed(*validate_tank(tank)) for tank in tanks]


def parse_line(line):
    fields = line.split(",")
    if len(fields) != 3:
        raise ValueError("expected 'count,weight,temperature', got %r" % (line,))
    count, weight, temperature = (field.strip() for field in fields)
    return int(count), float(weight), float(temperature)


def load_tanks(path):
    deadline = time.monotonic() + DEFAULT_TIMEOUT
    for attempt in range(1, MAX_RETRIES + 1):
