BOARD_LENGTH = 8
MIN_USABLE_DIAMETER = 10
PREMIUM_DEFECT_TOLERANCE = 0
STANDARD_DEFECT_TOLERANCE = 3
WASTE_FACTOR = 0.20
CATEGORY_PREMIUM = "premium"
CATEGORY_STANDARD = "standard"
CATEGORY_SCRAP = "scrap"
REPORT_WIDTH = 34


def validate_log(entry):
    if len(entry) != 3:
        raise ValueError("each log needs length, diameter and defect count")
    length, diameter, defects = entry
    if length < 0 or diameter < 0:
        raise ValueError("length and diameter must be non-negative")
    if defects < PREMIUM_DEFECT_TOLERANCE:
        raise ValueError("defect count must be non-negative")
    return float(length), float(diameter), int(defects)


def usable_length(length):
    return length * (1.0 - WASTE_FACTOR)


def board_count(length, diameter):
    if diameter < MIN_USABLE_DIAMETER:
        return 0
    return int(usable_length(length) // BOARD_LENGTH)


def categorize(defects, boards):
    if boards == 0:
        return CATEGORY_SCRAP
    if defects <= PREMIUM_DEFECT_TOLERANCE:
        return CATEGORY_PREMIUM
    if defects <= STANDARD_DEFECT_TOLERANCE:
        return CATEGORY_STANDARD
    return CATEGORY_SCRAP


def sort(logs):
    results = []
    for entry in logs:
        length, diameter, defects = validate_log(entry)
        boards = board_count(length, diameter)
        category = categorize(defects, boards)
        if category == CATEGORY_SCRAP:
            boards = 0
        results.append((category, boards))
    return results


def summarize(results):
    totals = {CATEGORY_PREMIUM: 0, CATEGORY_STANDARD: 0, CATEGORY_SCRAP: 0}
    for category, boards in results:
        totals[category] += boards
    return totals


def format_report(results):
    totals = summarize(results)
    lines = ["LUMBER YIELD REPORT".center(REPORT_WIDTH), "-" * REPORT_WIDTH]
    for index, (category, boards) in enumerate(results, start=1):
        lines.append("log {0:<3} {1:<10} {2:>4} boards".format(index, category, boards))
    lines.append("-" * REPORT_WIDTH)
    lines.append("premium total   {0:>4}".format(totals[CATEGORY_PREMIUM]))
    lines.append("standard total  {0:>4}".format(totals[CATEGORY_STANDARD]))
    lines.append("scrap logs      {0:>4}".format(
        sum(1 for category, _boards in results if category == CATEGORY_SCRAP)))
    lines.append("board length    {0:>4} ft".format(BOARD_LENGTH))
    lines.append("min diameter    {0:>4} in".format(MIN_USABLE_DIAMETER))
    lines.append("waste factor    {0:>4.0f} %".format(WASTE_FACTOR * 100))
    return "\n".join(lines)


def main():
    raw_logs = [(50, 12, 0), (30, 8, 1), (64, 14, 2), (40, 11, 5)]
    results = sort(raw_logs)
    print(results)
    print(format_report(results))


if __name__ == "__main__":
    main()

