INNER_POINTS = 7
OUTER_POINTS = 3
MISS_POINTS = 0

TIME_LIMIT_SECONDS = 20
TIME_PENALTY_POINTS = 1
MAX_WIND_SPEED_FOR_PENALTY = 15

ARROW_FIELD_COUNT = 3


def ring_points(distance):
    """Return the raw points awarded for a hit at the given distance."""
    if distance <= BULLSEYE_RADIUS:
        return BULLSEYE_POINTS
    if distance <= INNER_RADIUS:
        return INNER_POINTS
    if distance <= OUTER_RADIUS:
        return OUTER_POINTS
    return MISS_POINTS


def time_penalty(wind_speed, seconds):
    """Return the penalty for a slow shot, unless strong wind invalidates it."""
    if seconds > TIME_LIMIT_SECONDS and wind_speed <= MAX_WIND_SPEED_FOR_PENALTY:
        return TIME_PENALTY_POINTS
    return 0


def validate_arrow(arrow):
    """Raise ValueError if the arrow record cannot be scored."""
    if len(arrow) != ARROW_FIELD_COUNT:
        raise ValueError("each arrow needs distance, wind speed and time")
    distance, wind_speed, seconds = arrow
    if distance < 0:
        raise ValueError("distance from center cannot be negative")
    if seconds < 0:
        raise ValueError("time taken cannot be negative")
    if wind_speed < 0:
        raise ValueError("wind speed cannot be negative")


def score(arrows):
    """Return (total score, number of bullseyes) for a list of arrow records."""
    total = 0
    bullseyes = 0
    for arrow in arrows:
        validate_arrow(arrow)
        distance, wind_speed, seconds = arrow
        points = ring_points(distance)
        if points == BULLSEYE_POINTS:
            bullseyes += 1
        total += points - time_penalty(wind_speed, seconds)
    return total, bullseyes


RING_NAMES = {
    BULLSEYE_POINTS: "bullseye",
    INNER_POINTS: "inner ring",
    OUTER_POINTS: "outer ring",
    MISS_POINTS: "miss",
}


