    """Build a human readable breakdown of every arrow plus the summary line."""
    lines = []
    for index, arrow in enumerate(arrows, start=1):
        validate_arrow(arrow)
        distance, wind_speed, seconds = arrow
        points = ring_points(distance)
        net = points - time_penalty(wind_speed, seconds)
        lines.append(
            "Arrow {0}: {1} at distance {2} -> {3} point(s)".format(
                index, RING_NAMES[points], distance, net
            )
        )
    total, bullseyes = score(arrows)
    lines.append("Total: {0}, bullseyes: {1}".format(total, bullseyes))
    return "\n".join(lines)


