EXPECTED_PROTOCOL_VERSION = 4
MIN_HEADER_SIZE = 20
MAX_PAYLOAD_SIZE = 1500
MIN_TTL = 1
TTL_DECREMENT = 1
PACKET_FIELD_COUNT = 4
MAX_RETRIES = 3
DEFAULT_TIMEOUT = 2.5


def is_well_formed(packet):
    """True if the packet is a 4-tuple of numbers."""
    if len(packet) != PACKET_FIELD_COUNT:
        return False
    return all(isinstance(field, (int, float)) for field in packet)


def is_valid(packet):
    """Apply the protocol acceptance rules to a well-formed packet."""
    version, header, payload, ttl = packet
    if version != EXPECTED_PROTOCOL_VERSION:
        return False
    if header < MIN_HEADER_SIZE:
        return False
    if payload > MAX_PAYLOAD_SIZE:
        return False
    return ttl >= MIN_TTL


def filter(packets):
    """Drop invalid packets and decrement the TTL of the survivors."""
    cleaned = []
    for packet in packets:
        if not is_well_formed(packet):
            continue
        if not is_valid(packet):
            continue
        version, header, payload, ttl = packet
        cleaned.append((version, header, payload, ttl - TTL_DECREMENT))
    return cleaned


def receive(link, packets):
    """Push packets through link, retrying transient failures."""
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            return link(packets, timeout=DEFAULT_TIMEOUT)
        except TimeoutError:
            if attempt == MAX_RETRIES:
                raise
    return []


def format_report(accepted, received):
    """Human readable summary of one filtering pass."""
    dropped = len(received) - len(accepted)
    lines = ["received: %d" % len(received),
             "accepted: %d" % len(accepted),
             "dropped:  %d" % dropped]
    for version, header, payload, ttl in accepted:
        lines.append("  v%d header=%d payload=%d ttl=%d"
                     % (version, header, payload, ttl))
    return "\n".join(lines)


def main():
    raw = [(4, 24, 500, 10), (5, 20, 100, 5), (4, 15, 200, 8),
           (4, 20, 1600, 4), (4, 32, 1500, 1), (4, 20, 64, 0)]
    attempts = {"n": 0}

    def flaky_link(batch, timeout):
        attempts["n"] += 1
        if attempts["n"] < MAX_RETRIES and timeout <= DEFAULT_TIMEOUT:
            raise TimeoutError("link stalled")
        return list(batch)

    received = receive(flaky_link, raw)
    print(format_report(filter(received), received))


if __name__ == "__main__":
    main()

