MINOR_THRESHOLD = 4.0
MODERATE_THRESHOLD = 5.5
SEVERE_THRESHOLD = 7.0
CATASTROPHIC_THRESHOLD = 8.0
MIN_VALID_MAGNITUDE = -2.0
MAX_VALID_MAGNITUDE = 10.0
CATEGORY_NAMES = ("micro", "minor", "moderate", "severe", "catastrophic")
REPORT_WIDTH = 34

import sys


def categorize(magnitudes):
    """Count readings per severity band, thresholds belonging to the higher band."""
    micro = minor = moderate = severe = catastrophic = 0
    for magnitude in magnitudes:
        if magnitude >= CATASTROPHIC_THRESHOLD:
            catastrophic += 1
        elif magnitude >= SEVERE_THRESHOLD:
            severe += 1
        elif magnitude >= MODERATE_THRESHOLD:
            moderate += 1
        elif magnitude >= MINOR_THRESHOLD:
            minor += 1
        else:
            micro += 1
    return (micro, minor, moderate, severe, catastrophic)


def parse_readings(text):
    """Turn whitespace/comma separated text into a list of validated magnitudes."""
    readings = []
    for token in text.replace(",", " ").split():
        value = float(token)
        if value < MIN_VALID_MAGNITUDE:
            raise ValueError(f"reading {value} is below the usable scale minimum "
                             f"of {MIN_VALID_MAGNITUDE}")
        if value > MAX_VALID_MAGNITUDE:
            raise ValueError(f"reading {value} exceeds the scale maximum "
                             f"of {MAX_VALID_MAGNITUDE}")
        readings.append(value)
    return readings


def format_report(counts):
    """Render the five counts as a fixed-width table with percentage shares."""
    total = sum(counts)
    lines = [" SEISMIC SUMMARY ".center(REPORT_WIDTH, "=")]
    for name, count in zip(CATEGORY_NAMES, counts):
        share = 100.0 * count / total if total else 0.0
        lines.append(f"{name:<14}{count:>6}{share:>10.1f}%")
    lines.append("-" * REPORT_WIDTH)
    lines.append(f"{'total':<14}{total:>6}")
    return "\n".join(lines)


def main(argv):
    if len(argv) > 1:
        with open(argv[1], "r", encoding="utf-8") as handle:
            text = handle.read()
    else:
        text = sys.stdin.read()
    try:
        readings = parse_readings(text)
    except ValueError as error:
        print(f"invalid input: {error}", file=sys.stderr)
        return 2
    if not readings:
        print("no readings supplied", file=sys.stderr)
        return 1
    counts = categorize(readings)
    print(format_report(counts))
    if counts[-1]:
        print(f"ALERT: {counts[-1]} {CATEGORY_NAMES[-1]} event(s) recorded")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

