import sys

WARP_TENSION_MULTIPLIER = 1.05
WEFT_OVERLAP_ALLOWANCE = 2.0
BREAKAGE_LOSS_FACTOR = 0.05
THREAD_DENSITY = 40
INCHES_PER_YARD = 36.0
DIMENSION_SEPARATOR = "x"


def warp_yarn(width, length):
    """Total warp thread length in inches for one piece."""
    return length * WARP_TENSION_MULTIPLIER * width * THREAD_DENSITY


def weft_yarn(width, length):
    """Total weft thread length in inches for one piece."""
    return (width + WEFT_OVERLAP_ALLOWANCE) * length * THREAD_DENSITY


def piece_yarn(width, length):
    """Yarn in inches for one piece, including breakage loss."""
    if width <= 0 or length <= 0:
        raise ValueError("fabric dimensions must be positive: got %r x %r" % (width, length))
    raw = warp_yarn(width, length) + weft_yarn(width, length)
    return raw * (1.0 + BREAKAGE_LOSS_FACTOR)


def calculate(patterns):
    """Total yarn in inches needed to weave every (width, length) piece."""
    total = 0.0
    for width, length in patterns:
        total += piece_yarn(width, length)
    return total


def parse_pattern(text):
    """Turn a 'WIDTHxLENGTH' string into a (width, length) tuple of floats."""
    parts = text.strip().lower().split(DIMENSION_SEPARATOR)
    if len(parts) != 2:
        raise ValueError("expected WIDTH%sLENGTH, got %r" % (DIMENSION_SEPARATOR, text))
    return float(parts[0]), float(parts[1])


def to_yards(inches):
    """Convert a thread length in inches to yards."""
    return inches / INCHES_PER_YARD


def format_report(patterns):
    """Join one summary line for every piece with a final total line."""
    lines = []
    for width, length in patterns:
        needed = piece_yarn(width, length)
        lines.append("%g%s%g in -> %.1f in (%.2f yd)"
                     % (width, DIMENSION_SEPARATOR, length, needed, to_yards(needed)))
    grand_total = calculate(patterns)
    lines.append("total -> %.1f in (%.2f yd)" % (grand_total, to_yards(grand_total)))
    return "\n".join(lines)


def main(argv):
    if len(argv) < 2:
        print("usage: %s WIDTH%sLENGTH [...]" % (argv[0], DIMENSION_SEPARATOR), file=sys.stderr)
        return 1
    try:
        patterns = [parse_pattern(arg) for arg in argv[1:]]
        print(format_report(patterns))
    except ValueError as error:
        print("error: %s" % error, file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

