BARK_DEDUCTION_RATE = 0.10
TAPER_INCHES_PER_FOOT = 0.2
MIN_TIP_DIAMETER_INCHES = 6.0
MIN_LOG_LENGTH_FEET = 1.0
MIN_BASE_DIAMETER_INCHES = 1.0
DIAMETER_DECIMALS = 2
REPORT_LABEL_WIDTH = 18


def validate_log(length, base_diameter):
    """Reject measurements that cannot describe a real log."""
    if length < MIN_LOG_LENGTH_FEET:
        raise ValueError("log length %r is below %.1f ft" % (length, MIN_LOG_LENGTH_FEET))
    if base_diameter < MIN_BASE_DIAMETER_INCHES:
        raise ValueError(
            "base diameter %r is below %.1f in" % (base_diameter, MIN_BASE_DIAMETER_INCHES)
        )


def tip_diameter(length, base_diameter):
    """Diameter left at the small end after bark and taper losses."""
    bark_loss = base_diameter * BARK_DEDUCTION_RATE
    taper_loss = TAPER_INCHES_PER_FOOT * length
    return base_diameter - bark_loss - taper_loss


def is_usable(length, base_diameter):
    return tip_diameter(length, base_diameter) >= MIN_TIP_DIAMETER_INCHES


def estimate(logs):
    """Total usable length in feet over all logs of a harvest."""
    total_length = 0.0
    for length, base_diameter in logs:
        validate_log(length, base_diameter)
        if is_usable(length, base_diameter):
            total_length += length
    return total_length


def format_log_line(index, length, base_diameter):
    tip = tip_diameter(length, base_diameter)
    label = "log %d (%g ft)" % (index, length)
    if tip < MIN_TIP_DIAMETER_INCHES:
        verdict = "rejected, tip under %.1f in" % MIN_TIP_DIAMETER_INCHES
    else:
        verdict = "accepted"
    return "%s tip %.*f in - %s" % (
        label.ljust(REPORT_LABEL_WIDTH),
        DIAMETER_DECIMALS,
        tip,
        verdict,
    )


def report(logs):
    """Per-log verdicts followed by the harvest total."""
    lines = []
    for index, (length, base_diameter) in enumerate(logs, start=1):
        validate_log(length, base_diameter)
        lines.append(format_log_line(index, length, base_diameter))
    lines.append("usable length: %g ft" % estimate(logs))
    return lines


def main():
    harvest = [(20, 14), (10, 8), (16, 18), (32, 24), (12, 9.5)]
    print("taper allowance: %.1f in per ft" % TAPER_INCHES_PER_FOOT)
    print("bark allowance: %.0f%% of base diameter" % (BARK_DEDUCTION_RATE * 100))
    for line in report(harvest):
        print(line)


if __name__ == "__main__":
    main()

