MIN_BOOST = 2.0
MAX_RETRIES = 3
DEFAULT_TIMEOUT = 5.0

import select
import sys


def parse_scores(raw):
    """Parse a comma/space separated string of scores into a list of floats."""
    scores = []
    for token in raw.replace(",", " ").split():
        try:
            scores.append(float(token))
        except ValueError:
            raise ValueError("not a number: {0!r}".format(token))
    return scores


def validate(scores):
    if not scores:
        raise ValueError("no scores provided")
    for score in scores:
        if score < 0 or score > MAX_SCORE:
            raise ValueError("score out of range: {0}".format(score))


def compute_boost(scores):
    average = sum(scores) / len(scores)
    difference = TARGET_AVERAGE - average
    if difference < MIN_BOOST:
        return MIN_BOOST
    return difference


def curve(scores):
    validate(scores)
    boost = compute_boost(scores)
    return [round(min(score + boost, MAX_SCORE)) for score in scores]


def curve_until_target(scores):
    """Re-apply the curve until the class average reaches the target.

    Scores that sit at the ceiling cannot rise any further, so the average
    may never reach the target and the number of passes is bounded.
    """
    current = list(scores)
    for _ in range(MAX_RETRIES):
        current = curve(current)
        if sum(current) / len(current) >= TARGET_AVERAGE:
            break
    return current


def read_scores(stream=sys.stdin, timeout=DEFAULT_TIMEOUT):
    """Read one line of scores, giving up if nothing arrives in time."""
    if not select.select([stream], [], [], timeout)[0]:
        raise TimeoutError("no scores received within {0}s".format(timeout))
    return parse_scores(stream.readline())


def report(scores):
