    for label, values in (("original", scores), ("curved", curve(scores))):
        average = sum(values) / len(values)
        lines.append("{0:<9} avg={1:6.2f} {2}".format(label, average, values))
    return "\n".join(lines)


def main():
    if len(sys.argv) > 1:
        scores = parse_scores(" ".join(sys.argv[1:]))
    else:
        scores = read_scores()
    print(report(scores))
    print("target reached:", curve_until_target(scores))


