def validate_carts(carts):
    """Return the cart list as plain integers, rejecting malformed input."""
    checked = []
    for position, items in enumerate(carts):
        if isinstance(items, bool) or not isinstance(items, int):
            raise TypeError("cart %d is not an integer: %r" % (position, items))
        if items < 0:
            raise ValueError("cart %d has a negative item count: %d" % (position, items))
        checked.append(items)
    return checked


def cart_time(items):
    """Seconds to scan a cart and take payment, floored at the till minimum."""
    service = items * SECONDS_PER_ITEM + PAYMENT_OVERHEAD_SECONDS
    return max(service, MINIMUM_SERVICE_SECONDS)


def simulate(carts):
    """Total seconds spent in the express lane and in the regular lane."""
