TARGET_PH = 6.5
LIME_POUNDS_PER_UNIT = 200.0
SULFUR_POUNDS_PER_UNIT = 50.0
MIN_VALID_PH = 0.0
MAX_VALID_PH = 14.0
ROUNDING_DIGITS = 1
LIME_LABEL = "lime"
SULFUR_LABEL = "sulfur"
NO_ACTION_LABEL = "no amendment"
REPORT_WIDTH = 38


def validate_reading(reading):
    """Return the reading as a float, rejecting values outside the pH scale."""
    if isinstance(reading, bool) or not isinstance(reading, (int, float)):
        raise TypeError("pH readings must be numeric, got %r" % (reading,))
    value = float(reading)
    if value < MIN_VALID_PH:
        raise ValueError("pH %g is below the scale minimum %g" % (value, MIN_VALID_PH))
    if value > MAX_VALID_PH:
        raise ValueError("pH %g is above the scale maximum %g" % (value, MAX_VALID_PH))
    return value


def compute_adjustment(reading):
    """Pounds of amendment for one plot: positive for lime, negative for sulfur."""
    value = validate_reading(reading)
    if value < TARGET_PH:
        pounds = (TARGET_PH - value) * LIME_POUNDS_PER_UNIT
    elif value > TARGET_PH:
        deficitless_excess = value - TARGET_PH
        pounds = -deficitless_excess * SULFUR_POUNDS_PER_UNIT
    else:
        pounds = 0.0
    return round(pounds, ROUNDING_DIGITS)


def amend(readings):
    """Prescribe amendment amounts for a list of soil pH readings."""
    return [compute_adjustment(reading) for reading in readings]


def describe_adjustment(pounds):
    """Human readable description of a single prescription."""
    if pounds > 0:
        return "%.1f lb %s" % (pounds, LIME_LABEL)
    if pounds < 0:
        return "%.1f lb %s" % (abs(pounds), SULFUR_LABEL)
    return NO_ACTION_LABEL


def format_report(readings, adjustments):
    """Build a per-plot amendment report plus a net total line."""
    lines = ["SOIL AMENDMENT PLAN".center(REPORT_WIDTH), "-" * REPORT_WIDTH]
    for index, (reading, pounds) in enumerate(zip(readings, adjustments), start=1):
        offset = round(float(reading) - TARGET_PH, ROUNDING_DIGITS)
        label = "Plot %d: pH %.2f (%+.1f)" % (index, reading, offset)
        lines.append("%s %s" % (label.ljust(REPORT_WIDTH - 20), describe_adjustment(pounds)))
    lines.append("-" * REPORT_WIDTH)
    net = round(sum(adjustments), ROUNDING_DIGITS)
    lines.append("Net prescription: %s" % describe_adjustment(net))
    return "\n".join(lines)


def main():
    readings = [6.0, 7.5, 6.5, 5.25, 8.0]
    adjustments = amend(readings)
    print(format_report(readings, adjustments))
    print("Raw adjustments: %s" % adjustments)
    print("Target level: pH %.1f" % TARGET_PH)


if __name__ == "__main__":
    main()

