VEHICLE_TYPE = "vehicle"
WALK_ON_TYPE = "walk-on"
VEHICLE_DECK_CAPACITY = 40
PASSENGER_DECK_CAPACITY = 200
MAX_TOTAL_WEIGHT = 75000
AVERAGE_PASSENGER_WEIGHT = 150


def validate_item(item):
    """Return (kind, amount) for a queue entry, raising ValueError if malformed."""
    if len(item) != 2:
        raise ValueError("each queue entry needs a type and an amount: %r" % (item,))
    kind, amount = item
    if kind not in (VEHICLE_TYPE, WALK_ON_TYPE):
        raise ValueError("unknown passenger type: %r" % (kind,))
    if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
        raise ValueError("amount must be a positive integer: %r" % (amount,))
    return kind, amount


def load(queue):
    """Board the queue in order and return (vehicles, walk_on_individuals)."""
    vehicles = 0
    walk_ons = 0
    weight = 0
    for item in queue:
        kind, amount = validate_item(item)
        if kind == VEHICLE_TYPE:
            if vehicles + 1 > VEHICLE_DECK_CAPACITY:
                break
            if weight + amount > MAX_TOTAL_WEIGHT:
                break
            vehicles += 1
            weight += amount
        else:
            group_weight = amount * AVERAGE_PASSENGER_WEIGHT
            if walk_ons + amount > PASSENGER_DECK_CAPACITY:
                break
            if weight + group_weight > MAX_TOTAL_WEIGHT:
                break
            walk_ons += amount
            weight += group_weight
    return vehicles, walk_ons


def manifest_weight(vehicles_weight, walk_ons):
    """Total boarded weight from vehicle weights plus estimated passenger weight."""
    return sum(vehicles_weight) + walk_ons * AVERAGE_PASSENGER_WEIGHT


def describe(queue):
    """Human readable summary of how a queue fares at the ramp."""
    vehicles, walk_ons = load(queue)
    boarded_vehicle_weights = []
    for item in queue:
        kind, amount = validate_item(item)
        if kind == VEHICLE_TYPE and len(boarded_vehicle_weights) < vehicles:
            boarded_vehicle_weights.append(amount)
    weight = manifest_weight(boarded_vehicle_weights, walk_ons)
    lines = [
        "vehicles: %d of %d" % (vehicles, VEHICLE_DECK_CAPACITY),
        "walk-ons: %d of %d" % (walk_ons, PASSENGER_DECK_CAPACITY),
        "weight:   %d of %d lb" % (weight, MAX_TOTAL_WEIGHT),
    ]
    if len(queue) > vehicles + sum(1 for k, _a in queue if k == WALK_ON_TYPE):
        lines.append("some traffic was left behind at the dock")
    return "\n".join(lines)


def main():
    queue = [(VEHICLE_TYPE, 4000), (WALK_ON_TYPE, 5)]
    print(load(queue))
    print(describe(queue))
    heavy = [(VEHICLE_TYPE, 30000)] * 3 + [(WALK_ON_TYPE, 40)]
    print(load(heavy))
    print(describe(heavy))


if __name__ == "__main__":
    main()

