text_nat:
MAX_GROSS_WEIGHT = 10000
FORWARD_CG_LIMIT = 200
AFT_CG_LIMIT = 350
MAX_RETRIES = 5
REPORT_WIDTH = 46


def _validate(manifest):
    items = []
    for entry in manifest:
        weight, position = entry
        if weight < 0:
            raise ValueError("cargo weight cannot be negative")
        items.append((float(weight), float(position)))
    return items


def total_weight(manifest):
    return sum(weight for weight, _position in _validate(manifest))


def total_moment(manifest):
    return sum(weight * position for weight, position in _validate(manifest))


def center_of_gravity(manifest):
    weight = total_weight(manifest)
    if weight <= 0:
        return None
    return total_moment(manifest) / weight


def balance(manifest):
    weight = total_weight(manifest)
    if weight <= 0 or weight > MAX_GROSS_WEIGHT:
        return False
    cg = center_of_gravity(manifest)
    if cg < FORWARD_CG_LIMIT:
        return False
    return cg <= AFT_CG_LIMIT


def _target_cg():
    span = AFT_CG_LIMIT - FORWARD_CG_LIMIT
    return FORWARD_CG_LIMIT + span / 2


def _worst_item(items):
    target = _target_cg()
    return max(items, key=lambda item: item[0] * abs(item[1] - target))


def suggest_offload(manifest):
    items = _validate(manifest)
    for removed in range(MAX_RETRIES + 1):
        if balance(items):
            return items, removed
        if not items:
            break
        items.remove(_worst_item(items))
    return None, removed


def format_report(manifest):
    lines = [" FLIGHT LOAD REPORT ".center(REPORT_WIDTH, "=")]
    lines.append(f"Total weight     : {total_weight(manifest):8.0f} lb")
    lines.append(f"Maximum allowed  : {MAX_GROSS_WEIGHT:8.0f} lb")
    lines.append(f"Total moment     : {total_moment(manifest):8.0f} lb-in")
    cg = center_of_gravity(manifest)
    if cg is None:
        lines.append("Center of gravity: empty aircraft")
    else:
        lines.append(f"Center of gravity: {cg:8.1f} in")
        lines.append(f"Forward limit    : {FORWARD_CG_LIMIT:8.1f} in")
        lines.append(f"Aft limit        : {AFT_CG_LIMIT:8.1f} in")
    verdict = " BALANCED " if balance(manifest) else " OUT OF LIMITS "
    lines.append(verdict.center(REPORT_WIDTH, "-"))
    return "\n".join(lines)


def main():
    fleet = [
        [(5000, 250), (2000, 300)],
        [(6000, 180), (5000, 190)],
        [(1500, 120), (900, 150)],
    ]
    for manifest in fleet:
        print(format_report(manifest))
        if not balance(manifest):
            trimmed, removed = suggest_offload(manifest)
            if trimmed is None:
                print(f"No safe load found after {MAX_RETRIES} offloads\n")
            else:
                print(f"Offload {removed} item(s), keep {trimmed}\n")
        else:
            print()


if __name__ == "__main__":
    main()

