    items = _validate(manifest)
    for removed in range(maxRetries + 1):
        if balance(items):
            return items, removed
        if not items:
            break
        items.remove(_worst_item(items))
    return None, removed


def format_report(manifest):
    lines = [" FLIGHT LOAD REPORT ".center(reportWidth, "=")]
    lines.append(f"Total weight     : {total_weight(manifest):8.0f} lb")
    lines.append(f"Maximum allowed  : {maxGrossWeight:8.0f} lb")
    lines.append(f"Total moment     : {total_moment(manifest):8.0f} lb-in")
    cg = center_of_gravity(manifest)
    if cg is None:
        lines.append("Center of gravity: empty aircraft")
    else:
        lines.append(f"Center of gravity: {cg:8.1f} in")
        lines.append(f"Forward limit    : {forwardCgLimit:8.1f} in")
        lines.append(f"Aft limit        : {aftCgLimit:8.1f} in")
    verdict = " BALANCED " if balance(manifest) else " OUT OF LIMITS "
    lines.append(verdict.center(reportWidth, "-"))
    return "\n".join(lines)


def main():
    fleet = [
        [(5000, 250), (2000, 300)],
        [(6000, 180), (5000, 190)],
        [(1500, 120), (900, 150)],
    ]
    for manifest in fleet:
        print(format_report(manifest))
        if not balance(manifest):
            trimmed, removed = suggest_offload(manifest)
            if trimmed is None:
                print(f"No safe load found after {maxRetries} offloads\n")
            else:
                print(f"Offload {removed} item(s), keep {trimmed}\n")
        else:
            print()


if __name__ == "__main__":
    main()

