    LEVEL_NORMAL: "No action required; river within normal range.",
    LEVEL_MINOR: "Minor flooding: advise residents in low-lying areas.",
    LEVEL_MODERATE: "Moderate flooding: prepare evacuation routes.",
    LEVEL_MAJOR: "MAJOR FLOODING: evacuate the flood plain immediately.",
}


def classify(reading):
    """Return the danger level for a single water height reading."""
    if reading >= MAJOR_THRESHOLD_FEET:
        return LEVEL_MAJOR
    if reading >= MODERATE_THRESHOLD_FEET:
        return LEVEL_MODERATE
    if reading >= MINOR_THRESHOLD_FEET:
        return LEVEL_MINOR
    return LEVEL_NORMAL


def monitor(levels):
    """Return the peak flood condition reached across hourly readings."""
    peak = LEVEL_NORMAL
    for reading in levels:
        height = float(reading)
        level = classify(height)
        if SEVERITY_RANK[level] > SEVERITY_RANK[peak]:
            peak = level
            if peak == LEVEL_MAJOR:
