MAX_RISER_HEIGHT = 7.75
MIN_TREAD_DEPTH = 10.0
MAX_RISER_VARIANCE = 0.375
MEASUREMENT_TOLERANCE = 1e-9
STATUS_COMPLIANT = "COMPLIANT"
STATUS_VIOLATION = "VIOLATION"


def _step_problems(number, riser, tread):
    """Return the individual-limit violations for a single step."""
    problems = []
    if riser > MAX_RISER_HEIGHT + MEASUREMENT_TOLERANCE:
        problems.append(
            "step %d: riser %.3f\" exceeds the %.3f\" maximum"
            % (number, riser, MAX_RISER_HEIGHT)
        )
    if tread < MIN_TREAD_DEPTH - MEASUREMENT_TOLERANCE:
        problems.append(
            "step %d: tread %.3f\" is under the %.3f\" minimum"
            % (number, tread, MIN_TREAD_DEPTH)
        )
    return problems


def _variance_problems(risers):
    """Return the staircase-wide riser variance violation, if any."""
    if not risers:
        return []
    spread = max(risers) - min(risers)
    if spread > MAX_RISER_VARIANCE + MEASUREMENT_TOLERANCE:
        return [
            "riser variance %.3f\" exceeds the %.3f\" maximum"
            % (spread, MAX_RISER_VARIANCE)
        ]
    return []


def audit(stairs):
    """Collect every building-code violation found in the measurements."""
    problems = []
    risers = []
    for number, step in enumerate(stairs, start=1):
        riser, tread = step
        riser, tread = float(riser), float(tread)
        risers.append(riser)
        problems.extend(_step_problems(number, riser, tread))
    problems.extend(_variance_problems(risers))
    return problems


def inspect(stairs):
    """True when every step and the overall riser variance are compliant."""
    return not audit(stairs)


def format_report(stairs):
    """Render a one-staircase inspection report as text."""
    problems = audit(stairs)
    status = STATUS_VIOLATION if problems else STATUS_COMPLIANT
    lines = ["%d step(s): %s" % (len(stairs), status)]
    for problem in problems:
        lines.append("  - " + problem)
    return "\n".join(lines)


def main():
    staircases = [
        [(7.5, 11), (7.6, 10.5), (7.4, 11)],
        [(7.5, 11), (7.9, 10.5), (7.4, 11)],
        [(7.0, 9.5), (7.0, 11.0)],
        [(7.0, 11), (7.2, 11), (7.5, 11), (7.45, 11)],
    ]
    for stairs in staircases:
        print(format_report(stairs))
        print("inspect() ->", inspect(stairs))


if __name__ == "__main__":
    main()

