def _unpack(tank, index):
    if len(tank) != TANK_FIELD_COUNT:
        raise ValueError(
            "tank %d must have %d fields: (volume, fish, plants)"
            % (index, TANK_FIELD_COUNT)
        )
    volume, fish, plants = tank
    if volume <= 0:
        raise ValueError("tank %d has a non-positive volume" % index)
    if fish < 0 or plants < 0:
        raise ValueError("tank %d has a negative population count" % index)
    return float(volume), int(fish), int(plants)


def stocking_capacity(volume):
    return volume * MAX_STOCKING_DENSITY


def is_overstocked(volume, fish):
    return fish > stocking_capacity(volume)


def nitrate_level(volume, fish, plants):
    produced = fish * NITRATE_PER_FISH
    absorbed = plants * NITRATE_ABSORBED_PER_PLANT
    return BASE_AMBIENT_NITRATE + (produced - absorbed) / volume


