text_nat:
FIRST_CRACK_F = 385.0
SECOND_CRACK_F = 435.0
BURN_F = 450.0
MAX_READINGS = 20
LIGHT = "light"
MEDIUM = "medium"
DARK = "dark"
RUINED = "ruined"
REPORT_NAME_WIDTH = 14
ADVICE = {
    LIGHT: "extend the roast, beans are under-developed",
    MEDIUM: "balanced profile, rest 24h before brewing",
    DARK: "drop earlier next time, oils are surfacing",
    RUINED: "discard the batch and recalibrate the drum",
}


def roast(temperatures):
    """Classify bean development from a list of Fahrenheit readings."""
    if not temperatures:
        raise ValueError("no temperature readings supplied")
    if len(temperatures) > MAX_READINGS:
        return RUINED
    for reading in temperatures:
        if reading >= BURN_F:
            return RUINED
    peak = max(temperatures)
    if peak < FIRST_CRACK_F:
        return LIGHT
    if peak < SECOND_CRACK_F:
        return MEDIUM
    return DARK


def parse_profile(text):
    """Turn a comma separated profile into a list of floats."""
    readings = []
    for field in text.split(","):
        field = field.strip()
        if not field:
            continue
        readings.append(float(field))
    if not readings:
        raise ValueError("profile %r contains no readings" % text)
    return readings


def crack_index(temperatures, threshold):
    """Position of the first reading at or above threshold, else None."""
    for index, reading in enumerate(temperatures):
        if reading >= threshold:
            return index
    return None


def format_report(name, temperatures):
    grade = roast(temperatures)
    peak = max(temperatures)
    margin = BURN_F - peak
    first = crack_index(temperatures, FIRST_CRACK_F)
    second = crack_index(temperatures, SECOND_CRACK_F)
    marks = "1st@%s 2nd@%s" % (
        "-" if first is None else first,
        "-" if second is None else second,
    )
    return "%s peak=%6.1fF margin=%6.1fF %-14s %-6s %s" % (
        name.ljust(REPORT_NAME_WIDTH),
        peak,
        margin,
        marks,
        grade,
        ADVICE[grade],
    )


def main():
    sessions = {
        "morning": "300, 350, 390, 410",
        "city": "280, 320, 360, 380",
        "french": "300, 370, 420, 440",
        "scorched": "300, 400, 452",
        "overlong": ",".join(["300"] * (MAX_READINGS + 1)),
    }
    for name, text in sessions.items():
        print(format_report(name, parse_profile(text)))


if __name__ == "__main__":
    main()

