        readings.append(float(field))
    if not readings:
        raise ValueError("profile %r contains no readings" % text)
    return readings


def crack_index(temperatures, threshold):
    """Position of the first reading at or above threshold, else None."""
    for index, reading in enumerate(temperatures):
        if reading >= threshold:
            return index
    return None


