SIGNATURE_OVERHEAD_SIZE = 108
MAX_BLOCK_SIZE = 1_000_000
PREMIUM_PRIORITY_MULTIPLIER = 3
HIGH_PRIORITY = "high"
REJECTION_MESSAGE = "rejected: exceeds maximum block size"


def parse_transaction(entry):
    """Normalise a transaction given as a mapping or a (size, priority) pair."""
    if isinstance(entry, dict):
        size = entry["size"]
        priority = entry.get("priority", "normal")
    else:
        size, priority = entry
    if not isinstance(size, int) or isinstance(size, bool):
        raise TypeError("transaction size must be an integer")
    if size < 0:
        raise ValueError("transaction size must be non-negative")
    return size, str(priority).strip().lower()


def total_size(size):
    """Size actually written to the block, signature included."""
    return size + SIGNATURE_OVERHEAD_SIZE


def is_accepted(size):
    return total_size(size) <= MAX_BLOCK_SIZE


def fee_for(size, priority):
    """Fee in satoshi for an accepted transaction."""
    cost = BASE_FEE + total_size(size) * COST_PER_BYTE
    if priority == HIGH_PRIORITY:
