import math

SEA_LEVEL_CONSUMPTION_RATE_LPH = 30.0
ALTITUDE_MULTIPLIER_FACTOR = 2.0
CRITICAL_DANGER_ALTITUDE_METERS = 7000
EMERGENCY_RESERVE_LITERS = 600.0
STANDARD_CYLINDER_CAPACITY_LITERS = 360.0


def parse_climb(climb):
    """Unpack and validate a single (altitude, hours, climbers) record."""
    altitude, hours, climbers = climb
    altitude = float(altitude)
    hours = float(hours)
    climbers = int(climbers)
    if altitude < 0:
        raise ValueError("altitude must not be negative")
    if hours < 0:
        raise ValueError("hours spent at altitude must not be negative")
    if climbers < 1:
        raise ValueError("a climb needs at least one climber")
    return altitude, hours, climbers


def oxygen_liters(climb):
    """Litres of bottled oxygen required for one climb."""
    altitude, hours, climbers = parse_climb(climb)
    if altitude < CRITICAL_DANGER_ALTITUDE_METERS:
        return 0.0
    rate = SEA_LEVEL_CONSUMPTION_RATE_LPH * ALTITUDE_MULTIPLIER_FACTOR
    return rate * hours * climbers + EMERGENCY_RESERVE_LITERS


def cylinders_for(liters):
    """Whole standard cylinders needed to carry the given litres."""
    return math.ceil(liters / STANDARD_CYLINDER_CAPACITY_LITERS)


def calculate(climbs):
    """Standard cylinders required for the whole expedition plan."""
    total = sum(oxygen_liters(climb) for climb in climbs)
    return cylinders_for(total)


def format_report(climbs):
    """Human readable breakdown of the expedition's oxygen logistics."""
    lines = []
    for climb in climbs:
        altitude, hours, climbers = parse_climb(climb)
        liters = oxygen_liters(climb)
        if altitude < CRITICAL_DANGER_ALTITUDE_METERS:
            note = "below the %d m danger line, no bottled oxygen" % (
                CRITICAL_DANGER_ALTITUDE_METERS,
            )
        else:
            note = "%.0f L (incl. %.0f L reserve) -> %d cylinder(s)" % (
                liters,
                EMERGENCY_RESERVE_LITERS,
                cylinders_for(liters),
            )
        lines.append(
            "%5.0f m | %4.1f h | %d climber(s) | %s" % (altitude, hours, climbers, note)
        )
    lines.append(
        "Expedition total: %d cylinder(s) of %.0f L"
        % (calculate(climbs), STANDARD_CYLINDER_CAPACITY_LITERS)
    )
    return "\n".join(lines)


def main():
    plan = [
        (8000, 10, 2),
        (5300, 48, 4),
        (7300, 6, 3),
    ]
    print("Consumption at altitude: %.0f L/h per climber" % (
        SEA_LEVEL_CONSUMPTION_RATE_LPH * ALTITUDE_MULTIPLIER_FACTOR,
    ))
    print(format_report(plan))
    print("Summit push alone:", calculate([(8000, 10, 2)]), "cylinder(s)")


if __name__ == "__main__":
    main()

