import json
import sys
import time
import urllib.error
import urllib.request

MAX_PARTICLE_COUNT = 250
MIN_CHLORINE_LEVEL = 0.2
BACKWASH_TRIGGER_VOLUME = 1500
MIN_FLOW_RATE = 5.0
FILTER_LIFESPAN_GALLONS = 20000
REQUIRED_FIELDS = ("particles", "chlorine", "flow", "gallons")
MAX_RETRIES = 3
DEFAULT_TIMEOUT = 2.5
RETRY_BACKOFF_SECONDS = 0.5


def validate_reading(index, reading):
    for field in REQUIRED_FIELDS:
        if field not in reading:
            raise ValueError("reading %d is missing field %r" % (index, field))
        if not isinstance(reading[field], (int, float)):
            raise ValueError("reading %d has non-numeric %r" % (index, field))


def analyze(readings):
    alerts = []
    for index, reading in enumerate(readings):
        validate_reading(index, reading)
        if reading["particles"] > MAX_PARTICLE_COUNT:
            alerts.append(
                "reading %d: UNSAFE - %g particles above limit of %d"
                % (index, reading["particles"], MAX_PARTICLE_COUNT)
            )
        if reading["chlorine"] < MIN_CHLORINE_LEVEL:
            alerts.append(
                "reading %d: UNSAFE - chlorine %g below required %g ppm"
                % (index, reading["chlorine"], MIN_CHLORINE_LEVEL)
            )
        if reading["flow"] < MIN_FLOW_RATE:
            alerts.append(
                "reading %d: MAINTENANCE - flow %g below %g gpm, backwash %d gallons"
                % (index, reading["flow"], MIN_FLOW_RATE, BACKWASH_TRIGGER_VOLUME)
            )
        if reading["gallons"] > FILTER_LIFESPAN_GALLONS:
            alerts.append(
                "reading %d: REPLACE FILTER NOW - %g of %d gallons used"
                % (index, reading["gallons"], FILTER_LIFESPAN_GALLONS)
            )
    return alerts


def fetch_readings(url, timeout=DEFAULT_TIMEOUT):
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            with urllib.request.urlopen(url, timeout=timeout) as response:
                return json.loads(response.read().decode("utf-8"))
        except (urllib.error.URLError, TimeoutError) as error:
            if attempt == MAX_RETRIES:
                raise RuntimeError(
                    "sensor %s unreachable after %d attempts: %s"
                    % (url, MAX_RETRIES, error)
                )
            time.sleep(RETRY_BACKOFF_SECONDS * attempt)


def main(argv):
    if len(argv) != 2:
        print("usage: %s <sensor-url>" % argv[0], file=sys.stderr)
        return 2
    readings = fetch_readings(argv[1])
    alerts = analyze(readings)
    if not alerts:
        print("All %d readings within standards." % len(readings))
        return 0
    for alert in alerts:
        print(alert)
    return 1


if __name__ == "__main__":
    sys.exit(main(sys.argv))

