OPTIMAL_CUSHION_PRESSURE = 20.0
MAX_LEAKAGE_RATE = 2.0
OBSTACLE_CLEARANCE_PRESSURE = 15.0
EMERGENCY_BLOWER_SPEED = 4200
PRESSURE_LOSS_THRESHOLD = 10.0
ROUGH_TERRAIN_SCORE = 6.0
SPEED_GAIN_PER_PRESSURE_UNIT = 100.0
OBSTACLE_CLEARANCE_BOOST = 200.0
MIN_FAN_SPEED = 0
MAX_FAN_SPEED = 5000

REQUIRED_FIELDS = ("fan_speed", "pressure", "roughness")


def validate_reading(reading):
    """Return the three numeric components of a sensor reading."""
    missing = [name for name in REQUIRED_FIELDS if name not in reading]
    if missing:
        raise KeyError("reading is missing fields: " + ", ".join(missing))
    speed = float(reading["fan_speed"])
    pressure = float(reading["pressure"])
    roughness = float(reading["roughness"])
    if speed < MIN_FAN_SPEED:
        raise ValueError("fan speed below %d rpm is not measurable" % MIN_FAN_SPEED)
    if speed > MAX_FAN_SPEED:
        raise ValueError("fan speed above %d rpm exceeds the fan rating" % MAX_FAN_SPEED)
    if pressure < 0:
        raise ValueError("skirt pressure cannot be negative")
    return speed, pressure, roughness


def pressure_deficit(pressure):
    """How far the skirt pressure sits under the optimal cushion pressure."""
    return OPTIMAL_CUSHION_PRESSURE - pressure


def recommended_increase(deficit):
    """Extra fan rpm needed to make up a leaking cushion."""
    if deficit <= MAX_LEAKAGE_RATE:
        return 0.0
    return deficit * SPEED_GAIN_PER_PRESSURE_UNIT


def regulate(readings):
    """Return the fan speed the lift fans should be driven at."""
    speed, pressure, roughness = validate_reading(readings)
    if pressure < PRESSURE_LOSS_THRESHOLD:
        return EMERGENCY_BLOWER_SPEED
    adjusted = speed + recommended_increase(pressure_deficit(pressure))
    if roughness >= ROUGH_TERRAIN_SCORE and pressure < OBSTACLE_CLEARANCE_PRESSURE:
        adjusted += OBSTACLE_CLEARANCE_BOOST
    return int(round(min(adjusted, MAX_FAN_SPEED)))


def describe(reading, commanded):
    """One-line summary of what the regulator decided for a reading."""
    if commanded == EMERGENCY_BLOWER_SPEED:
        status = "emergency blower"
    elif commanded >= MAX_FAN_SPEED:
        status = "boost (fan saturated)"
    elif commanded > float(reading["fan_speed"]):
        status = "boost"
    else:
        status = "steady"
    return "p=%5.1f rough=%3.1f -> %5d rpm  [%s]" % (
        float(reading["pressure"]),
        float(reading["roughness"]),
        commanded,
        status,
    )


def main():
    log = [
        {"fan_speed": 2500, "pressure": 12, "roughness": 7},
        {"fan_speed": 2500, "pressure": 19, "roughness": 2},
        {"fan_speed": 3000, "pressure": 8, "roughness": 4},
        {"fan_speed": 4800, "pressure": 11, "roughness": 9},
    ]
    for reading in log:
        print(describe(reading, regulate(reading)))


if __name__ == "__main__":
    main()

