MINIMUM_SAP_SUGAR_PERCENT = 1.0
TARGET_SYRUP_DENSITY_PERCENT = 66.0
BOILING_POINT_ELEVATION_PER_SUGAR_DEGREE = 0.106
WATER_BOILING_POINT_F = 212.0
FILTERING_TEMPERATURE_F = 217.0
EVAPORATION_RATE_GALLONS_PER_HOUR = 11.4
REPORT_DECIMALS = 1


def parse_batch(batch):
    """Accept a batch as a mapping or a (volume, sugar_percent) pair."""
    if isinstance(batch, dict):
        volume = float(batch["volume"])
        sugar = float(batch["sugar"])
    else:
        volume, sugar = (float(value) for value in batch)
    if volume <= 0.0:
        raise ValueError(f"sap volume must be positive, got {volume}")
    if not 0.0 <= sugar <= TARGET_SYRUP_DENSITY_PERCENT:
        raise ValueError(f"sap sugar percentage out of range: {sugar}")
    return volume, sugar


def finished_volume(volume, sugar):
    """Gallons of syrup left once the sap reaches the target density."""
    return volume * sugar / TARGET_SYRUP_DENSITY_PERCENT


def water_to_remove(volume, sugar):
    return volume - finished_volume(volume, sugar)


def boil_time(volume, sugar):
    return water_to_remove(volume, sugar) / EVAPORATION_RATE_GALLONS_PER_HOUR


def final_boiling_point(density=TARGET_SYRUP_DENSITY_PERCENT):
    temperature = WATER_BOILING_POINT_F + density * BOILING_POINT_ELEVATION_PER_SUGAR_DEGREE
    if temperature <= FILTERING_TEMPERATURE_F:
        raise ValueError(
            f"boiling point {temperature:.2f}F never reaches the filtering "
            f"threshold {FILTERING_TEMPERATURE_F}F"
