TARGET_HUMIDITY_PCT = 85.0
MAX_AMMONIA_PPM = 25.0
MAX_TEMPERATURE_C = 14.0
MIN_TEMPERATURE_C = 10.0
FAN_RUNTIME_MINUTES = 20
REQUIRED_FIELDS = ("name", "humidity", "ammonia", "temperature")
SENSOR_FEED = """north-gallery,78.4,12.0,12.5
deep-cellar,88.0,31.5,9.2
south-niche,91.0,18.0,16.4
entry-vault,85.0,25.0,11.8"""


def parse_reading(line):
    parts = [field.strip() for field in line.split(",")]
    if len(parts) != len(REQUIRED_FIELDS):
        raise ValueError("expected %d fields, got %d" % (len(REQUIRED_FIELDS), len(parts)))
    reading = {"name": parts[0]}
    for field, raw in zip(REQUIRED_FIELDS[1:], parts[1:]):
        reading[field] = float(raw)
    return reading


def validate_cave(cave):
    missing = [field for field in REQUIRED_FIELDS if field not in cave]
    if missing:
        raise ValueError("cave is missing fields: %s" % ", ".join(missing))
    for field in REQUIRED_FIELDS[1:]:
        if not isinstance(cave[field], (int, float)):
            raise ValueError("field %r must be numeric for cave %r" % (field, cave["name"]))
    return cave


def ventilate(caves):
    commands = []
    for cave in caves:
        validate_cave(cave)
        name = cave["name"]
        if cave["humidity"] < TARGET_HUMIDITY_PCT:
            deficit = TARGET_HUMIDITY_PCT - cave["humidity"]
            commands.append("%s: activate misting system (+%.1f%% humidity needed)" % (name, deficit))
        if cave["ammonia"] > MAX_AMMONIA_PPM:
            commands.append("%s: activate exhaust for %d minutes" % (name, FAN_RUNTIME_MINUTES))
        if cave["temperature"] > MAX_TEMPERATURE_C:
            commands.append("%s: activate cooler down to %.1fC" % (name, MAX_TEMPERATURE_C))
        elif cave["temperature"] < MIN_TEMPERATURE_C:
            commands.append("%s: activate heater up to %.1fC" % (name, MIN_TEMPERATURE_C))
    return commands


def format_report(caves, commands):
    lines = ["Aging environment report for %d cave(s)" % len(caves)]
    lines.append("targets: humidity >= %.1f%%, ammonia <= %.1f ppm, temperature %.1f-%.1fC"
                 % (TARGET_HUMIDITY_PCT, MAX_AMMONIA_PPM, MIN_TEMPERATURE_C, MAX_TEMPERATURE_C))
    if commands:
        lines.extend("  " + command for command in commands)
    else:
        lines.append("  all caves within limits")
    return "\n".join(lines)


def main():
    caves = [parse_reading(line) for line in SENSOR_FEED.splitlines() if line.strip()]
    commands = ventilate(caves)
    print(format_report(caves, commands))
    exhausting = sum(1 for command in commands if "exhaust" in command)
    if exhausting:
        print("total exhaust runtime: %d minutes" % (exhausting * FAN_RUNTIME_MINUTES))


if __name__ == "__main__":
    main()

