BISQUE_PEAK_TEMP = 1050
GLAZE_PEAK_TEMP = 1250
RAMP_RATE_DEG_PER_HOUR = 150.0
PEAK_HOLD_HOURS = 2.0
SAFETY_SHUTOFF_TEMP = 1200
THICKNESS_FACTORS = {"thin": 0.75, "medium": 1.0, "thick": 1.5}
DEFAULT_THICKNESS = "medium"
HOURS_PRECISION = 2


def thickness_factor(thickness):
    """Return the ramp multiplier for a named thickness."""
    try:
        return THICKNESS_FACTORS[thickness]
    except KeyError:
        known = ", ".join(sorted(THICKNESS_FACTORS))
        raise ValueError("unknown thickness %r (expected one of %s)" % (thickness, known))


def target_temperature(raw):
    """Bisque peak for raw clay, glaze peak otherwise, limited by the shutoff."""
    wanted = BISQUE_PEAK_TEMP if raw else GLAZE_PEAK_TEMP
    return min(wanted, SAFETY_SHUTOFF_TEMP)


def firing_hours(peak, thickness):
    """Hours needed to ramp up to the peak plus the soak at the peak."""
    ramp_hours = peak / RAMP_RATE_DEG_PER_HOUR * thickness_factor(thickness)
    return round(ramp_hours + PEAK_HOLD_HOURS, HOURS_PRECISION)


def fire(programs):
    """Build the heating curve for each program: peak temperature and hours."""
    curves = []
    for program in programs:
        clay = program["clay"]
        thickness = program.get("thickness", DEFAULT_THICKNESS)
        raw = bool(program.get("raw", False))
        peak = target_temperature(raw)
        curves.append({
            "clay": clay,
            "thickness": thickness,
            "peak": peak,
            "hours": firing_hours(peak, thickness),
            "capped": peak == SAFETY_SHUTOFF_TEMP and not raw,
        })
    return curves


def format_report(curves):
    """Render the firing schedules as human readable lines."""
    lines = []
    for curve in curves:
        line = "%-10s %-6s %5.2f h  peak %d C" % (
            curve["clay"], curve["thickness"], curve["hours"], curve["peak"])
        if curve["capped"]:
            line += " (limited to safety shutoff %d C)" % SAFETY_SHUTOFF_TEMP
        lines.append(line)
    total = round(sum(curve["hours"] for curve in curves), HOURS_PRECISION)
    lines.append("total kiln time: %.2f h" % total)
    return "\n".join(lines)


def main():
    programs = [
        {"clay": "stoneware", "thickness": "thick", "raw": True},
        {"clay": "porcelain", "thickness": "thin"},
        {"clay": "earthenware"},
    ]
    print(format_report(fire(programs)))


if __name__ == "__main__":
    main()

