SEA_LEVEL_AIR_DENSITY = 1.225
STANDARD_TEMPERATURE_K = 288.15
KELVIN_OFFSET = 273.15
ABSOLUTE_ZERO_CELSIUS = -273.15
STANDARD_PASSENGER_WEIGHT = 85.0
SAFETY_LIFT_MARGIN = 150.0
FABRIC_SAFE_TEMP_LIMIT = 120.0
BURNER_MAX_HEAT_OUTPUT = 250.0
BURNER_HEATUP_SECONDS = 300.0
AIR_SPECIFIC_HEAT = 1.005


def validate(flight):
    volume = float(flight["volume"])
    temperature = float(flight["temperature"])
    passengers = int(flight["passengers"])
    if volume <= 0.0:
        raise ValueError("envelope volume must be positive")
    if temperature <= ABSOLUTE_ZERO_CELSIUS:
        raise ValueError("outside temperature below absolute zero")
    if passengers < 0:
        raise ValueError("passenger count cannot be negative")
    return volume, temperature, passengers


def outside_density(temperature):
    return SEA_LEVEL_AIR_DENSITY * STANDARD_TEMPERATURE_K / (temperature + KELVIN_OFFSET)


def required_lift(passengers):
    return passengers * STANDARD_PASSENGER_WEIGHT + SAFETY_LIFT_MARGIN


def internal_temperature(volume, temperature, passengers):
    density_out = outside_density(temperature)
    density_in = density_out - required_lift(passengers) / volume
    if density_in <= 0.0:
        return None, density_in
    temp_in_k = (temperature + KELVIN_OFFSET) * density_out / density_in
    return temp_in_k - KELVIN_OFFSET, density_in


def heat_required(volume, temperature, inside_temperature, density_in):
    return density_in * volume * AIR_SPECIFIC_HEAT * (inside_temperature - temperature)


def available_heat():
    return BURNER_MAX_HEAT_OUTPUT * BURNER_HEATUP_SECONDS


def capacity(flights):
    reports = []
    for flight in flights:
        volume, temperature, passengers = validate(flight)
        load = required_lift(passengers)
        inside, density_in = internal_temperature(volume, temperature, passengers)
        if inside is None:
            reports.append(
                "CANCELED: %.0f m3 cannot lift %.0f kg at %.1f C" % (volume, load, temperature)
            )
            continue
        if inside > FABRIC_SAFE_TEMP_LIMIT:
            reports.append(
                "CANCELED: needs %.1f C, fabric limit is %.1f C"
                % (inside, FABRIC_SAFE_TEMP_LIMIT)
            )
            continue
        heat = heat_required(volume, temperature, inside, density_in)
        if heat > available_heat():
            reports.append(
                "CANCELED: needs %.0f kJ, burner delivers %.0f kW for %.0f s"
                % (heat, BURNER_MAX_HEAT_OUTPUT, BURNER_HEATUP_SECONDS)
            )
            continue
        reports.append(
            "CLEARED: %d pax (%.0f kg incl. %.0f kg margin), inside %.1f C, %.0f kJ"
            % (passengers, load, SAFETY_LIFT_MARGIN, inside, heat)
        )
    return reports


