import math

TARGET_PH = 6.0
PH_TOLERANCE = 0.3
MAX_PH_SHIFT_PER_DOSE = 0.5
PH_ADJUSTER_ML_PER_PH_PER_LITER = 1.5
NUTRIENT_ML_PER_EC_PER_LITER = 2.0
EC_TARGET = 1.8
EC_FLUSH_THRESHOLD = 3.5
PUMP_RATE_ML_PER_SEC = 4.0
FLUSH_VOLUME_LITERS = 50.0
MAX_RETRIES = 3
DEFAULT_TIMEOUT = 120.0


def validate_reading(reading):
    ph, ec, volume = reading["ph"], reading["ec"], reading["volume"]
    if not 0.0 < ph < 14.0:
        raise ValueError("acidity level out of range: %r" % (ph,))
    if ec < 0.0:
        raise ValueError("electrical conductivity must not be negative")
    if volume <= 0.0:
        raise ValueError("reservoir volume must be positive")
    return ph, ec, volume


def ph_plan(ph, volume):
    deviation = ph - TARGET_PH
    if abs(deviation) <= PH_TOLERANCE:
        return {"agent": None, "ml": 0.0, "cycles": 0, "seconds_per_cycle": 0.0}
    agent = "ph_down" if deviation > 0.0 else "ph_up"
    millilitres = abs(deviation) * PH_ADJUSTER_ML_PER_PH_PER_LITER * volume
    cycles = min(math.ceil(abs(deviation) / MAX_PH_SHIFT_PER_DOSE), MAX_RETRIES)
    seconds = millilitres / cycles / PUMP_RATE_ML_PER_SEC
    return {
        "agent": agent,
        "ml": millilitres,
        "cycles": cycles,
        "seconds_per_cycle": min(seconds, DEFAULT_TIMEOUT),
    }


def nutrient_plan(ec, volume):
    if ec >= EC_FLUSH_THRESHOLD:
        return {"ml": 0.0, "seconds": 0.0, "flush_liters": FLUSH_VOLUME_LITERS}
    millilitres = max(EC_TARGET - ec, 0.0) * NUTRIENT_ML_PER_EC_PER_LITER * volume
    seconds = millilitres / PUMP_RATE_ML_PER_SEC
    return {
        "ml": millilitres,
        "seconds": min(seconds, DEFAULT_TIMEOUT),
        "flush_liters": 0.0,
    }


def dose(readings):
    plans = []
    for reading in readings:
        ph, ec, volume = validate_reading(reading)
        acid = ph_plan(ph, volume)
        nutrients = nutrient_plan(ec, volume)
        plans.append({"ph": acid, "nutrients": nutrients})
    return plans


def format_plan(index, plan):
    acid, nutrients = plan["ph"], plan["nutrients"]
    lines = ["reservoir %d:" % index]
    if acid["agent"] is None:
        lines.append("  acidity within %.2f of %.2f, no adjuster" % (PH_TOLERANCE, TARGET_PH))
    else:
        lines.append("  %s %.1f ml in %d/%d cycles of %.1f s" % (
            acid["agent"], acid["ml"], acid["cycles"], MAX_RETRIES,
            acid["seconds_per_cycle"]))
    if nutrients["flush_liters"]:
        lines.append("  conductivity above %.1f: replace %.1f L of water" % (
            EC_FLUSH_THRESHOLD, nutrients["flush_liters"]))
    else:
        lines.append("  nutrients %.1f ml, pump %.1f s (cap %.0f s)" % (
            nutrients["ml"], nutrients["seconds"], DEFAULT_TIMEOUT))
    return "\n".join(lines)


def main():
    readings = [
        {"ph": 7.4, "ec": 1.1, "volume": 40.0},
        {"ph": 6.1, "ec": 4.0, "volume": 25.0},
        {"ph": 5.2, "ec": 1.75, "volume": 60.0},
    ]
    for index, plan in enumerate(dose(readings), start=1):
        print(format_plan(index, plan))


if __name__ == "__main__":
    main()

