OLIVE_LYE_MULTIPLIER = 0.1353
COCONUT_LYE_MULTIPLIER = 0.1900
PALM_LYE_MULTIPLIER = 0.1410
STANDARD_WATER_RATIO = 0.38
SUPERFAT_DISCOUNT = 0.05
MIN_CURING_WEEKS = 4
SUPPORTED_OILS = ("olive", "coconut", "palm")
ROUNDING_PRECISION = 2


def validate_recipe(recipe):
    """Return a clean {oil: grams} mapping, raising on bad input."""
    if not isinstance(recipe, dict):
        raise TypeError("each recipe must be a dict of oil names to grams")
    unknown = set(recipe) - set(SUPPORTED_OILS)
    if unknown:
        raise ValueError("unsupported oils: " + ", ".join(sorted(unknown)))
    cleaned = {}
    for oil in SUPPORTED_OILS:
        grams = recipe.get(oil, 0.0)
        if isinstance(grams, bool) or not isinstance(grams, (int, float)):
            raise TypeError("grams of %s must be numeric" % oil)
        if grams < 0:
            raise ValueError("grams of %s must not be negative" % oil)
        cleaned[oil] = float(grams)
    if sum(cleaned.values()) <= 0:
        raise ValueError("a recipe needs at least one oil with weight")
    return cleaned


def required_lye(oils):
    """Sodium hydroxide weight after applying the superfat discount."""
    raw_lye = oils["olive"] * OLIVE_LYE_MULTIPLIER
    raw_lye += oils["coconut"] * COCONUT_LYE_MULTIPLIER
    raw_lye += oils["palm"] * PALM_LYE_MULTIPLIER
    return raw_lye * (1.0 - SUPERFAT_DISCOUNT)


def required_water(oils):
    """Water weight derived from the total oil weight."""
    return sum(oils.values()) * STANDARD_WATER_RATIO


def saponify(recipes):
    """Turn a sequence of oil recipes into lye/water/curing batch results."""
    batches = []
    for recipe in recipes:
        oils = validate_recipe(recipe)
        batches.append({
            "total_oil": round(sum(oils.values()), ROUNDING_PRECISION),
            "lye": round(required_lye(oils), ROUNDING_PRECISION),
            "water": round(required_water(oils), ROUNDING_PRECISION),
            "curing_weeks": MIN_CURING_WEEKS,
        })
    return batches


def format_batch(index, batch):
    percent = SUPERFAT_DISCOUNT * 100
    return (
        "Batch %d: %.*f g oils -> %.*f g lye (%.0f%% superfat), "
        "%.*f g water, cure %d weeks"
        % (
            index,
            ROUNDING_PRECISION, batch["total_oil"],
            ROUNDING_PRECISION, batch["lye"],
            percent,
            ROUNDING_PRECISION, batch["water"],
            batch["curing_weeks"],
        )
    )


def main():
    recipes = [
        {"olive": 500, "coconut": 200},
        {"olive": 300, "coconut": 300, "palm": 400},
    ]
    for number, batch in enumerate(saponify(recipes), start=1):
        print(format_batch(number, batch))


if __name__ == "__main__":
    main()

