BRONZE_MELTING_POINT_C = 950.0
CRUCIBLE_PREHEAT_C = 620.0
MAX_POUR_DURATION_S = 30.0
THERMAL_SHRINKAGE_RATE = 0.05
MOLD_COOLING_TIME_MIN = 45.0
FURNACE_RAMP_C_PER_S = 8.0
POUR_RATE_L_PER_S = 0.5
MAX_RETRIES = 3
DEFAULT_TIMEOUT = 20.0


def required_volume(volume):
    """Molten metal needed once thermal shrinkage is compensated."""
    if volume <= 0:
        raise ValueError("mold volume must be positive")
    return round(volume * (1.0 + THERMAL_SHRINKAGE_RATE), 3)


def heat_furnace(ambient_c):
    """Drive the furnace to the bronze melting point in timed soak cycles."""
    if ambient_c >= BRONZE_MELTING_POINT_C:
        raise ValueError("ambient temperature already exceeds the melting point")
    temperature = ambient_c
    attempts = 0
    while temperature < BRONZE_MELTING_POINT_C:
        if attempts == MAX_RETRIES:
            raise RuntimeError("furnace failed to reach melting point")
        temperature = min(
            BRONZE_MELTING_POINT_C,
            temperature + FURNACE_RAMP_C_PER_S * DEFAULT_TIMEOUT,
        )
        attempts += 1
    return temperature, attempts


def crucible_hold(furnace_c):
    """Crucible is held at preheat while the furnace keeps the charge molten."""
    if furnace_c < CRUCIBLE_PREHEAT_C:
        raise RuntimeError("furnace cannot sustain the crucible preheat")
    return CRUCIBLE_PREHEAT_C


def pour_duration(metal_volume):
    seconds = metal_volume / POUR_RATE_L_PER_S
    if seconds > MAX_POUR_DURATION_S:
        raise RuntimeError("pour would exceed the maximum duration: cold shut risk")
    return round(seconds, 2)


def cast(molds):
    """Plan every pour: metal volume, furnace cycle, pour time, rest period."""
    plans = []
    for mold in molds:
        metal = required_volume(mold["volume"])
        furnace_c, cycles = heat_furnace(mold["ambient"])
        plans.append(
            {
                "volume": mold["volume"],
                "metal_volume": metal,
                "furnace_c": furnace_c,
                "crucible_c": crucible_hold(furnace_c),
                "heat_cycles": cycles,
                "soak_time_s": cycles * DEFAULT_TIMEOUT,
                "pour_time_s": pour_duration(metal),
                "rest_min": MOLD_COOLING_TIME_MIN,
            }
        )
    return plans


def format_plan(plan):
    return (
        "{volume} L mold -> {metal_volume} L bronze at {furnace_c} C "
        "(crucible {crucible_c} C, soak {soak_time_s} s over {heat_cycles} cycles); "
        "pour {pour_time_s} s, rest {rest_min} min"
    ).format(**plan)


def main():
    molds = [{"volume": 10.0, "ambient": 25.0}, {"volume": 4.0, "ambient": 700.0}]
    for plan in cast(molds):
        print(format_plan(plan))
    try:
        cast([{"volume": 40.0, "ambient": 25.0}])
    except RuntimeError as exc:
        print("rejected:", exc)


if __name__ == "__main__":
    main()

