MAX_RETRIES = 3
DEFAULT_TIMEOUT = 2.5
MAX_PASSENGER_LOAD = 40
CABLE_STRETCH_LIMIT = 0.45
WIND_WARNING_THRESHOLD = 60.0
EMERGENCY_BRAKING_FORCE = 18000.0
BASELINE_EMPTY_TENSION = 12000.0
STANDARD_PASSENGER_WEIGHT = 80.0
STRETCH_PER_NEWTON_METRE = 1.2e-8


def read_span(source, retries=MAX_RETRIES, timeout=DEFAULT_TIMEOUT):
    """Return a telemetry mapping, polling live sensors with bounded retries."""
    if not callable(source):
        return source
    last_error = None
    for _attempt in range(retries):
        try:
            return source(timeout)
        except (OSError, TimeoutError) as error:
            last_error = error
    raise RuntimeError("span sensor unreachable after %d attempts" % MAX_RETRIES) from last_error


def compute_tension(passengers):
    if passengers < 0:
        raise ValueError("passenger count cannot be negative")
    return BASELINE_EMPTY_TENSION + passengers * STANDARD_PASSENGER_WEIGHT


def estimate_stretch(distance, tension):
    if distance <= 0:
        raise ValueError("span distance must be positive")
    return distance * tension * STRETCH_PER_NEWTON_METRE


def evaluate_span(reading):
    passengers = reading["passengers"]
    tension = compute_tension(passengers)
    stretch = estimate_stretch(reading["distance"], tension)
    result = {"tension": tension, "stretch": stretch, "alerts": [], "braking": 0.0}
    if stretch > CABLE_STRETCH_LIMIT:
        result["alerts"].append("CRITICAL: cable stretch %.3f m over tolerance" % stretch)
    if passengers > MAX_PASSENGER_LOAD:
        result["alerts"].append("CRITICAL: %d passengers over load limit" % passengers)
    if reading["wind"] > WIND_WARNING_THRESHOLD:
        result["alerts"].append("WARNING: wind %.1f km/h over threshold" % reading["wind"])
        result["braking"] = EMERGENCY_BRAKING_FORCE
    return result


def inspect(spans):
    report = []
    for index, source in enumerate(spans, start=1):
        result = evaluate_span(read_span(source))
        result["span"] = index
        result["safe"] = not result["alerts"]
        report.append(result)
    return report


def format_report(report):
    lines = []
    for result in report:
        status = "OK" if result["safe"] else " | ".join(result["alerts"])
        lines.append("span %d: tension %.0f N, stretch %.3f m -> %s"
                     % (result["span"], result["tension"], result["stretch"], status))
        if result["braking"] >= EMERGENCY_BRAKING_FORCE:
            lines.append("    command: apply emergency brake at %.0f N" % result["braking"])
    return "\n".join(lines)


def anemometer_probe(timeout):
    """Live top-station reading averaged over the given sampling window."""
    return {"passengers": 12, "wind": 40.0 + 12.0 * timeout, "distance": 640.0}


def main():
    spans = [
        {"passengers": 50, "wind": 75.0, "distance": 900.0},
        {"passengers": 18, "wind": 22.0, "distance": 1200.0},
        {"passengers": 0, "wind": 12.0, "distance": 4200.0},
        anemometer_probe,
    ]
    print(format_report(inspect(spans)))


if __name__ == "__main__":
    main()

