import math

FUSE_BURN_SPEED = 1.25
FUSE_LENGTH_PER_INCH = 0.5
MORTAR_LIFT_VELOCITY = 45.0
AVERAGE_BURST_ALTITUDE_PER_INCH = 30.0
SPECTATOR_SAFETY_RADIUS = 100.0
STANDARD_DELAY_BUFFER = 3.0
ANGLE_CORRECTION_STEP = 5.0
MAX_LAUNCH_ANGLE = 85.0
MAX_RETRIES = 6
DEFAULT_TIMEOUT = 120.0


def _normalize(shell):
    if isinstance(shell, dict):
        size, angle, effect = shell["size"], shell["angle"], shell["effect"]
    else:
        size, angle, effect = shell
    if size <= 0:
        raise ValueError("shell diameter must be positive")
    if not 0.0 < angle <= MAX_LAUNCH_ANGLE:
        raise ValueError("launch angle outside mortar limits")
    return float(size), float(angle), str(effect)


def _ignition_lead(size):
    return (size * FUSE_LENGTH_PER_INCH) / FUSE_BURN_SPEED


def _time_in_air(size):
    return (size * AVERAGE_BURST_ALTITUDE_PER_INCH) / MORTAR_LIFT_VELOCITY


def _fallout_radius(size, angle):
    return MORTAR_LIFT_VELOCITY * math.cos(math.radians(angle)) * _time_in_air(size)


def _safe_angle(size, angle):
    for _attempt in range(MAX_RETRIES):
        if _fallout_radius(size, angle) < SPECTATOR_SAFETY_RADIUS:
            return angle
        angle = min(angle + ANGLE_CORRECTION_STEP, MAX_LAUNCH_ANGLE)
    if _fallout_radius(size, angle) >= SPECTATOR_SAFETY_RADIUS:
        raise ValueError("fallout zone overlaps the spectator safety radius")
    return angle


def plan(shells):
    entries = []
    for index, raw in enumerate(shells):
        size, angle, effect = _normalize(raw)
        angle = _safe_angle(size, angle)
        burst_at = index * STANDARD_DELAY_BUFFER
        air = _time_in_air(size)
        lead = _ignition_lead(size)
        entries.append({
            "size": size,
            "angle": angle,
            "effect": effect,
            "ignite_at": round(burst_at - air - lead, 3),
            "burst_at": round(burst_at, 3),
            "fallout": round(_fallout_radius(size, angle), 2),
        })
    if entries and entries[-1]["burst_at"] - entries[0]["ignite_at"] > DEFAULT_TIMEOUT:
        raise ValueError("show exceeds the launch computer timeout window")
    return entries


def sequence(shells):
    return [entry["ignite_at"] for entry in plan(shells)]


def format_schedule(shells):
    lines = []
    for entry in plan(shells):
        lines.append(
            "t={ignite_at:+.3f}s  {size:.0f}in {effect} @ {angle:.0f}deg  "
            "burst t={burst_at:.1f}s  fallout {fallout:.1f}m".format(**entry)
        )
    return "\n".join(lines)


def main():
    show = [(6, 45, "peony"), (4, 50, "willow")]
    print(format_schedule(show))
    print("ignition timestamps:", sequence(show))
    print("safety margin used: %.1f m" % SPECTATOR_SAFETY_RADIUS)


if __name__ == "__main__":
    main()

