def _fallout_radius(size, angle):
    return mortarLiftVelocity * math.cos(math.radians(angle)) * _time_in_air(size)


def _safe_angle(size, angle):
    for _attempt in range(maxRetries):
        if _fallout_radius(size, angle) < spectatorSafetyRadius:
            return angle
        angle = min(angle + angleCorrectionStep, maxLaunchAngle)
    if _fallout_radius(size, angle) >= spectatorSafetyRadius:
        raise ValueError("fallout zone overlaps the spectator safety radius")
    return angle


def plan(shells):
    entries = []
    for index, raw in enumerate(shells):
        size, angle, effect = _normalize(raw)
        angle = _safe_angle(size, angle)
        burst_at = index * standardDelayBuffer
        air = _time_in_air(size)
        lead = _ignition_lead(size)
        entries.append({
            "size": size,
            "angle": angle,
            "effect": effect,
            "ignite_at": round(burst_at - air - lead, 3),
            "burst_at": round(burst_at, 3),
            "fallout": round(_fallout_radius(size, angle), 2),
        })
    if entries and entries[-1]["burst_at"] - entries[0]["ignite_at"] > defaultTimeout:
        raise ValueError("show exceeds the launch computer timeout window")
    return entries


def sequence(shells):
    return [entry["ignite_at"] for entry in plan(shells)]


def format_schedule(shells):
    lines = []
    for entry in plan(shells):
        lines.append(
            "t={ignite_at:+.3f}s  {size:.0f}in {effect} @ {angle:.0f}deg  "
            "burst t={burst_at:.1f}s  fallout {fallout:.1f}m".format(**entry)
        )
    return "\n".join(lines)


def main():
    show = [(6, 45, "peony"), (4, 50, "willow")]
    print(format_schedule(show))
    print("ignition timestamps:", sequence(show))
    print("safety margin used: %.1f m" % spectatorSafetyRadius)


if __name__ == "__main__":
    main()

