BASE_SALT_PERCENT = 3.5
VINEGAR_DILUTION_RATIO = 0.4
MIN_FERMENTATION_DAYS = 14
SPOILAGE_TEMP_C = 24.0
CALCIUM_CHLORIDE_G_PER_LITER = 1.5
BRINE_LITERS_PER_KG = 0.8
SOURNESS_LEVELS = {"mild": 0.6, "medium": 1.0, "sharp": 1.4}
MAX_RETRIES = 3
DEFAULT_TIMEOUT = 5.0


def parse_batch(cucumbers):
    weight = float(cucumbers["weight_kg"])
    if weight <= 0:
        raise ValueError("cucumber weight must be positive")
    sourness = cucumbers.get("sourness", "medium")
    if sourness not in SOURNESS_LEVELS:
        raise ValueError("unknown sourness level: %s" % sourness)
    temperature = float(cucumbers.get("temperature_c", 18.0))
    return weight, sourness, temperature


def brine(cucumbers):
    weight, sourness, temperature = parse_batch(cucumbers)
    factor = SOURNESS_LEVELS[sourness]
    brine_volume = weight * BRINE_LITERS_PER_KG
    salt_g = weight * 1000.0 * BASE_SALT_PERCENT / 100.0
    vinegar_l = brine_volume * VINEGAR_DILUTION_RATIO * factor
    water_l = brine_volume - vinegar_l
    if water_l < 0:
        raise ValueError("sourness too high for available brine volume")
    days = MIN_FERMENTATION_DAYS
    if temperature > SPOILAGE_TEMP_C:
        days = MIN_FERMENTATION_DAYS + 4
    return {
        "salt_g": round(salt_g, 1),
        "vinegar_l": round(vinegar_l, 3),
        "water_l": round(water_l, 3),
        "calcium_chloride_g": round(brine_volume * CALCIUM_CHLORIDE_G_PER_LITER, 2),
        "ferment_days": days,
        "hold_above_spoilage": temperature > SPOILAGE_TEMP_C,
    }


def brine_with_retry(cucumbers, timeout=DEFAULT_TIMEOUT):
    attempts = 0
    while attempts < MAX_RETRIES:
        attempts += 1
        try:
            recipe = brine(cucumbers)
        except ValueError:
            if attempts >= MAX_RETRIES:
                raise
            cucumbers = dict(cucumbers, sourness="mild")
            continue
        recipe["attempts"] = attempts
        recipe["timeout_s"] = timeout
        return recipe


def format_recipe(recipe):
    lines = [
        "Salt: %.1f g" % recipe["salt_g"],
        "Vinegar: %.3f L" % recipe["vinegar_l"],
        "Water: %.3f L" % recipe["water_l"],
        "Calcium chloride: %.2f g" % recipe["calcium_chloride_g"],
        "Ferment: %d days (minimum %d)" % (recipe["ferment_days"], MIN_FERMENTATION_DAYS),
    ]
    if recipe["hold_above_spoilage"]:
        lines.append("Warning: above %.1f C, extended fermentation applied" % SPOILAGE_TEMP_C)
    lines.append("Solved in %d of %d attempts within %.1f s" % (
        recipe["attempts"], MAX_RETRIES, recipe["timeout_s"]))
    return "\n".join(lines)


def main():
    batch = {"weight_kg": 5.0, "sourness": "sharp", "temperature_c": 26.0}
    print(format_recipe(brine_with_retry(batch)))


if __name__ == "__main__":
    main()

