HOURLY_RATE = 12.0
EXTRA_WALK_FEE = 15.0
LATE_PENALTY_PER_MINUTE = 2.0
MAX_DAILY_BASE_CHARGE = 80.0
TAX_RATE = 0.08
MAX_DAILY_HOURS = 24
STAY_FIELD_COUNT = 4
CURRENCY_DECIMALS = 2


def validate_stay(stay):
    """Unpack and sanity-check a single stay record."""
    if len(stay) != STAY_FIELD_COUNT:
        raise ValueError("a stay needs (hours, extra_walk, late_pickup, minutes_late)")
    hours, extra_walk, late_pickup, minutes_late = stay
    if hours < 0 or hours > MAX_DAILY_HOURS:
        raise ValueError("hours must be between 0 and %d" % MAX_DAILY_HOURS)
    if minutes_late < 0:
        raise ValueError("minutes_late cannot be negative")
    if not late_pickup:
        minutes_late = 0
    return hours, bool(extra_walk), bool(late_pickup), minutes_late


def base_charge(hours):
    """Hourly charge, capped by the daily maximum."""
    return min(hours * HOURLY_RATE, MAX_DAILY_BASE_CHARGE)


def surcharges(extra_walk, minutes_late):
    """Extras that are added after the daily cap is applied."""
    total = 0.0
    if extra_walk:
        total += EXTRA_WALK_FEE
    total += minutes_late * LATE_PENALTY_PER_MINUTE
    return total


def apply_tax(subtotal):
    return round(subtotal * (1.0 + TAX_RATE), CURRENCY_DECIMALS)


def stay_total(stay):
    hours, extra_walk, _late_pickup, minutes_late = validate_stay(stay)
    subtotal = base_charge(hours) + surcharges(extra_walk, minutes_late)
    return apply_tax(subtotal)


def bill(stays):
    """Return the taxed total for every stay in the list."""
    return [stay_total(stay) for stay in stays]


def format_receipt(stays, totals):
    lines = []
    for stay, total in zip(stays, totals):
        hours, extra_walk, late_pickup, minutes_late = validate_stay(stay)
        parts = ["%g h @ $%.2f" % (hours, HOURLY_RATE)]
        if hours * HOURLY_RATE > MAX_DAILY_BASE_CHARGE:
            parts.append("capped at $%.2f" % MAX_DAILY_BASE_CHARGE)
        if extra_walk:
            parts.append("walk $%.2f" % EXTRA_WALK_FEE)
        if late_pickup:
            parts.append("%d min late $%.2f" % (minutes_late, minutes_late * LATE_PENALTY_PER_MINUTE))
        parts.append("tax %.0f%%" % (TAX_RATE * 100))
        lines.append("%-56s => $%.*f" % (", ".join(parts), CURRENCY_DECIMALS, total))
    return "\n".join(lines)


def main():
    stays = [
        (5, False, False, 0),
        (8, True, True, 10),
        (MAX_DAILY_HOURS, False, True, 3),
    ]
    totals = bill(stays)
    print(format_receipt(stays, totals))
    print("Totals:", totals)
    print("Grand total: $%.*f" % (CURRENCY_DECIMALS, round(sum(totals), CURRENCY_DECIMALS)))


if __name__ == "__main__":
    main()

