PRICE_PER_OUNCE = 0.50
MAX_BASE_OUNCES = 32
MIN_BASE_OUNCES = 8
PROTEIN_SCOOP_PRICE = 1.50
MAX_PROTEIN_SCOOPS = 6
PREMIUM_FRUIT_PRICE = 2.00
LOYALTY_THRESHOLD = 15.00
LOYALTY_DISCOUNT_RATE = 0.10
SALES_TAX_RATE = 0.06
PRICE_DECIMALS = 2
RECEIPT_WIDTH = 34


def validate_order(order):
    """Return a normalised (ounces, scoops, premium) triple or raise ValueError."""
    ounces, scoops, premium = order
    if ounces < MIN_BASE_OUNCES:
        raise ValueError("base size must be at least %d ounces" % MIN_BASE_OUNCES)
    if scoops < 0 or scoops > MAX_PROTEIN_SCOOPS:
        raise ValueError("scoops must be between 0 and %d" % MAX_PROTEIN_SCOOPS)
    return min(ounces, MAX_BASE_OUNCES), scoops, bool(premium)


def base_cost(ounces):
    return min(ounces, MAX_BASE_OUNCES) * PRICE_PER_OUNCE


def addon_cost(scoops, premium):
    cost = scoops * PROTEIN_SCOOP_PRICE
    if premium:
        cost += PREMIUM_FRUIT_PRICE
    return cost


def apply_loyalty_discount(subtotal):
    if subtotal > LOYALTY_THRESHOLD:
        return subtotal * (1.0 - LOYALTY_DISCOUNT_RATE)
    return subtotal


def price_order(order):
    ounces, scoops, premium = validate_order(order)
    subtotal = base_cost(ounces) + addon_cost(scoops, premium)
    discounted = apply_loyalty_discount(subtotal)
    return round(discounted * (1.0 + SALES_TAX_RATE), PRICE_DECIMALS)


def blend(orders):
    return [price_order(order) for order in orders]


def format_receipt(orders, prices):
    lines = ["SMOOTHIE BAR".center(RECEIPT_WIDTH), "-" * RECEIPT_WIDTH]
    for (ounces, scoops, premium), price in zip(orders, prices):
        served = min(ounces, MAX_BASE_OUNCES)
        label = "%doz" % served
        if scoops:
            label += " +%dx protein" % scoops
        if premium:
            label += " +premium fruit"
        if served * PRICE_PER_OUNCE + addon_cost(scoops, premium) > LOYALTY_THRESHOLD:
            label += " (loyalty)"
        lines.append(label.ljust(RECEIPT_WIDTH - 8) + ("%8.2f" % price))
    lines.append("-" * RECEIPT_WIDTH)
    total = round(sum(prices), PRICE_DECIMALS)
    lines.append("TOTAL".ljust(RECEIPT_WIDTH - 8) + ("%8.2f" % total))
    return "\n".join(lines)


def main():
    orders = [(20, 1, False), (40, 3, True), (12, 0, False), (32, 2, True)]
    prices = blend(orders)
    print(prices)
    print(format_receipt(orders, prices))


if __name__ == "__main__":
    main()

