text_nat:
ADULT_TICKET_PRICE = 25.0
CHILD_TICKET_PRICE = 15.0
HELMET_RENTAL_FEE = 3.0
EXCLUSIVITY_FEE = 200.0
MAX_KARTS_PER_HEAT = 12
GROUP_FIELD_COUNT = 3
CURRENCY_SYMBOL = "$"
RECEIPT_WIDTH = 44


def _validate_group(group):
    """Unpack a (adults, children, exclusive) tuple, rejecting bad input."""
    if len(group) != GROUP_FIELD_COUNT:
        raise ValueError(
            "each group needs exactly %d fields: %r" % (GROUP_FIELD_COUNT, group)
        )
    adults, children, exclusive = group
    for count in (adults, children):
        if isinstance(count, bool) or not isinstance(count, int):
            raise TypeError("racer counts must be integers: %r" % (group,))
        if count < 0:
            raise ValueError("racer counts must not be negative: %r" % (group,))
    return adults, children, bool(exclusive)


def _apply_kart_limit(adults, children):
    """Cap a group at the track's kart limit, seating children first."""
    if adults + children <= MAX_KARTS_PER_HEAT:
        return adults, children
    seated_children = min(children, MAX_KARTS_PER_HEAT)
    return MAX_KARTS_PER_HEAT - seated_children, seated_children


def _group_cost(adults, children, exclusive):
    seated_adults, seated_children = _apply_kart_limit(adults, children)
    total = seated_adults * ADULT_TICKET_PRICE
    total += seated_children * CHILD_TICKET_PRICE
    total += (seated_adults + seated_children) * HELMET_RENTAL_FEE
    if exclusive:
        total += EXCLUSIVITY_FEE
    return total


def race(groups):
    """Return the list of ticketing totals, one per group."""
    return [_group_cost(*_validate_group(group)) for group in groups]


def format_receipt(groups, totals):
    """Render a printable receipt for already-priced groups."""
    lines = [" GO KART TICKETING ".center(RECEIPT_WIDTH, "=")]
    for group, total in zip(groups, totals):
        adults, children, exclusive = _validate_group(group)
        seated_adults, seated_children = _apply_kart_limit(adults, children)
        label = "%d adult / %d child" % (seated_adults, seated_children)
        if seated_adults + seated_children < adults + children:
            label += " (capped at %d karts)" % MAX_KARTS_PER_HEAT
        if exclusive:
            label += " +exclusive"
        amount = "%s%.2f" % (CURRENCY_SYMBOL, total)
        lines.append(label.ljust(RECEIPT_WIDTH - len(amount)) + amount)
    grand_total = "%s%.2f" % (CURRENCY_SYMBOL, sum(totals))
    lines.append("-" * RECEIPT_WIDTH)
    lines.append("TOTAL DUE".ljust(RECEIPT_WIDTH - len(grand_total)) + grand_total)
    return "\n".join(lines)


def main():
    groups = [(2, 2, False), (5, 10, True), (9, 1, False)]
    totals = race(groups)
    print(totals)
    print(format_receipt(groups, totals))


if __name__ == "__main__":
    main()

