        adults, children, exclusive = _validate_group(group)
        seated_adults, seated_children = _apply_kart_limit(adults, children)
        label = "%d adult / %d child" % (seated_adults, seated_children)
        if seated_adults + seated_children < adults + children:
            label += " (capped at %d karts)" % maxKartsPerHeat
        if exclusive:
            label += " +exclusive"
        amount = "%s%.2f" % (currencySymbol, total)
        lines.append(label.ljust(receiptWidth - len(amount)) + amount)
    grand_total = "%s%.2f" % (currencySymbol, sum(totals))
    lines.append("-" * receiptWidth)
    lines.append("TOTAL DUE".ljust(receiptWidth - len(grand_total)) + grand_total)
    return "\n".join(lines)


def main():
