MINIMUM_CALLOUT_FEE = 50
BUILDING_FIELD_COUNT = 3
CURRENCY_SYMBOL = "$"
QUOTE_DECIMALS = 2


def validate_building(building):
    """Check that a building entry is a (ground, upper, screens) triple."""
    if len(building) != BUILDING_FIELD_COUNT:
        raise ValueError(
            "each building needs exactly %d fields" % BUILDING_FIELD_COUNT
        )
    ground, upper, screens = building
    if not isinstance(screens, bool):
        raise TypeError("the screen cleaning flag must be a boolean")
    if ground < 0 or upper < 0:
        raise ValueError("window counts cannot be negative")
    return ground, upper, screens


def quote_building(building, upper_allowance):
    """Return (quote, upper windows actually cleaned) for one building."""
    ground, upper, screens = validate_building(building)
    upper_cleaned = min(upper, upper_allowance)
    total = ground * GROUND_WINDOW_RATE + upper_cleaned * UPPER_WINDOW_RATE
    if screens:
        total += (ground + upper_cleaned) * SCREEN_CLEAN_RATE
    if total < MINIMUM_CALLOUT_FEE:
        total = MINIMUM_CALLOUT_FEE
    return float(total), upper_cleaned


def wash(buildings):
    """Quote every building, respecting the shared daily upper window limit."""
    remaining_upper = DAILY_UPPER_WINDOW_LIMIT
    quotes = []
    for building in buildings:
        quote, upper_cleaned = quote_building(building, remaining_upper)
        remaining_upper -= upper_cleaned
        quotes.append(quote)
    return quotes


def format_quote(quote):
