import sys
import time
import urllib.request

BASE_SERVICE_FEE = 60.0
LOCK_PICK_FEE = 30.0
KEY_DUPLICATION_FEE = 5.0
FREE_TRAVEL_MILES = 10
EXTRA_MILE_RATE = 3.0
BULK_DISCOUNT = 20.0
BULK_DISCOUNT_MIN_LOCKS = 3
CURRENCY_DECIMALS = 2
MAX_RETRIES = 3
DEFAULT_TIMEOUT = 5.0
RETRY_BACKOFF_SECONDS = 1.0


def travel_charge(miles):
    return max(0, miles - FREE_TRAVEL_MILES) * EXTRA_MILE_RATE


def visit_total(miles, locks, keys):
    total = BASE_SERVICE_FEE
    total += locks * LOCK_PICK_FEE
    total += keys * KEY_DUPLICATION_FEE
    total += travel_charge(miles)
    if locks > BULK_DISCOUNT_MIN_LOCKS:
        total -= BULK_DISCOUNT
    return round(total, CURRENCY_DECIMALS)


def lock(calls):
    return [visit_total(miles, locks, keys) for miles, locks, keys in calls]


def parse_call(line):
    fields = [part.strip() for part in line.split(",")]
    if len(fields) != 3:
        raise ValueError("expected miles,locks,keys but got: %r" % line)
    miles, locks, keys = (int(field) for field in fields)
    if min(miles, locks, keys) < 0:
        raise ValueError("negative quantities are not billable: %r" % line)
    return miles, locks, keys


def parse_log(text):
    calls = []
    for line in text.splitlines():
        stripped = line.strip()
        if stripped and not stripped.startswith("#"):
            calls.append(parse_call(stripped))
    return calls


def fetch_log(url, timeout=DEFAULT_TIMEOUT):
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            with urllib.request.urlopen(url, timeout=timeout) as response:
                return response.read().decode("utf-8")
        except OSError as error:
            if attempt == MAX_RETRIES:
                raise RuntimeError("dispatch log unreachable: %s" % error)
            time.sleep(RETRY_BACKOFF_SECONDS * attempt)


def format_report(calls, totals):
    lines = []
    for (miles, locks, keys), total in zip(calls, totals):
        lines.append(
            "%3d mi  %2d locks  %2d keys  $%.*f"
            % (miles, locks, keys, CURRENCY_DECIMALS, total)
        )
    grand = round(sum(totals), CURRENCY_DECIMALS)
    lines.append("TOTAL BILLED: $%.*f" % (CURRENCY_DECIMALS, grand))
    return "\n".join(lines)


def main(argv):
    if argv:
        text = fetch_log(argv[0])
    else:
        text = sys.stdin.read()
    calls = parse_log(text)
    totals = lock(calls)
    print(format_report(calls, totals))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

