text_nat:
RATE_PER_SQFT = 0.05
MAX_BILLABLE_SQFT = 5000
MINIMUM_CHARGE = 90.0
SEVERE_SURCHARGE = 120.0
RECURRING_DISCOUNT_RATE = 0.15
MONEY_PRECISION = 2
CURRENCY_SYMBOL = "$"
FIELD_SEPARATOR = ","
TREATMENT_FIELDS = 3
SEVERE_FLAG = "severe"
RECURRING_FLAG = "recurring"


def treatment_charge(square_feet):
    billable = min(square_feet, MAX_BILLABLE_SQFT)
    return max(billable * RATE_PER_SQFT, MINIMUM_CHARGE)


def pest(treatments):
    bills = []
    for treatment in treatments:
        if len(treatment) != TREATMENT_FIELDS:
            raise ValueError("each treatment needs %d fields" % TREATMENT_FIELDS)
        square_feet, severe, recurring = treatment
        if square_feet < 0:
            raise ValueError("square footage cannot be negative")
        cost = treatment_charge(square_feet)
        if severe:
            cost += SEVERE_SURCHARGE
        if recurring:
            cost *= 1.0 - RECURRING_DISCOUNT_RATE
        bills.append(round(cost, MONEY_PRECISION))
    return bills


def parse_treatment(text):
    fields = text.split(FIELD_SEPARATOR)
    if len(fields) != TREATMENT_FIELDS:
        raise ValueError("cannot parse %r" % text)
    square_feet = int(fields[0].strip())
    severe = fields[1].strip().lower() == SEVERE_FLAG
    recurring = fields[2].strip().lower() == RECURRING_FLAG
    return (square_feet, severe, recurring)


def format_money(amount):
    return "%s%.*f" % (CURRENCY_SYMBOL, MONEY_PRECISION, amount)


def describe(treatment):
    square_feet, severe, recurring = treatment
    labels = []
    if severe:
        labels.append(SEVERE_FLAG)
    if recurring:
        labels.append(RECURRING_FLAG)
    if square_feet > MAX_BILLABLE_SQFT:
        labels.append("capped at %d sqft" % MAX_BILLABLE_SQFT)
    suffix = " (%s)" % ", ".join(labels) if labels else ""
    return "%5d sqft%s" % (square_feet, suffix)


def main():
    orders = [
        "2000, none, none",
        "800, severe, none",
        "6400, severe, recurring",
        "1200, none, recurring",
    ]
    treatments = [parse_treatment(line) for line in orders]
    bills = pest(treatments)
    for treatment, cost in zip(treatments, bills):
        print("%-45s %10s" % (describe(treatment), format_money(cost)))
    print("%-45s %10s" % ("TOTAL", format_money(sum(bills))))
    print(pest([(2000, False, False)]))


if __name__ == "__main__":
    main()

