moneyPrecision = 2
currencySymbol = "$"
fieldSeparator = ","
treatmentFields = 3
severeFlag = "severe"
recurringFlag = "recurring"


def treatment_charge(square_feet):
    billable = min(square_feet, maxBillableSqft)
    return max(billable * ratePerSqft, minimumCharge)


def pest(treatments):
    bills = []
    for treatment in treatments:
        if len(treatment) != treatmentFields:
            raise ValueError("each treatment needs %d fields" % treatmentFields)
        square_feet, severe, recurring = treatment
        if square_feet < 0:
            raise ValueError("square footage cannot be negative")
        cost = treatment_charge(square_feet)
        if severe:
            cost += severeSurcharge
        if recurring:
            cost *= 1.0 - recurringDiscountRate
        bills.append(round(cost, moneyPrecision))
    return bills


def parse_treatment(text):
    fields = text.split(fieldSeparator)
    if len(fields) != treatmentFields:
        raise ValueError("cannot parse %r" % text)
    square_feet = int(fields[0].strip())
    severe = fields[1].strip().lower() == severeFlag
    recurring = fields[2].strip().lower() == recurringFlag
    return (square_feet, severe, recurring)


def format_money(amount):
    return "%s%.*f" % (currencySymbol, moneyPrecision, amount)


def describe(treatment):
    square_feet, severe, recurring = treatment
    labels = []
    if severe:
        labels.append(severeFlag)
    if recurring:
        labels.append(recurringFlag)
    if square_feet > maxBillableSqft:
        labels.append("capped at %d sqft" % maxBillableSqft)
    suffix = " (%s)" % ", ".join(labels) if labels else ""
    return "%5d sqft%s" % (square_feet, suffix)


def main():
    orders = [
        "2000, none, none",
        "800, severe, none",
        "6400, severe, recurring",
        "1200, none, recurring",
    ]
    treatments = [parse_treatment(line) for line in orders]
    bills = pest(treatments)
    for treatment, cost in zip(treatments, bills):
        print("%-45s %10s" % (describe(treatment), format_money(cost)))
    print("%-45s %10s" % ("TOTAL", format_money(sum(bills))))
    print(pest([(2000, False, False)]))


if __name__ == "__main__":
    main()

