def validate_client(client):
    """Unpack and check a single (sessions, meal_plan, in_home) booking tuple."""
    if len(client) != 3:
        raise ValueError("each client needs sessions, meal plan flag and in-home flag")
    sessions, meal_plan, in_home = client
    if not isinstance(sessions, int) or isinstance(sessions, bool):
