        raise ValueError("session count cannot be negative")
    if not isinstance(meal_plan, bool) or not isinstance(in_home, bool):
        raise TypeError("meal plan and in-home training must be booleans")
    return sessions, meal_plan, in_home


def session_rate(sessions):
    """Per-session fee, discounted once the booking passes the bulk threshold."""
    if sessions > BULK_DISCOUNT_THRESHOLD:
        return DISCOUNTED_SESSION_FEE
    return STANDARD_SESSION_FEE


def billable_sessions(sessions):
    """Only a limited number of sessions can be billed in one booking."""
    return min(sessions, MAX_BILLABLE_SESSIONS)


def client_total(client):
