    parts = ["{0} sessions at {1}{2:.{3}f}".format(
        billable, CURRENCY_SYMBOL, session_rate(sessions), DECIMAL_PLACES)]
    if billable < sessions:
        parts.append("{0} session(s) over the limit of {1}".format(
            sessions - billable, MAX_BILLABLE_SESSIONS))
    if meal_plan:
        parts.append("meal plan {0}{1:.2f}".format(CURRENCY_SYMBOL, MEAL_PLAN_FEE))
    if in_home:
        parts.append("travel {0}{1:.2f}/session".format(
            CURRENCY_SYMBOL, TRAVEL_FEE_PER_SESSION))
    return "{0} => {1}{2:.{3}f}".format(
