TWIN_RATE = 40.0
KING_RATE = 70.0
ODOR_RATE_PER_MATTRESS = 20.0
TRAVEL_FEE = 15.0
MAX_MATTRESSES_PER_VISIT = 6
CURRENCY_SYMBOL = "$"
QUOTE_DECIMALS = 2


def validate_job(job):
    """Return (twins, kings, odor) from a job tuple, raising on bad input."""
    twins, kings, odor = job
    if not isinstance(twins, int) or not isinstance(kings, int):
        raise TypeError("mattress counts must be integers")
    if twins < 0 or kings < 0:
        raise ValueError("mattress counts must not be negative")
    return twins, kings, bool(odor)


def plan_visit(twins, kings):
    """Pick what fits in one visit: kings first, then twins, up to the cap."""
    kings_cleaned = min(kings, MAX_MATTRESSES_PER_VISIT)
    remaining_slots = MAX_MATTRESSES_PER_VISIT - kings_cleaned
    twins_cleaned = min(twins, remaining_slots)
    return twins_cleaned, kings_cleaned


def quote_job(job):
    """Compute the final quote in dollars for a single job tuple."""
    twins, kings, odor = validate_job(job)
    twins_cleaned, kings_cleaned = plan_visit(twins, kings)
    total = twins_cleaned * TWIN_RATE + kings_cleaned * KING_RATE
    if odor:
        total += (twins_cleaned + kings_cleaned) * ODOR_RATE_PER_MATTRESS
    total += TRAVEL_FEE
    return round(total, QUOTE_DECIMALS)


def mattress(jobs):
    """Return a list of final quotes, one per job tuple."""
    return [quote_job(job) for job in jobs]


def format_quote(amount):
    """Render a dollar amount for the printed report."""
    return "{}{:.{}f}".format(CURRENCY_SYMBOL, amount, QUOTE_DECIMALS)


def describe_job(job):
    """Human-readable summary of what will actually be cleaned."""
    twins, kings, odor = validate_job(job)
    twins_cleaned, kings_cleaned = plan_visit(twins, kings)
    skipped = (twins + kings) - (twins_cleaned + kings_cleaned)
    parts = ["{} twin(s)".format(twins_cleaned), "{} king(s)".format(kings_cleaned)]
    if odor:
        parts.append("odor treatment")
    if skipped:
        parts.append("{} deferred (cap {})".format(skipped, MAX_MATTRESSES_PER_VISIT))
    return ", ".join(parts)


def main():
    jobs = [(1, 1, False), (3, 5, True), (0, 0, True), (4, 2, False)]
    quotes = mattress(jobs)
    for job, amount in zip(jobs, quotes):
        print("{} -> {} [{}]".format(job, format_quote(amount), describe_job(job)))
    print("Total billed: {}".format(format_quote(sum(quotes))))
    print("Travel fees included: {}".format(format_quote(len(jobs) * TRAVEL_FEE)))
    print(quotes)


if __name__ == "__main__":
    main()

