def billable_days(days):
    """Clamp a requested rental length to the bookable range."""
    if isinstance(days, bool) or not isinstance(days, int):
        raise TypeError("rental length must be an integer number of days")
    if days < 1:
        raise ValueError("rental length must be at least one day")
    return min(days, MAX_RENTAL_DAYS)


def daily_rate(premium_skis, helmet):
    """Combined per-day charge for skis, optional helmet and the waiver."""
    rate = PREMIUM_SKI_DAILY_RATE if premium_skis else BASE_SKI_DAILY_RATE
    if helmet:
        rate += HELMET_DAILY_RATE
    return rate + INSURANCE_WAIVER_DAILY_RATE


