text_nat:
NORMAL_WIDTH = 400
WIDTH_TOLERANCE = 5
IDEAL_MOISTURE = 5
MOISTURE_TOLERANCE = 0.5
BASE_SPEED_LIMIT = 1000
ABSOLUTE_MAX_SPEED = 1200
PERFECT_SCORE = 100
DEFECT_PENALTY = 5
OVERSPEED_DEFECT_PENALTY = 10
OVERSPEED_SCORE = 0
MIN_SCORE = 0
PASS_THRESHOLD = 70
ROLL_FIELD_COUNT = 5


def validate_roll(roll):
    """Unpack a roll tuple (length, speed, moisture, width, defects)."""
    if len(roll) != ROLL_FIELD_COUNT:
        raise ValueError("a roll needs %d fields, got %d" % (ROLL_FIELD_COUNT, len(roll)))
    length, speed, moisture, width, defects = roll
    if length <= 0:
        raise ValueError("roll length must be positive")
    if defects < 0:
        raise ValueError("defect count cannot be negative")
    return length, speed, moisture, width, defects


def score_roll(speed, defects):
    """Grade a single roll from its running speed and defect count."""
    if speed > ABSOLUTE_MAX_SPEED:
        return OVERSPEED_SCORE
    if speed > BASE_SPEED_LIMIT:
        penalty = OVERSPEED_DEFECT_PENALTY
    else:
        penalty = DEFECT_PENALTY
    return max(PERFECT_SCORE - defects * penalty, MIN_SCORE)


def spec_notes(moisture, width):
    """Describe how far a roll drifts from the mill's nominal sheet spec."""
    notes = []
    if abs(width - NORMAL_WIDTH) > WIDTH_TOLERANCE:
        notes.append("width %g off nominal %d" % (width, NORMAL_WIDTH))
    if abs(moisture - IDEAL_MOISTURE) > MOISTURE_TOLERANCE:
        notes.append("moisture %g off ideal %d" % (moisture, IDEAL_MOISTURE))
    return notes


def evaluate(rolls):
    """Return (score, passed) for every roll in the list."""
    results = []
    for roll in rolls:
        _length, speed, _moisture, _width, defects = validate_roll(roll)
        score = score_roll(speed, defects)
        results.append((score, score > PASS_THRESHOLD))
    return results


def format_report(rolls):
    """Human readable summary of the graded rolls."""
    lines = []
    for index, (roll, (score, passed)) in enumerate(zip(rolls, evaluate(rolls)), start=1):
        _length, speed, moisture, width, _defects = validate_roll(roll)
        details = spec_notes(moisture, width)
        if speed > ABSOLUTE_MAX_SPEED:
            details.append("speed above absolute max %d" % ABSOLUTE_MAX_SPEED)
        elif speed > BASE_SPEED_LIMIT:
            details.append("speed above base limit %d" % BASE_SPEED_LIMIT)
        status = "PASS" if passed else "FAIL"
        suffix = " (" + "; ".join(details) + ")" if details else ""
        lines.append("Roll %d: score %d %s%s" % (index, score, status, suffix))
    return "\n".join(lines)


def main():
    rolls = [
        (2000, 1100, 5, 400, 2),
        (1500, 950, 6.2, 390, 4),
        (1800, 1250, 5, 400, 0),
        (2200, 800, 5, 400, 7),
    ]
    print(evaluate(rolls))
    print(format_report(rolls))


if __name__ == "__main__":
    main()

