MAX_SLING_CAPACITY = 4000.0
PINE_DENSITY = 40.0
OAK_DENSITY = 50.0
FUEL_RESERVE_WEIGHT = 500.0
SAFETY_MARGIN_RATE = 0.10
MIN_VOLUME = 0.0

WOOD_DENSITIES = {}
WOOD_DENSITIES["pine"] = PINE_DENSITY
WOOD_DENSITIES["oak"] = OAK_DENSITY


def density_for(wood_type):
    key = str(wood_type).strip().lower()
    if key not in WOOD_DENSITIES:
        known = ", ".join(sorted(WOOD_DENSITIES))
        raise ValueError("unknown wood type %r (known: %s)" % (wood_type, known))
    return WOOD_DENSITIES[key]


def wood_weight(wood_type, volume):
    if isinstance(volume, bool) or not isinstance(volume, (int, float)):
        raise TypeError("volume must be a number, got %r" % (volume,))
    if volume < MIN_VOLUME:
        raise ValueError("volume must be at least %.1f" % MIN_VOLUME)
    return float(volume) * density_for(wood_type)


def safety_margin(weight):
    return weight * SAFETY_MARGIN_RATE


def total_load(weight):
    return weight + FUEL_RESERVE_WEIGHT + safety_margin(weight)


def plan(trees):
    results = []
    for tree in trees:
        wood_type, volume = tree
        load = total_load(wood_weight(wood_type, volume))
        results.append((load, load <= MAX_SLING_CAPACITY))
    return results


def format_report(trees, results):
    lines = []
    for (wood_type, volume), (load, liftable) in zip(trees, results):
        if liftable:
            status = "OK, spare %.1f kg" % (MAX_SLING_CAPACITY - load)
        else:
            status = "OVER by %.1f kg" % (load - MAX_SLING_CAPACITY)
        lines.append("%-5s %6.1f m3 -> %8.1f kg  %s" % (wood_type, volume, load, status))
    return "\n".join(lines)


def main():
    trees = [("pine", 50), ("oak", 60), ("pine", 0), ("oak", 80)]
    results = plan(trees)
    print(format_report(trees, results))
    liftable = sum(1 for _, ok in results if ok)
    print("%d of %d slings within %.1f kg" % (liftable, len(results), MAX_SLING_CAPACITY))
    heaviest = max(load for load, _ in results)
    print("heaviest planned load: %.1f kg (reserve %.1f kg included)"
          % (heaviest, FUEL_RESERVE_WEIGHT))
    print("safety margin applied: %.0f%%" % (SAFETY_MARGIN_RATE * 100))


if __name__ == "__main__":
    main()

