BASE_AIR_EXCHANGE_RATE = 5
MAX_PASSENGER_LIMIT = 500
OVERCROWD_CO2_PENALTY = 200
PURGE_SPEED_BOOST = 20


def adjusted_co2(passengers, co2):
    """Return the carbon dioxide reading corrected for overcrowding."""
    if passengers > MAX_PASSENGER_LIMIT:
        return co2 + OVERCROWD_CO2_PENALTY
    return co2


def fan_speed_for(level):
    """Map an adjusted carbon dioxide level onto a fan speed."""
    if level > EMERGENCY_PURGE_LEVEL:
        return HIGH_FAN_SPEED + PURGE_SPEED_BOOST
    if level > CO2_THRESHOLD:
        return HIGH_FAN_SPEED
    return NORMAL_FAN_SPEED


def air_exchange(speed):
    """Air volume exchanged per minute, scaled from the base rate."""
    return BASE_AIR_EXCHANGE_RATE * speed / NORMAL_FAN_SPEED


def regulate(stations):
    results = []
    for passengers, co2 in stations:
        if passengers < 0 or co2 < 0:
            raise ValueError("passenger and carbon dioxide readings must be positive")
        level = adjusted_co2(passengers, co2)
        speed = fan_speed_for(level)
        results.append((speed, speed > HIGH_FAN_SPEED))
    return results


def report(stations, readings):
    lines = []
    for index, ((passengers, co2), (speed, purge)) in enumerate(zip(stations, readings), 1):
        level = adjusted_co2(passengers, co2)
        if purge:
            state = "EMERGENCY PURGE"
        elif speed == HIGH_FAN_SPEED:
            state = "high ventilation"
        else:
            state = "normal ventilation"
        crowding = "over capacity" if passengers > MAX_PASSENGER_LIMIT else "within capacity"
        lines.append(
            "Station {0}: {1} passengers ({2}), CO2 {3} ppm, fan {4}%, "
            "{5:.1f} units/min air exchange -> {6}".format(
                index, passengers, crowding, level, speed, air_exchange(speed), state
            )
        )
    return "\n".join(lines)


def main():
    stations = [(600, 1100), (120, 640), (480, 950), (520, 1050), (500, EMERGENCY_PURGE_LEVEL)]
    readings = regulate(stations)
    print(readings)
    print(report(stations, readings))
    purges = sum(1 for _, purge in readings if purge)
    print("Stations purging: {0} of {1}".format(purges, len(stations)))
    print("Idle baseline exchange: {0} units/min".format(BASE_AIR_EXCHANGE_RATE))


