HEAVY_START_VOLUME = 25.0
LIGHT_START_VOLUME = 10.0
BUFF_AREA_LENGTH = 40
BREAKDOWN_RATE_PER_GAME = 0.2
MINIMUM_ACCEPTABLE_VOLUME = 5.0
EXTRA_BUFF_PENALTY = 2.0
VOLUME_DECIMALS = 2

START_VOLUMES = {"heavy": HEAVY_START_VOLUME, "light": LIGHT_START_VOLUME}


def starting_volume(pattern):
    """Return the starting oil volume for a named pattern."""
    key = str(pattern).strip().lower()
    if key not in START_VOLUMES:
        raise ValueError("unknown oil pattern: %r" % (pattern,))
    return START_VOLUMES[key]


def check_games(games):
    """Validate and normalise a games-played count."""
    if isinstance(games, bool) or not isinstance(games, int):
        raise TypeError("games played must be an int, got %r" % (games,))
    if games < 0:
        raise ValueError("games played cannot be negative: %d" % games)
    return games


def remaining_volume(pattern, games):
    """Oil left after `games` games on `pattern`, including buff-area wear."""
    volume = starting_volume(pattern) - BREAKDOWN_RATE_PER_GAME * check_games(games)
    if games > BUFF_AREA_LENGTH:
        volume -= EXTRA_BUFF_PENALTY
    return round(volume, VOLUME_DECIMALS)


def analyze(lanes):
    """Map (pattern, games) pairs to (remaining volume, below minimum) pairs."""
    results = []
    for pattern, games in lanes:
        volume = remaining_volume(pattern, games)
        results.append((volume, volume < MINIMUM_ACCEPTABLE_VOLUME))
    return results


def format_report(lanes, results):
    """Build a human-readable line per analysed lane."""
    lines = []
    for (pattern, games), (volume, needs_oil) in zip(lanes, results):
        status = "RE-OIL" if needs_oil else "ok"
        note = " (past buff length)" if games > BUFF_AREA_LENGTH else ""
        lines.append(
            "%-6s %3d games: %6.2f of %5.2f units -> %s%s"
            % (pattern, games, volume, starting_volume(pattern), status, note)
        )
    return lines


def main():
    lanes = [("heavy", 10), ("light", 0), ("heavy", 45), ("light", 41), ("heavy", 120)]
    results = analyze(lanes)
    print(results)
    for line in format_report(lanes, results):
        print(line)
    flagged = sum(1 for _, needs_oil in results if needs_oil)
    print(
        "%d of %d lanes below the %.1f unit minimum"
        % (flagged, len(results), MINIMUM_ACCEPTABLE_VOLUME)
    )
    worst = min(volume for volume, _ in results)
    if worst < MINIMUM_ACCEPTABLE_VOLUME:
        print("driest lane at %.2f units; strip and re-oil before league play" % worst)


if __name__ == "__main__":
    main()

