WARNING_FLASH_INTERVAL = 10
EMERGENCY_FLASH_INTERVAL = 3
BASE_CANDELA = 1_000_000
FOG_MULTIPLIER = 2
MAX_ROTATION_SPEED = 6
MIN_BATTERY_RESERVE = 20
FOG_VISIBILITY_THRESHOLD = 2
MAX_RETRIES = 3
DEFAULT_TIMEOUT = 5.0


def validate(lights):
    """Return the readings as (visibility, battery) float/int pairs, rejecting bad rows."""
    cleaned = []
    for index, reading in enumerate(lights):
        if len(reading) != 2:
            raise ValueError("reading %d must hold visibility and battery" % index)
        visibility, battery = reading
        if visibility < 0:
            raise ValueError("reading %d has negative visibility" % index)
        if not 0 <= battery <= 100:
            raise ValueError("reading %d has battery outside 0..100" % index)
        cleaned.append((visibility, battery))
    return cleaned


def configure(lights):
    """Map each (visibility, battery) reading to a (candela, interval) pair."""
    settings = []
    for visibility, battery in validate(lights):
        if battery < MIN_BATTERY_RESERVE:
            settings.append((BASE_CANDELA // 2, WARNING_FLASH_INTERVAL))
        elif visibility < FOG_VISIBILITY_THRESHOLD:
            settings.append((BASE_CANDELA * FOG_MULTIPLIER, EMERGENCY_FLASH_INTERVAL))
        else:
            settings.append((BASE_CANDELA, WARNING_FLASH_INTERVAL))
    return settings


def rotation_speed(interval):
    """Rotations per minute implied by a flash interval, capped by the drive motor."""
    speed = 60 // interval
    return min(speed, MAX_ROTATION_SPEED)


def acquire(sensor, attempts=MAX_RETRIES, timeout=DEFAULT_TIMEOUT):
    """Poll a sensor callable until it yields a reading, then return it."""
    for attempt in range(attempts):
        reading = sensor(timeout * (attempt + 1))
        if reading is not None:
            return reading
    raise RuntimeError("sensor silent after %d attempts" % attempts)


def report(settings):
    """Render one human-readable line per configured lamp."""
    lines = []
    for candela, interval in settings:
        note = "emergency" if interval == EMERGENCY_FLASH_INTERVAL else "warning"
        lines.append(
            "%9d cd | %2ds (%s) | %d rpm"
            % (candela, interval, note, rotation_speed(interval))
        )
    return "\n".join(lines)


def main():
    log = [(1, 25), (4, 80), (7, 12), (0, 19)]
    flaky = iter([None, (3, 55)])

    def sensor(timeout):
        reading = next(flaky, None)
        if reading is None and timeout < DEFAULT_TIMEOUT * MAX_RETRIES:
            return None
        return reading

    log.append(acquire(sensor))
    print(configure(log))
    print(report(configure(log)))


if __name__ == "__main__":
    main()

