TARGET_HUNTING_WEIGHT = 800
MIN_FLIGHT_DISTANCE = 50
OPTIMAL_LURE_SPEED = 30
WEIGHT_VARIANCE_PENALTY = 5
WEIGHT_VARIANCE_STEP = 10
SHORT_FLIGHT_PENALTY = 10
PERFECT_READINESS_SCORE = 100
MIN_PASS_SCORE = 80
STAMINA_SPEED_REDUCTION = 10


def validate_record(record):
    """Unpack and check one (weight, distance) measurement pair."""
    try:
        weight, distance = record
    except (TypeError, ValueError):
        raise ValueError("each bird must be a (weight, distance) pair: %r" % (record,))
    if not isinstance(weight, (int, float)) or not isinstance(distance, (int, float)):
        raise ValueError("weight and distance must be numeric: %r" % (record,))
    if weight <= 0 or distance < 0:
        raise ValueError("weight must be positive and distance non-negative: %r" % (record,))
    return weight, distance


def score_bird(weight, distance):
    """Readiness score for a single bird, starting from a perfect score."""
    score = PERFECT_READINESS_SCORE
    variance = abs(weight - TARGET_HUNTING_WEIGHT)
    score -= int(variance // WEIGHT_VARIANCE_STEP) * WEIGHT_VARIANCE_PENALTY
    if distance < MIN_FLIGHT_DISTANCE:
        score -= SHORT_FLIGHT_PENALTY
    return max(score, 0)


def assess(birds):
    """Return [(score, passed), ...] for a list of (weight, distance) pairs."""
    results = []
    for record in birds:
        weight, distance = validate_record(record)
        score = score_bird(weight, distance)
        results.append((score, score >= MIN_PASS_SCORE))
    return results


def recommended_lure_speed(distance):
    """Slow the lure down while a bird is still building flight stamina."""
    if distance < MIN_FLIGHT_DISTANCE:
        return OPTIMAL_LURE_SPEED - STAMINA_SPEED_REDUCTION
    return OPTIMAL_LURE_SPEED


def training_plan(weight, distance, score):
    """Drill notes derived from the measurements and the readiness score."""
    notes = []
    if score >= MIN_PASS_SCORE:
        notes.append("maintenance flights at lure speed %d" % OPTIMAL_LURE_SPEED)
    else:
        notes.append("remedial work at lure speed %d" % recommended_lure_speed(distance))
    if weight > TARGET_HUNTING_WEIGHT:
        notes.append("reduce rations by %d units" % (weight - TARGET_HUNTING_WEIGHT))
    elif weight < TARGET_HUNTING_WEIGHT:
        notes.append("increase rations by %d units" % (TARGET_HUNTING_WEIGHT - weight))
    if distance < MIN_FLIGHT_DISTANCE:
        notes.append("extend flights to at least %d" % MIN_FLIGHT_DISTANCE)
    return "; ".join(notes)


def format_report(birds, results):
    lines = []
    for index, ((weight, distance), (score, passed)) in enumerate(zip(birds, results), 1):
        verdict = "PASS" if passed else "FAIL (needs %d)" % MIN_PASS_SCORE
        lines.append("Bird %d: %d/%d %s" % (index, score, PERFECT_READINESS_SCORE, verdict))
        lines.append("    " + training_plan(weight, distance, score))
    return "\n".join(lines)


def main():
    birds = [(820, 60), (800, 55), (745, 40), (900, 70)]
    results = assess(birds)
    print(results)
    print(format_report(birds, results))


if __name__ == "__main__":
