OPTIMAL_VINEGAR_RATIO = 0.1
OPTIMAL_SUGAR_RATIO = 0.05
TARGET_COOLING_TEMPERATURE = 35
STANDARD_HYDRATION_TIME = 30
TEMPERATURE_VARIANCE_PENALTY = 2
STARTING_QUALITY_SCORE = 50
QUALITY_PASS_THRESHOLD = 0.0
MIN_RICE_WEIGHT = 1.0


def vinegar_penalty(rice_weight, vinegar_weight):
    return abs(vinegar_weight - rice_weight * OPTIMAL_VINEGAR_RATIO)


def sugar_penalty(rice_weight, sugar_weight):
    return abs(sugar_weight - rice_weight * OPTIMAL_SUGAR_RATIO)


def temperature_penalty(temperature):
    offset = abs(temperature - TARGET_COOLING_TEMPERATURE)
    return offset * TEMPERATURE_VARIANCE_PENALTY


def score_batch(rice_weight, vinegar_weight, sugar_weight, temperature):
    if rice_weight < MIN_RICE_WEIGHT:
        raise ValueError("rice weight must be at least %g g" % MIN_RICE_WEIGHT)
    if vinegar_weight < 0 or sugar_weight < 0:
        raise ValueError("ingredient weights cannot be negative")
    score = float(STARTING_QUALITY_SCORE)
    score -= vinegar_penalty(rice_weight, vinegar_weight)
    score -= sugar_penalty(rice_weight, sugar_weight)
    score -= temperature_penalty(temperature)
    return round(score, 2)


def prepare(batches):
    results = []
    for rice_weight, vinegar_weight, sugar_weight, temperature in batches:
        score = score_batch(rice_weight, vinegar_weight, sugar_weight, temperature)
        results.append((score, score > QUALITY_PASS_THRESHOLD))
    return results


def hydration_schedule(batches):
    """Start minute of each batch, assuming batches hydrate one after another."""
    return [index * STANDARD_HYDRATION_TIME for index in range(len(batches))]


def format_report(batches, results, schedule):
    lines = []
    for batch, (score, accepted) in zip(batches, results):
        start = schedule[len(lines)]
        verdict = "serve" if accepted else "discard"
        drift = batch[3] - TARGET_COOLING_TEMPERATURE
        lines.append(
            "t+%3d min | rice %6.0f g | score %6.2f | drift %+d C | %s"
            % (start, batch[0], score, drift, verdict)
        )
    finish = schedule[-1] + STANDARD_HYDRATION_TIME if schedule else 0
    lines.append("all batches hydrated by t+%d min" % finish)
    return "\n".join(lines)


def main():
    batches = [
        (1000, 100, 50, 37),
        (1000, 100, 50, TARGET_COOLING_TEMPERATURE),
        (500, 90, 10, 60),
    ]
    results = prepare(batches)
    print(results)
    print(format_report(batches, results, hydration_schedule(batches)))


