text_nat:
IDEAL_PLATEN_HARDNESS = 90
OPTIMAL_KEY_TRAVEL = 15
MIN_RIBBON_TENSION = 5
MARGIN_BELL_THRESHOLD = 10
HARDNESS_VARIANCE_DEDUCTION = 0.5
MAX_SERVICE_SCORE = 100.0
TRAVEL_PENALTY = 5.0
EXPECTED_FIELDS = 3


def _parse_machine(machine):
    """Turn one raw machine record into a (hardness, travel, tension) tuple."""
    values = tuple(machine)
    if len(values) != EXPECTED_FIELDS:
        raise ValueError(
            "each machine needs %d values (hardness, travel, tension), got %d"
            % (EXPECTED_FIELDS, len(values))
        )
    for value in values:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("machine measurements must be numeric: %r" % (machine,))
    return values


def score_machine(hardness, travel, tension):
    """Service score plus replacement flag for a single typewriter."""
    score = MAX_SERVICE_SCORE
    score -= abs(hardness - IDEAL_PLATEN_HARDNESS) * HARDNESS_VARIANCE_DEDUCTION
    if travel != OPTIMAL_KEY_TRAVEL:
        score -= TRAVEL_PENALTY
    return score, tension < MIN_RIBBON_TENSION


def repair(machines):
    """Evaluate every machine record and return [(score, needs_replacement)]."""
    results = []
    for machine in machines:
        hardness, travel, tension = _parse_machine(machine)
        results.append(score_machine(hardness, travel, tension))
    return results


def needs_bell_warning(score):
    """A machine drifting more than the bell threshold from perfect is flagged."""
    return MAX_SERVICE_SCORE - score > MARGIN_BELL_THRESHOLD


def format_report(machines, results):
    lines = []
    for index, ((hardness, travel, tension), (score, replace)) in enumerate(
        zip(machines, results), start=1
    ):
        notes = []
        if replace:
            notes.append("ribbon tension %g below %g" % (tension, MIN_RIBBON_TENSION))
        if travel != OPTIMAL_KEY_TRAVEL:
            notes.append("key travel %g off %g" % (travel, OPTIMAL_KEY_TRAVEL))
        if hardness != IDEAL_PLATEN_HARDNESS:
            notes.append("platen hardness %g off %g" % (hardness, IDEAL_PLATEN_HARDNESS))
        if needs_bell_warning(score):
            notes.append("margin bell warning")
        summary = "; ".join(notes) if notes else "within tolerance"
        lines.append("machine %d: score %.1f/%.0f - %s"
                     % (index, score, MAX_SERVICE_SCORE, summary))
    return "\n".join(lines)


def main():
    batch = [(80, 15, 4), (90, 15, 6), (72, 12, 5), (91, 15, 9)]
    results = repair(batch)
    print(results)
    print(format_report(batch, results))
    flagged = sum(1 for score, _replace in results if needs_bell_warning(score))
    print("machines past the %g point bell threshold: %d"
          % (MARGIN_BELL_THRESHOLD, flagged))


if __name__ == "__main__":
    main()

