def _validate(count, index):
    if isinstance(count, bool) or not isinstance(count, int):
        raise TypeError("traffic[%d] must be an integer, got %r" % (index, count))
    if count < 0:
        raise ValueError("traffic[%d] must not be negative, got %d" % (index, count))
    return count


def motor_power(count):
    if count == 0:
        return STANDBY_POWER_WATTS
    power = BASE_POWER_WATTS + count * WATTS_PER_ITEM
    if power > MAX_CAPACITY_WATTS:
        return MAX_CAPACITY_WATTS
    return power


def calculate(traffic):
    readings = []
    for index, count in enumerate(traffic):
        items = _validate(count, index)
