    if volume <= 0:
        raise ValueError("tank volume must be positive, got %r" % (volume,))
    if occupants < MIN_OCCUPANTS:
        raise ValueError("a household needs at least %d occupant(s), got %r"
                         % (MIN_OCCUPANTS, occupants))


