def annual_accumulation(occupants):
    return BASE_RATE_GALLONS_PER_PERSON_YEAR * occupants * DISPOSAL_RATE_MULTIPLIER


def usable_sludge_volume(volume):
    return volume * SLUDGE_THRESHOLD_FRACTION


def pumping_interval(volume, occupants):
    years = usable_sludge_volume(volume) / annual_accumulation(occupants)
    interval = int(math.floor(years))
    if interval < MIN_INTERVAL_YEARS:
        return MIN_INTERVAL_YEARS
    if interval > MAX_INTERVAL_YEARS:
        return MAX_INTERVAL_YEARS
    return interval


def lifetime_inspection_fee(interval):
    return interval * INSPECTION_FEE_PER_YEAR


def analyze(households):
