MIN_WIND_KNOTS = 12
MAX_WIND_KNOTS = 30
BASE_WIND_KNOTS = 20
BASE_WEIGHT_KG = 75
BASE_KITE_SIZE_SQM = 10.0
WEIGHT_STEP_KG = 5.0
SIZE_PER_WEIGHT_STEP_SQM = 0.5
WIND_STEP_KNOTS = 2.0
SIZE_PER_WIND_STEP_SQM = 1.0
UNSAFE_RESULT = "unsafe"
SIZE_DECIMALS = 2


def parse_condition(entry):
    """Turn one (wind, weight) pair into validated floats."""
    wind, weight = entry
    wind = float(wind)
    weight = float(weight)
    if weight <= 0:
        raise ValueError("rider weight must be positive: %r" % (weight,))
    if wind < 0:
        raise ValueError("wind speed cannot be negative: %r" % (wind,))
    return wind, weight


def is_safe(wind):
    """A session is safe only inside the advertised wind window."""
    return MIN_WIND_KNOTS <= wind <= MAX_WIND_KNOTS


def kite_size(wind, weight):
    """Recommended kite area in square meters for a safe wind speed."""
    size = BASE_KITE_SIZE_SQM
    if weight > BASE_WEIGHT_KG:
        weight_steps = (weight - BASE_WEIGHT_KG) // WEIGHT_STEP_KG
        size += weight_steps * SIZE_PER_WEIGHT_STEP_SQM
    if wind < BASE_WIND_KNOTS:
        wind_steps = (BASE_WIND_KNOTS - wind) // WIND_STEP_KNOTS
        size += wind_steps * SIZE_PER_WIND_STEP_SQM
    return round(size, SIZE_DECIMALS)


def assess(conditions):
    """Map each (wind, weight) pair to a kite size or the unsafe marker."""
    results = []
    for entry in conditions:
        wind, weight = parse_condition(entry)
        if is_safe(wind):
            results.append(kite_size(wind, weight))
        else:
            results.append(UNSAFE_RESULT)
    return results


def format_result(entry, result):
    wind, weight = parse_condition(entry)
    if result == UNSAFE_RESULT:
        if wind < MIN_WIND_KNOTS:
            reason = "below %g kt" % MIN_WIND_KNOTS
        else:
            reason = "above %g kt" % MAX_WIND_KNOTS
        return "%g kt / %g kg -> unsafe (%s)" % (wind, weight, reason)
    return "%g kt / %g kg -> %.1f m2" % (wind, weight, result)


def report(conditions):
    """Human readable lines for a whole batch of conditions."""
    results = assess(conditions)
    return [format_result(entry, result)
            for entry, result in zip(conditions, results)]


def main():
    conditions = [(18, 80), (10, 75), (20, 75), (26, 95), (34, 70), (12, 60)]
    print(assess(conditions))
    for line in report(conditions):
        print(line)


if __name__ == "__main__":
    main()

