TARGET_TOUCHES = 15
CARD_PENALTY = 1
MIN_SCORE = 0
DOMINANT_MARGIN = 5
DOMINANT_POINTS = 3
WIN_POINTS = 2
DRAW_POINTS = 1
LOSS_POINTS = 0
BOUT_FIELDS = 3


def adjusted_score(touches, cards):
    """Apply card deductions to a touch count, clamped at the floor."""
    return max(MIN_SCORE, touches - cards * CARD_PENALTY)


def validate_bout(bout):
    """Return a validated (touches, opponent, cards) triple."""
    if len(bout) != BOUT_FIELDS:
        raise ValueError("each bout needs touches, opponent touches and cards")
    touches, opponent, cards = bout
    for value in (touches, opponent, cards):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("bout values must be integers")
    if touches < MIN_SCORE or opponent < MIN_SCORE or cards < MIN_SCORE:
        raise ValueError("bout values must not be negative")
    if touches > TARGET_TOUCHES or opponent > TARGET_TOUCHES:
        raise ValueError("a bout stops at %d touches" % TARGET_TOUCHES)
    return touches, opponent, cards


def bout_points(bout):
    """Ranking points earned by the fencer in a single bout."""
    touches, opponent, cards = validate_bout(bout)
    own = adjusted_score(touches, cards)
    if own > opponent:
        if own - opponent >= DOMINANT_MARGIN:
            return DOMINANT_POINTS
        return WIN_POINTS
    if own == opponent:
        return DRAW_POINTS
    return LOSS_POINTS


def score(bouts):
    """Ranking points for every bout in the supplied sequence."""
    return [bout_points(bout) for bout in bouts]


def describe(points):
    """Human readable label for a ranking point total of one bout."""
    if points == DOMINANT_POINTS:
        return "dominant win"
    if points == WIN_POINTS:
        return "win"
    if points == DRAW_POINTS:
        return "draw"
    return "loss"


def format_report(bouts):
    """Build a per-bout report plus the season total."""
    points = score(bouts)
    lines = []
    for index, (bout, earned) in enumerate(zip(bouts, points), start=1):
        touches, opponent, cards = bout
        lines.append(
            "Bout %d: %d-%d (%d card(s), adjusted %d/%d) -> %d pts, %s"
            % (index, touches, opponent, cards,
               adjusted_score(touches, cards), TARGET_TOUCHES,
               earned, describe(earned))
        )
    lines.append("Total ranking points: %d" % sum(points))
    return "\n".join(lines)


def main():
    season = [(15, 8, 1), (12, 15, 0), (15, 14, 0), (14, 13, 1), (2, 15, 3)]
    print(score(season))
    print(format_report(season))


if __name__ == "__main__":
    main()

