import math

GRAVITY = 9.8
BASE_DWELL_TIME = 0.2
FATIGUE_PROP_THRESHOLD = 5
FATIGUE_DWELL_PENALTY = 0.05
MAX_THROW_RATE = 7.0
MIN_PROPS = 1
RATE_DECIMALS = 2


def validate_pattern(height, props):
    if not isinstance(props, int):
        raise TypeError("prop count must be an integer")
    if props < MIN_PROPS:
        raise ValueError("a pattern needs at least %d prop" % MIN_PROPS)
    if height <= 0:
        raise ValueError("peak throw height must be positive")
    return float(height), props


def dwell_time(props):
    dwell = BASE_DWELL_TIME
    if props > FATIGUE_PROP_THRESHOLD:
        dwell += FATIGUE_DWELL_PENALTY
    return dwell


def flight_time(height):
    return 2.0 * math.sqrt(2.0 * height / GRAVITY)


def cycle_time(height, props):
    return flight_time(height) + dwell_time(props)


def truncate_rate(rate):
    factor = 10 ** RATE_DECIMALS
    return math.floor(rate * factor) / factor


def throw_rate(height, props):
    rate = props / cycle_time(height, props)
    return truncate_rate(min(rate, MAX_THROW_RATE))


def analyze(patterns):
    rates = []
    for height, props in patterns:
        clean_height, clean_props = validate_pattern(height, props)
        rates.append(throw_rate(clean_height, clean_props))
    return rates


def format_report(patterns, rates):
    lines = []
    for (height, props), rate in zip(patterns, rates):
        note = "at human limit" if rate >= MAX_THROW_RATE else "sustainable"
        if props > FATIGUE_PROP_THRESHOLD:
            note += ", fatigued dwell"
        lines.append(
            "{0} props at {1:.2f} m: {2:.{3}f} throws/s ({4})".format(
                props, height, rate, RATE_DECIMALS, note
            )
        )
    return "\n".join(lines)


def main():
    patterns = [(1.5, 5), (0.8, 7), (2.4, 9), (0.35, 3)]
    rates = analyze(patterns)
