OPTIMAL_LAUNCH_ANGLE = 45.0
MIN_LAUNCH_ANGLE = 0.0
MAX_LAUNCH_ANGLE = 90.0
MIN_WIND_SPEED = 0.0
BASE_RETURN_RADIUS = 20.0
RADIUS_PER_DEGREE = 0.5
MINIMUM_RADIUS = 10.0
WIND_DISPLACEMENT_PER_UNIT = 2.0
SKILL_BONUS_FACTOR = 0.10
MAX_CATCHABLE_OFFSET = 5.0
REPORT_PRECISION = 2


def validate_throw(wind_speed, angle):
    """Reject throws that are outside the physically modelled envelope."""
    if wind_speed < MIN_WIND_SPEED:
        raise ValueError("wind speed must be at least %g m/s" % MIN_WIND_SPEED)
    if angle < MIN_LAUNCH_ANGLE or angle > MAX_LAUNCH_ANGLE:
        raise ValueError(
            "launch angle must lie between %g and %g degrees"
            % (MIN_LAUNCH_ANGLE, MAX_LAUNCH_ANGLE)
        )


def angle_deviation(angle):
    """Degrees away from the ideal launch angle."""
    return abs(angle - OPTIMAL_LAUNCH_ANGLE)


def return_radius(angle):
    """Radius of the circular flight path for a given launch angle."""
    grown = BASE_RETURN_RADIUS + RADIUS_PER_DEGREE * angle_deviation(angle)
    return max(MINIMUM_RADIUS, grown)


def wind_displacement(wind_speed):
    """Sideways shift of the flight path centre, softened by the skill bonus."""
    raw = wind_speed * WIND_DISPLACEMENT_PER_UNIT
    return raw * (1.0 - SKILL_BONUS_FACTOR)


