OPTIMAL_FLOW = 30.0
MIN_CLEARING_FLOW = 15.0
MAX_SAFE_FLOW = 45.0
OPTIMAL_FEED = 10.0
BASE_RETENTION = 90.0
PENALTY_PER_EXTRA_KG = 5.0
BAD_FLOW_PENALTY = 20.0
MIN_RETENTION = 10.0


def _check_sluice(index, sluice):
    try:
        flow, feed = sluice
    except (TypeError, ValueError):
        raise ValueError("sluice %d must be a (flow, feed) pair" % index)
    if not isinstance(flow, (int, float)) or not isinstance(feed, (int, float)):
        raise TypeError("sluice %d has non-numeric readings" % index)
    if flow < 0 or feed < 0:
        raise ValueError("sluice %d has negative readings" % index)
    return float(flow), float(feed)


def retention(flow, feed):
    result = BASE_RETENTION
    excess_feed = feed - OPTIMAL_FEED
    if excess_feed > 0:
        result -= excess_feed * PENALTY_PER_EXTRA_KG
    if flow < MIN_CLEARING_FLOW or flow > MAX_SAFE_FLOW:
        result -= BAD_FLOW_PENALTY
    if result < MIN_RETENTION:
        return MIN_RETENTION
    return result


def optimize(sluices):
    retentions = []
    for index, sluice in enumerate(sluices):
        flow, feed = _check_sluice(index, sluice)
        retentions.append(retention(flow, feed))
    return retentions


def flow_advice(flow):
    if flow < MIN_CLEARING_FLOW:
        return "raise flow by %.1f L/s (sand is not clearing)" % (MIN_CLEARING_FLOW - flow)
    if flow > MAX_SAFE_FLOW:
        return "cut flow by %.1f L/s (gold is washing out)" % (flow - MAX_SAFE_FLOW)
    if flow != OPTIMAL_FLOW:
        return "trim flow by %+.1f L/s toward optimum" % (OPTIMAL_FLOW - flow)
    return "flow is at the optimum"


def feed_advice(feed):
    if feed > OPTIMAL_FEED:
        return "reduce feed by %.1f kg/min (riffles blocked)" % (feed - OPTIMAL_FEED)
    return "feed is within the %.1f kg/min optimum" % OPTIMAL_FEED


def format_report(sluices):
    lines = []
    for index, (sluice, value) in enumerate(zip(sluices, optimize(sluices)), start=1):
        flow, feed = _check_sluice(index - 1, sluice)
        lines.append("Sluice %d: %.1f L/s, %.1f kg/min -> %.1f%% retention"
                     % (index, flow, feed, value))
        lines.append("  flow: " + flow_advice(flow))
        lines.append("  feed: " + feed_advice(feed))
        if value <= MIN_RETENTION:
            lines.append("  warning: retention floored at %.1f%%" % MIN_RETENTION)
    return "\n".join(lines)


def main():
    readings = [(20, 12), (30, 10), (12, 9), (50, 18), (30, 40)]
    print(optimize(readings))
    print(format_report(readings))


if __name__ == "__main__":
    main()

