text_nat:
import os
import sys

CHUNK_SIZE = 1 << 16
NEWLINE = b"\n"
REPORT_WIDTH = 48
NAME_WIDTH = REPORT_WIDTH - 20
COUNT_WIDTH = 8
SIZE_WIDTH = REPORT_WIDTH - NAME_WIDTH - COUNT_WIDTH
ELLIPSIS = "... "
EXIT_OK = 0
EXIT_FAILURE = 1
EXIT_USAGE = 2


def count_lines_in_file(filepath):
    total = 0
    last_byte = b""
    with open(filepath, "rb") as handle:
        while True:
            chunk = handle.read(CHUNK_SIZE)
            if not chunk:
                break
            total += chunk.count(NEWLINE)
            last_byte = chunk[-1:]
    if last_byte and last_byte != NEWLINE:
        total += 1
    return total


def describe_file(filepath):
    return {
        "path": filepath,
        "lines": count_lines_in_file(filepath),
        "bytes": os.path.getsize(filepath),
    }


def _shorten(name):
    if len(name) > NAME_WIDTH:
        return name[: NAME_WIDTH - len(ELLIPSIS)] + ELLIPSIS
    return name


def _format_row(name, lines, size):
    return "{:<{n}}{:>{c}}{:>{s}}".format(
        _shorten(name), lines, size, n=NAME_WIDTH, c=COUNT_WIDTH, s=SIZE_WIDTH
    )


def format_report(entries):
    rows = [_format_row("FILE", "LINES", "BYTES"), "-" * REPORT_WIDTH]
    for entry in entries:
        rows.append(_format_row(os.path.basename(entry["path"]), entry["lines"], entry["bytes"]))
    rows.append("-" * REPORT_WIDTH)
    total_lines = sum(entry["lines"] for entry in entries)
    total_bytes = sum(entry["bytes"] for entry in entries)
    rows.append(_format_row("TOTAL", total_lines, total_bytes))
    return "\n".join(rows)


def main(argv):
    paths = argv[1:]
    if not paths:
        sys.stderr.write("usage: linecount FILE [FILE ...]\n")
        return EXIT_USAGE
    entries = []
    for path in paths:
        try:
            entries.append(describe_file(path))
        except OSError as exc:
            sys.stderr.write("skipping {}: {}\n".format(path, exc))
    if not entries:
        return EXIT_FAILURE
    sys.stdout.write(format_report(entries) + "\n")
    return EXIT_OK


if __name__ == "__main__":
    sys.exit(main(sys.argv))

