MAX_RETRIES = 5
DEFAULT_TIMEOUT = 30.0

TOO_HIGH = "Too high"
TOO_LOW = "Too low"
CORRECT = "Correct!"


def guess_number(secret_number, guess):
    if guess > secret_number:
        return TOO_HIGH
    if guess < secret_number:
        return TOO_LOW
    return CORRECT


def parse_transcript(text):
    entries = []
    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 2:
            raise ValueError("line %d: expected 'timestamp guess'" % lineno)
        timestamp = float(parts[0])
        guess = int(parts[1])
        if not MIN_GUESS <= guess <= MAX_GUESS:
            raise ValueError(
                "line %d: guess %d outside %d..%d" % (lineno, guess, MIN_GUESS, MAX_GUESS)
            )
        entries.append((timestamp, guess))
    return entries


def play_game(secret_number, transcript, timeout=DEFAULT_TIMEOUT):
    history = []
    previous = 0.0
    for timestamp, guess in transcript:
