            return {"outcome": "abandoned", "history": history}
        previous = timestamp
        verdict = guess_number(secret_number, guess)
        history.append((guess, verdict))
        if verdict == CORRECT:
            return {"outcome": "won", "history": history}
        if len(history) >= MAX_RETRIES:
            return {"outcome": "lost", "history": history}
    return {"outcome": "unfinished", "history": history}


