    if result["outcome"] == "abandoned":
        lines.append("  player idled longer than %.0fs" % DEFAULT_TIMEOUT)
    elif result["outcome"] == "lost":
        lines.append("  no luck within %d guesses" % MAX_RETRIES)
    return "\n".join(lines)


