"""Compute the squares of 1..n, with a small command-line driver."""

import sys

MAX_N = 100_000
PREVIEW_LIMIT = 8
PROMPT = "Enter a non-negative integer (n): "
EXIT_OK = 0
EXIT_BAD_INPUT = 2


def list_of_squares(n):
    """Return the squares of 1..n inclusive; an empty list when n <= 0."""
    if n <= 0:
        return []
    return [value * value for value in range(1, n + 1)]


def parse_n(text):
    """Convert a line of user input into a valid n, or raise ValueError."""
    stripped = text.strip()
    if not stripped:
        raise ValueError("empty input")
    value = int(stripped)
    if value < 0:
        raise ValueError("n must not be negative")
    if value > MAX_N:
        raise ValueError(f"n must not exceed {MAX_N}")
    return value


def format_report(n, squares):
    """Build a short human-readable summary of the computed squares."""
    if not squares:
        return f"n = {n}: no squares to show"
    body = ", ".join(str(square) for square in squares[:PREVIEW_LIMIT])
    if len(squares) > PREVIEW_LIMIT:
        body += f", ... (+{len(squares) - PREVIEW_LIMIT} more)"
    return f"n = {n}: [{body}]\nsum = {sum(squares)}, largest = {squares[-1]}"


def main(argv):
    if len(argv) > 1:
        sources = argv[1:]
    else:
        sys.stdout.write(PROMPT)
        sys.stdout.flush()
        line = sys.stdin.readline()
        if not line:
            print("no input received", file=sys.stderr)
            return EXIT_BAD_INPUT
        sources = [line]
    status = EXIT_OK
    for source in sources:
        try:
            n = parse_n(source)
        except ValueError as exc:
            print(f"bad input {source.strip()!r}: {exc}", file=sys.stderr)
            status = EXIT_BAD_INPUT
            continue
        print(format_report(n, list_of_squares(n)))
    return status


if __name__ == "__main__":
    sys.exit(main(sys.argv))

