import sys

maxSentenceLength = 4096
wordSeparator = " "
reportWidth = 72
exitSuccess = 0
exitFailure = 1


def validate_sentence(sentence):
    """Return the sentence unchanged, or raise if it cannot be processed."""
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a str, got %s" % type(sentence).__name__)
    if len(sentence) > maxSentenceLength:
        raise ValueError(
            "sentence is %d characters long; limit is %d"
            % (len(sentence), maxSentenceLength)
        )
    return sentence


def reverse_words(sentence):
    """Reverse the order of the words in the sentence, keeping words intact."""
    validate_sentence(sentence)
    words = sentence.split()
    words.reverse()
    return wordSeparator.join(words)


def read_sentences():
    """Read one sentence per line from standard input, ignoring blank lines."""
    sentences = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            sentences.append(line)
    return sentences


def format_report(results):
    """Render original/reversed pairs as a fixed-width text block."""
    header = " %d sentence(s) reversed " % len(results)
    lines = [header.center(reportWidth, "=")]
    for original, reversed_sentence in results:
        entry = "%s -> %s" % (original, reversed_sentence)
        if len(entry) > reportWidth:
            entry = entry[:reportWidth - 3] + "..."
        lines.append(entry)
    return "\n".join(lines)


def main(argv):
    sentences = argv[1:] or read_sentences()
    results = []
    rejected = 0
    for sentence in sentences:
        try:
            results.append((sentence, reverse_words(sentence)))
        except (TypeError, ValueError) as exc:
            print("skipping input: %s" % exc, file=sys.stderr)
            rejected += 1
    print(format_report(results))
    if rejected:
        return exitFailure
    return exitSuccess


if __name__ == "__main__":
    sys.exit(main(sys.argv))

