import sys
import time

MAX_RETRIES = 3
DEFAULT_TIMEOUT = 5.0
FIELD_SEPARATOR = ","
REPORT_TEMPLATE = "{count} value(s) read, smallest = {smallest}"
USAGE = (
    "usage: smallest.py [TIMEOUT] [RETRIES]\n"
    "  TIMEOUT  seconds to keep trying for a usable line\n"
    "  RETRIES  number of input lines to attempt\n"
    "reads whitespace/comma separated numbers from stdin"
)


def find_smallest(numbers):
    if not numbers:
        raise ValueError("cannot take the smallest of an empty list")
    smallest = numbers[0]
    for value in numbers[1:]:
        if value < smallest:
            smallest = value
    return smallest


def parse_numbers(text):
    tokens = text.replace(FIELD_SEPARATOR, " ").split()
    if not tokens:
        raise ValueError("no numbers on this line")
    numbers = []
    for token in tokens:
        try:
            numbers.append(int(token))
        except ValueError:
            try:
                numbers.append(float(token))
            except ValueError:
                raise ValueError(f"{token!r} is not a number")
    return numbers


def collect_readings(
    read_line,
    timeout=DEFAULT_TIMEOUT,
    max_retries=MAX_RETRIES,
):
    started = time.monotonic()
    problems = []
    for attempt in range(1, max_retries + 1):
        if time.monotonic() - started > timeout:
            raise TimeoutError(
                f"no usable input within {timeout}s ({attempt - 1} attempt(s) made)"
            )
        line = read_line()
        if not line:
            raise EOFError("input ended before a usable line arrived")
        try:
            return parse_numbers(line)
        except ValueError as exc:
            problems.append(f"attempt {attempt}: {exc}")
    raise ValueError("; ".join(problems))


def report(numbers):
    return REPORT_TEMPLATE.format(
        count=len(numbers),
        smallest=find_smallest(numbers),
    )


def main(argv):
    if "-h" in argv or "--help" in argv:
        print(USAGE)
        return 0
    timeout = DEFAULT_TIMEOUT
    retries = MAX_RETRIES
    if argv:
        timeout = float(argv[0])
    if len(argv) > 1:
        retries = int(argv[1])
    try:
        numbers = collect_readings(sys.stdin.readline, timeout, retries)
    except (ValueError, EOFError, TimeoutError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    print(report(numbers))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

