import sys

DEFAULT_LIMIT = 3
MAX_LIMIT = 1_000_000
MAX_RETRIES = 3
PREVIEW_COUNT = 6
LABEL_WIDTH = 8


def cubes_up_to(limit):
    """Return the cubes of 0..limit (inclusive) as a list of int."""
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise TypeError("limit must be an int, got %r" % (limit,))
    if limit < 0:
        raise ValueError("limit must be non-negative, got %d" % limit)
    return [n ** 3 for n in range(limit + 1)]


def parse_limit(text):
    """Turn a raw token into a limit this module is willing to expand."""
    stripped = text.strip()
    if not stripped:
        raise ValueError("blank input")
    try:
        value = int(stripped)
    except ValueError:
        raise ValueError("%r is not an integer" % stripped)
    if value < 0:
        raise ValueError("negative limit %d" % value)
    if value > MAX_LIMIT:
        raise ValueError("limit %d exceeds maximum %d" % (value, MAX_LIMIT))
    return value


def prompt_limit():
    """Ask the user for a limit, tolerating a few unusable answers."""
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            return parse_limit(input("limit [0-%d]: " % MAX_LIMIT))
        except ValueError as exc:
            print("attempt %d of %d rejected: %s" % (attempt, MAX_RETRIES, exc))
    raise ValueError("no usable limit after %d attempts" % MAX_RETRIES)


def format_report(limit, cubes_list):
    """Render a short summary of a computed cube list."""
    preview = ", ".join(str(c) for c in cubes_list[:PREVIEW_COUNT])
    if len(cubes_list) > PREVIEW_COUNT:
        preview += ", ..."
    rows = [
        ("limit", limit),
        ("count", len(cubes_list)),
        ("cubes", "[%s]" % preview),
        ("largest", cubes_list[-1]),
    ]
    return "\n".join("%-*s: %s" % (LABEL_WIDTH, name, value) for name, value in rows)


def main(argv):
    if len(argv) > 1:
        source = lambda: parse_limit(argv[1])
    elif sys.stdin.isatty():
        source = prompt_limit
    else:
        source = lambda: DEFAULT_LIMIT
    try:
        limit = source()
    except ValueError as exc:
        print("input error: %s" % exc)
        return 1
    print(format_report(limit, cubes_up_to(limit)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

