import sys

BLOCK_SEPARATOR = "\n\n"
ROW_SEPARATOR = "\n"
COLUMN_SEPARATOR = " "
VALUE_FORMAT = "{:.6g}"
ZERO_TOLERANCE = 1e-9
MAX_PREVIEW_ROWS = 20
TRUNCATION_NOTICE = "... {} more rows"
IDENTICAL_NOTICE = "matrices are identical within {:g}"
SHAPE_ERROR = "row counts differ: {} vs {}"
ROW_SHAPE_ERROR = "column counts differ in row {}: {} vs {}"


def parse_number(token):
    try:
        return int(token)
    except ValueError:
        return float(token)


def parse_matrix(block):
    rows = []
    for line in block.split(ROW_SEPARATOR):
        if line.strip():
            rows.append([parse_number(token) for token in line.split()])
    return rows


def parse_matrices(text):
    blocks = [block for block in text.split(BLOCK_SEPARATOR) if block.strip()]
    if len(blocks) != 2:
        raise ValueError("expected two matrices separated by a blank line")
    return parse_matrix(blocks[0]), parse_matrix(blocks[1])


def format_value(value):
    return VALUE_FORMAT.format(value)


def format_row(row):
    return COLUMN_SEPARATOR.join(format_value(value) for value in row)


def format_matrix(matrix):
    lines = [format_row(row) for row in matrix[:MAX_PREVIEW_ROWS]]
    hidden = len(matrix) - MAX_PREVIEW_ROWS
    if hidden > 0:
        lines.append(TRUNCATION_NOTICE.format(hidden))
    return ROW_SEPARATOR.join(lines)


def is_zero_matrix(matrix):
    return all(abs(value) <= ZERO_TOLERANCE for row in matrix for value in row)


def matrix_subtract(matrix1, matrix2):
    if len(matrix1) != len(matrix2):
        raise ValueError(SHAPE_ERROR.format(len(matrix1), len(matrix2)))
    result_matrix = []
    for index, (row1, row2) in enumerate(zip(matrix1, matrix2)):
        if len(row1) != len(row2):
            raise ValueError(
                ROW_SHAPE_ERROR.format(index, len(row1), len(row2)))
        result_matrix.append([a - b for a, b in zip(row1, row2)])
    return result_matrix


def main():
    left, right = parse_matrices(sys.stdin.read())
    difference = matrix_subtract(left, right)
    print(format_matrix(difference))
    if is_zero_matrix(difference):
        print(IDENTICAL_NOTICE.format(ZERO_TOLERANCE))


if __name__ == "__main__":
    main()

