CHANNEL_COUNT = 3
MIN_CHANNEL_VALUE = 0
MAX_CHANNEL_VALUE = 255
ASCII_RAMP = " .:-=+*#%@"
CELL_FORMAT = "%3d%s"


def validate_image(image_matrix):
    if not image_matrix or not all(image_matrix):
        raise ValueError("image must contain at least one pixel")
    width = len(image_matrix[0])
    for row in image_matrix:
        if len(row) != width:
            raise ValueError("all rows must have the same width")
        for pixel in row:
            if len(pixel) != CHANNEL_COUNT:
                raise ValueError("each pixel needs %d channels" % CHANNEL_COUNT)
            for value in pixel:
                if not MIN_CHANNEL_VALUE <= value <= MAX_CHANNEL_VALUE:
                    raise ValueError(
                        "channel out of range %d..%d"
                        % (MIN_CHANNEL_VALUE, MAX_CHANNEL_VALUE)
                    )


def average_channels(pixel):
    return sum(pixel) // CHANNEL_COUNT


def to_grayscale(image_matrix):
    validate_image(image_matrix)
    return [[average_channels(pixel) for pixel in row] for row in image_matrix]


def ramp_symbol(level):
    index = level * (len(ASCII_RAMP) - 1) // MAX_CHANNEL_VALUE
    return ASCII_RAMP[index]


def format_report(grayscale_image):
    lines = []
    for row in grayscale_image:
        lines.append(" ".join(CELL_FORMAT % (level, ramp_symbol(level)) for level in row))
    return "\n".join(lines)


def summarize(grayscale_image):
    levels = [level for row in grayscale_image for level in row]
    return {
        "pixels": len(levels),
        "darkest": min(levels),
        "brightest": max(levels),
        "mean": sum(levels) // len(levels),
    }


def main():
    frames = [
        [[[255, 0, 0], [0, 255, 0]]],
        [[[10, 20, 30]]],
        [[[0, 0, 0], [128, 128, 128]], [[255, 255, 255], [60, 90, 120]]],
    ]
    for number, frame in enumerate(frames, start=1):
        grayscale_image = to_grayscale(frame)
        stats = summarize(grayscale_image)
        print("frame %d -> %s" % (number, grayscale_image))
        print(format_report(grayscale_image))
        print(
            "pixels=%d darkest=%d brightest=%d mean=%d"
            % (stats["pixels"], stats["darkest"], stats["brightest"], stats["mean"])
        )


if __name__ == "__main__":
    main()

